# The four tools, with the versions their run scripts give. Each tool's statements go over one connection, as its user
# and database (an open node takes any user name).
BI_TOOLS = {"grafana": "Grafana 13.2.3", "metabase": "Metabase 0.64.1.6", "superset": "Superset 6.1.0", "dbeaver": "DBeaver 2.0.49"}

# Statements Postgres 16 itself refuses (psql at 127.0.0.1:5416 on the same data): key -> (why, the SQLSTATE Postgres gives).
# Pondra must refuse each one too, with the same SQLSTATE.
BI_PG_REFUSES = {
    "grafana:18": ("Grafana's $__interval macro, sent unquoted: 1d is a number with letters after it", "42601"),
    "dbeaver:G11": ("pgAgent's job list: the pgagent schema is not on this server", "42P01"),
    "dbeaver:G12": ("pgAgent's job classes: the same missing schema", "42P01"),
}

# Statements Pondra can't answer, where the fix belongs elsewhere: key -> why. Each one is kept as a failure in info.
BI_EXCEPTIONS = {
    "dbeaver:D5": "row_number() ... AS attnum beside a.*, which has an attnum of its own: DataFusion's schema then holds "
                   "attnum both qualified (a.attnum) and unqualified, so Pondra answers XX000 'ambiguous'",
}

# What Postgres 16 answers on the same data, written as literals (computed on a Postgres 16.15 server, database bi). One
# difference is Pondra's on purpose: a VARCHAR(n) column is text, as in DuckDB (Pondra keeps strings as one type and no
# declared length; the `pg_catalog` section checks it), so `note` reads text where Postgres 16 says character varying.
BI_GRAFANA_TABLES = ["regions", "sales", "sales_by_region", "crm.customers"]  # showTables, in the order its ORDER BY gives
BI_GRAFANA_SALES = [("amount", "double precision"), ("id", "bigint"), ("note", "text"), ("product", "text"),
                    ("qty", "integer"), ("ref", "uuid"), ("region", "text"), ("ts", "timestamp without time zone")]
BI_METABASE_TABLES = [("crm", "customers", "TABLE", None), ("public", "regions", "TABLE", None),
                      ("public", "sales", "TABLE", "one row a sale"), ("public", "sales_by_region", "VIEW", None)]
BI_METABASE_SALES = [("id", "int8", 0, True, None), ("ts", "timestamp", 1, False, None), ("region", "text", 2, False, None),
                     ("product", "text", 3, False, None), ("amount", "float8", 4, False, "in euros"),
                     ("qty", "int4", 5, False, None), ("ref", "uuid", 6, False, None), ("note", "text", 7, False, None)]
# Superset's time-range charts: [row count, digest] (bi_digest), by statement key.
BI_SUPERSET = {"superset:45": ("day", 356, "9cbded7090574f0e"), "superset:46": ("week", 56, "4149781711f54944"),
               "superset:47": ("month", 12, "ac21e38aff619dea"), "superset:48": ("hour", 8544, "4686040d6f2da882"),
               "superset:49": ("year", 4, "2c3b27d88ad11053"), "superset:50": ("quarter", 4, "2c3b27d88ad11053")}
BI_TYPE_NAMES = ["bool", "bytea", "char", "date", "float4", "float8", "int2", "int4", "int8", "interval", "json", "jsonb",
                 "numeric", "text", "timestamp", "timestamptz", "uuid", "varchar"]
BI_TYPE_REPEATS = {"_pg_user_mappings": 2}  # the one name Postgres 16 lists twice (in two schemas); every other name once
TS = "TIMESTAMP '2026-01-07 13:05:09.123456'"  # (a Wednesday)
BI_TO_CHAR = [(f"SELECT to_char({TS}, '{form}')", text) for form, text in [
    ("YYYY-MM-DD HH24:MI:SS", "2026-01-07 13:05:09"), ("YYYY-MM-DD HH24:MI:SS.US", "2026-01-07 13:05:09.123456"),
    ("DD Mon YYYY", "07 Jan 2026"), ("Day", "Wednesday"), ("yyyy-mm-dd", "2026-01-07"), ("FMMonth", "January"),
    ("HH12:MI AM", "01:05 PM"), ("IYYY-IW", "2026-02"), ("Q", "1"), ('YYYY"Q"Q', "2026Q1")]]
BI_TO_DATE = [
    ("SELECT to_char(to_date('07 Jan 2026', 'DD Mon YYYY'), 'YYYY-MM-DD')", "2026-01-07"),
    ("SELECT to_char(to_timestamp('2026-01-07 13:05:09', 'YYYY-MM-DD HH24:MI:SS'), 'YYYY-MM-DD HH24:MI:SS')", "2026-01-07 13:05:09")]
BI_HELPERS = [
    ("SELECT format('%I.%I', 'crm', 'Sales')", 'crm."Sales"'),
    ("SELECT format('%s|%L|%L', 'a', NULL, 'it''s')", "a|NULL|'it''s'"),
    ("SELECT quote_ident('Sales')", '"Sales"'),
    ("SELECT quote_literal('a\\b')", r"E'a\\b'"),
    ("SELECT quote_nullable(NULL)", "NULL"),
    ("SELECT array_to_string(parse_ident('crm.\"Sales\"'), '|')", "crm|Sales"),  # (parse_ident's answer, as its parts)
]


def bi_digest(rows):
    """[row count, the first 16 hex digits of sha256]: each row's values joined by '|' (a float rounded to 6 places,
    a timestamp with a zone taken as UTC, a date as midnight), the lines sorted and joined by newlines. Postgres 16's
    answers were digested the same way, so the two can be compared without writing out every row."""
    import datetime, decimal, hashlib

    def text(v):
        if isinstance(v, bool):
            return str(v)
        if isinstance(v, (int, float, decimal.Decimal)):
            return repr(round(float(v), 6))
        if isinstance(v, datetime.datetime):
            if v.tzinfo is not None:
                v = v.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return v.isoformat()
        if isinstance(v, datetime.date):
            return v.isoformat() + "T00:00:00"
        return "" if v is None else str(v)

    lines = sorted("|".join(text(v) for v in r) for r in rows)
    return [len(lines), hashlib.sha256("\n".join(lines).encode()).hexdigest()[:16]]


def bi():
    """What Grafana, Metabase, Superset and DBeaver send, word for word: tools/bi_statements.json holds every distinct
    statement the four tools sent to the Postgres port (with their parameters, DBeaver's `?` as `$n`). The section loads
    the sample data, then runs each statement as its tool did, one connection a tool, and checks that each answers, that
    the statements Postgres 16 refuses are refused with its SQLSTATE, and that what the tools read is what Postgres 16
    gives on the same data: Grafana's table and column lists, Metabase's table and field sync, Superset's time-range
    charts (six grains and a DATE range, as digests of the rows) and pgjdbc's type-name lookups, which give one row a
    type name. The to_char, to_date, to_timestamp, format, quote and parse_ident answers are Postgres 16's, written in."""
    import collections, psycopg

    corpus = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "bi_statements.json"), encoding="utf-8"))
    lake = new_lake()
    port, pg = A.port + 1, A.port + 10
    url = f"host=127.0.0.1 port={pg} user=u dbname=lake"
    checks, info, results, refused = {}, {}, {}, {}
    node = extra = None

    def check(name, fn):
        """A check's value is its bool. An exception fails it and is kept in info; the rest still run."""
        try:
            checks[name] = bool(fn())
        except Exception as e:
            checks[name] = False
            info[f"error: {name}"] = f"{type(e).__name__}: {str(e)[:600]}"

    def connect():
        return psycopg.connect(url, autocommit=True, cursor_factory=psycopg.RawCursor)

    def failed(conn, x):
        """The SQLSTATE and the start of the error. A transaction the statement broke is ended, so the next one stands alone."""
        if conn.info.transaction_status == psycopg.pq.TransactionStatus.INERROR:
            conn.execute("ROLLBACK")
        return f"{x.sqlstate or type(x).__name__}: {str(x)[:300]}"

    def run(conn, e):
        """One statement as its tool sent it: its parameters, with a lookup's answer read on this same connection."""
        params = []
        for p in e.get("params", []):
            if isinstance(p, dict) and "lookup" in p:
                found = conn.execute(p["lookup"]).fetchall()
                p = found[0][0] if found else None
            params.append(p)
        cur = conn.cursor()
        if params:
            cur.execute(e["sql"], params)
        else:
            cur.execute(e["sql"])
        return cur.fetchall() if cur.description else None

    def load():
        """The sample data, its role and its sequence, one statement at a time: every one that answers counts."""
        errors = []
        with connect() as c:
            for s in (x.strip() for x in BI_SAMPLE.split(";")):
                if s:
                    try:
                        c.execute(s)
                    except psycopg.Error as x:
                        errors.append(f"{s[:70]}: {failed(c, x)}")
        if errors:
            info["sample data errors"] = errors
        return not errors

    def answer_all():
        """Every corpus statement, per tool over one connection, in the order the tool sent it."""
        for tool in BI_TOOLS:
            conn = connect()
            try:
                for e in (x for x in corpus if x["tool"] == tool):
                    key = e["key"]
                    try:
                        results[key] = run(conn, e)
                        if key in BI_PG_REFUSES:
                            refused[key] = None
                            info.setdefault("postgres refuses", {})[key] = {"why": BI_PG_REFUSES[key][0], "pondra": "answered"}
                        elif key in BI_EXCEPTIONS:
                            info.setdefault("exceptions", {})[key] = {"why": BI_EXCEPTIONS[key], "pondra": "answered"}
                    except psycopg.Error as x:
                        why = failed(conn, x)
                        if key in BI_PG_REFUSES:
                            refused[key] = x.sqlstate
                            info.setdefault("postgres refuses", {})[key] = {"why": BI_PG_REFUSES[key][0], "pondra": why}
                        elif key in BI_EXCEPTIONS:
                            info.setdefault("exceptions", {})[key] = {"why": BI_EXCEPTIONS[key], "pondra": why}
                        else:
                            info[key] = why
            finally:
                conn.close()

    def same(pairs, label):
        """Each statement's one value against Postgres 16's text; the ones that differ are kept in info under label."""
        differ = []
        for sql, want in pairs:
            try:
                got = extra.execute(sql).fetchone()[0]
            except psycopg.Error as x:
                got = failed(extra, x)
            if got != want:
                differ.append({"sql": sql, "postgres": want, "pondra": got})
        if differ:
            info[label] = differ
        return not differ

    def type_names_once():
        """pgjdbc's type cache: each common type name once, and no name more often than Postgres 16 lists it."""
        counts = collections.Counter(r[2] for r in results["dbeaver:D6"])
        return all(counts[n] == 1 for n in BI_TYPE_NAMES) and all(v <= BI_TYPE_REPEATS.get(k, 1) for k, v in counts.items())

    try:
        node = Node(lake, port, pg=f"127.0.0.1:{pg}").start()
        check("the sample data loads: its tables, view, comments, role and sequence (every statement answers)", load)
        answer_all()
        extra = connect()
        d8 = next(e for e in corpus if e["key"] == "dbeaver:D8")
        try:
            results["dbeaver:D8 int4"] = extra.execute(d8["sql"], ["int4"]).fetchall()
        except psycopg.Error as x:
            info["dbeaver:D8 int4"] = failed(extra, x)

        counts = {}
        for tool, version in BI_TOOLS.items():
            keys = [e["key"] for e in corpus if e["tool"] == tool]
            answering = [k for k in keys if k not in BI_PG_REFUSES and k not in BI_EXCEPTIONS]
            counts[tool] = {"statements": len(keys), "answering": len(answering),
                            "postgres refuses": [k for k in keys if k in BI_PG_REFUSES],
                            "exceptions": [k for k in keys if k in BI_EXCEPTIONS]}
            n = len(answering)
            checks[f"every statement {version} sends answers ({n} of {n})"] = all(k in results for k in answering)
        info["corpus"] = counts
        n = len(BI_PG_REFUSES)
        checks[f"statements Postgres 16 refuses are refused too, with the same SQLSTATE ({n} of {n})"] = all(
            refused.get(k) == code for k, (_, code) in BI_PG_REFUSES.items())

        check("Grafana's table list (showTables) gives regions, sales, sales_by_region and crm.customers, in Postgres 16's order",
              lambda: [r[0] for r in results["grafana:21"]] == BI_GRAFANA_TABLES)
        check("Grafana's column list for sales (getSchema with parse_ident('sales')) gives its 8 columns with Postgres 16's types",
              lambda: sorted(map(tuple, results["grafana:22"])) == sorted(BI_GRAFANA_SALES))
        check("Metabase's table sync (statement 11) gives sales, regions, sales_by_region and crm.customers with Postgres 16's "
              "types and comments, and sales' estimated row count is not NULL",
              lambda: [tuple(r[:4]) for r in results["metabase:sync-11"]] == BI_METABASE_TABLES
              and any(r[0] == "public" and r[1] == "sales" and r[4] is not None for r in results["metabase:sync-11"]))
        check("Metabase's field sync (statement 13) gives each column of sales its database type (int8, timestamp, text, float8, "
              "int4, uuid; a VARCHAR(n) text), pk? true for id only, and amount's comment",
              lambda: [(r[0], r[1], r[2], r[5], r[6]) for r in results["metabase:sync-13"]
                       if r[3] == "public" and r[4] == "sales"] == BI_METABASE_SALES)
        for key, (grain, count, digest) in BI_SUPERSET.items():
            check(f"Superset's {grain} time-range chart (TO_TIMESTAMP) gives the rows Postgres 16 gives (sorted, values rounded to 6 places)",
                  lambda key=key, count=count, digest=digest: bi_digest(results[key]) == [count, digest])
        check("Superset's month chart on crm.customers with a DATE time range (TO_DATE) gives the rows Postgres 16 gives",
              lambda: bi_digest(results["superset:64"]) == [2, "5f3d2dc382607bc9"])
        check("pgjdbc's type cache (DBeaver D6) has one row per type name, as Postgres 16's does (its one repeat, _pg_user_mappings, twice)",
              type_names_once)
        check("pgjdbc's oid lookup (DBeaver D8) finds int4 as one row and no type named mood, as Postgres 16 does",
              lambda: [r[1] for r in results["dbeaver:D8 int4"]] == ["int4"] and results["dbeaver:D8"] == [])
        check("to_char gives Postgres 16's text for ten templates, from YYYY-MM-DD HH24:MI:SS to YYYY\"Q\"Q",
              lambda: same(BI_TO_CHAR, "to_char"))
        check("to_date and to_timestamp read their text as Postgres 16 does", lambda: same(BI_TO_DATE, "to_date and to_timestamp"))
        check("format, quote_ident, quote_literal, quote_nullable and parse_ident give Postgres 16's answers",
              lambda: same(BI_HELPERS, "format and quoting"))

        def matview():
            """A materialized view as DBeaver's and dbt's catalog queries read it: its query as written in pg_matviews and
            pg_get_viewdef (the same text); a GROUP BY view's groups are its key (an index, as pg_index lists it), and an
            index made on a row-by-row one shows in hasindexes."""
            extra.execute("CREATE MATERIALIZED VIEW region_totals AS SELECT region, sum(amount) AS total FROM sales GROUP BY region")
            extra.execute("CREATE MATERIALIZED VIEW big_sales AS SELECT region, product, amount FROM sales WHERE amount > 10")
            has = lambda v: extra.execute(f"SELECT hasindexes FROM pg_matviews WHERE matviewname = '{v}'").fetchone()
            before = has("big_sales")
            extra.execute("CREATE INDEX big_sales_region ON big_sales (region)")
            after = has("big_sales")
            row = extra.execute("SELECT definition, hasindexes FROM pg_matviews WHERE matviewname = 'region_totals'").fetchone()
            viewdef = extra.execute("SELECT pg_get_viewdef('region_totals'::regclass)").fetchone()
            info["materialized view"] = {"row-by-row before and after an index": (before, after), "pg_matviews": row, "pg_get_viewdef": viewdef}
            return before == (False,) and after == (True,) and row is not None and "sum(amount)" in row[0] and "GROUP BY region" in row[0] \
                and row[1] is True and viewdef == (row[0],)
        check("a materialized view's query as written, in pg_matviews.definition and pg_get_viewdef, and an index on it in hasindexes",
              matview)
    finally:
        if extra is not None:
            extra.close()
        if node is not None:
            node.kill()
    ok = all(checks.values())
    print(json.dumps({"bi": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"{sum(checks.values())} of {len(checks)} BI checks"


# The object kinds `registry()` doesn't make itself, and where each is checked (grepped: each named
# section or tool makes the kind and asserts on it). A kind added to KINDS without a check fails there.
ELSEWHERE = {"external table": "harness.py external", "type": "harness.py enums", "secret": "harness.py secrets", "user": "harness.py users",
             "database": "this section's branches, environments_check.py", "share": "sharing_check.py", "recipient": "sharing_check.py", "identity provider": "harness.py sso"}


def registry():
    """The statement registry (ADR-049): every kind of object in `pondra.objects` with its comment and
    definition; `SHOW CREATE` of each kind runs again to the same object; `COMMENT ON` every kind,
    following a rename and gone with a drop; `CREATE OR ALTER TABLE` makes, adds, widens, takes away
    options and refuses what would lose rows; `GET /kinds`."""
    lake = new_lake()
    node = Node(lake, A.port, pg=f"127.0.0.1:{A.port + 10}").start()
    q = lambda s: sql(A.port, s)
    def http(body):
        c = http_client.HTTPConnection("127.0.0.1", A.port, timeout=60)
        c.request("POST", "/sql", body.encode())
        r = c.getresponse()
        data = r.read()
        return r.status, data.decode()[:400]
    checks, info = {}, {}
    made = [
        ("schema", "sales", "CREATE SCHEMA sales"),
        ("table", "sales.orders", "CREATE TABLE sales.orders (id BIGINT PRIMARY KEY, region VARCHAR NOT NULL, amount DECIMAL(12, 2) DEFAULT 0, at TIMESTAMP, "
                                  "tags VARCHAR[], CONSTRAINT positive CHECK (amount >= 0)) CLUSTER BY (region) SEQUENCE BY at TTL at + INTERVAL '2 days' WITH (retention = '3 days')"),
        ("table", "clicks", "CREATE TABLE clicks (ts TIMESTAMP, page VARCHAR, \"User\" BIGINT, \"order\" INT) PARTITION BY day(ts)"),
        ("table", "totals", "CREATE TABLE totals (region VARCHAR PRIMARY KEY, amount DOUBLE MERGE sum, n BIGINT MERGE count)"),
        ("view", "eu_orders", "CREATE VIEW eu_orders AS SELECT id, amount FROM sales.orders WHERE region = 'eu'"),
        ("materialized view", "pages", "CREATE MATERIALIZED VIEW pages (CONSTRAINT some_page EXPECT (page IS NOT NULL) ON VIOLATION DROP ROW) AS SELECT ts, page FROM clicks"),
        ("materialized view", "per_page", "CREATE MATERIALIZED VIEW per_page AS SELECT page, count(*) AS n FROM clicks GROUP BY page"),
        ("materialized view", "per_minute", "CREATE MATERIALIZED VIEW per_minute WITH (window = 'minute', size_secs = 60, lateness_secs = 5) AS SELECT date_bin(INTERVAL '1 minute', ts) AS minute, count(*) AS n FROM clicks GROUP BY 1"),
        ("macro", "twice", "CREATE MACRO twice(x) AS x * 2"),
        ("function", "net", "CREATE FUNCTION net(x DOUBLE, rate DOUBLE DEFAULT 0.2) RETURNS DOUBLE IMMUTABLE RETURN x * (1 - rate)"),
        ("table function", "big_orders", "CREATE FUNCTION big_orders(least DOUBLE) RETURNS TABLE (id BIGINT, amount DOUBLE) LANGUAGE sql AS $$ SELECT id, CAST(amount AS DOUBLE) FROM sales.orders WHERE amount > least $$"),
        ("procedure", "note_click", "CREATE PROCEDURE note_click(p VARCHAR) LANGUAGE sql AS $$ INSERT INTO clicks VALUES (now(), p, 1, 1); $$"),
        ("task", "tidy", "CREATE TASK tidy SCHEDULE '1 hour' WITH (retries = 2, timeout = '10 minutes') AS CALL note_click('tidy')"),
        ("task", "after_tidy", "CREATE TASK after_tidy AFTER tidy WHEN 1 = 1 AS SELECT 1"),
        ("role", "analyst", "CREATE ROLE analyst"),
        ("sequence", "order_no", "CREATE SEQUENCE order_no AS integer START WITH 1000 INCREMENT BY 10 CACHE 5"),
        ("table", "tickets", "CREATE TABLE tickets (id BIGINT GENERATED ALWAYS AS IDENTITY (START WITH 5), title VARCHAR)"),
        ("index", "sales.orders_region_at_idx", "CREATE INDEX ON sales.orders (region, at DESC)"),
        ("index", "clicks_lower_page", "CREATE INDEX clicks_lower_page ON clicks USING brin (lower(page)) WHERE page IS NOT NULL"),
    ]
    for _, _, stmt in made:
        q(stmt)
    q("ALTER TASK tidy SUSPEND")
    word = lambda k: {"macro": "FUNCTION", "table function": "FUNCTION"}.get(k, k.upper())
    comments = {"schema": "sales", "table": "sales.orders", "view": "eu_orders", "materialized view": "per_page", "function": "net",
                "procedure": "note_click", "task": "tidy", "role": "analyst", "sequence": "order_no", "index": "clicks_lower_page"}
    for k, n in comments.items():
        q(f"COMMENT ON {k.upper()} {n} IS 'about {n}'")
    q("COMMENT ON COLUMN sales.orders.amount IS $$in euros, it's net$$")
    q("COMMENT ON COLUMN eu_orders.amount IS 'net, in euros'")
    q("COMMENT ON TABLE clicks IS 'gone soon'")
    q("COMMENT ON TABLE clicks IS NULL")
    listed = {(r["kind"], r.get("schema"), r["name"]): r for r in q("SELECT * FROM pondra.objects")}
    info["listed"] = sorted(f"{k[0]}:{k[1]}.{k[2]}" for k in listed)
    want = {(k, n.split(".")[0] if "." in n else (None if k in ("schema", "role") else "public"), n.split(".")[-1]) for k, n, _ in made}
    checks["pondra.objects lists every kind, each with its comment"] = want <= set(listed) \
        and all(listed[(k, n.split(".")[0] if "." in n else (None if k in ("schema", "role") else "public"), n.split(".")[-1])].get("comment") == f"about {n}" for k, n in comments.items()) \
        and listed[("table", "public", "clicks")].get("comment") is None
    # SHOW CREATE, dropped, run again: the same definition and comments
    show = lambda k, n: q(f"SHOW CREATE {word(k)} {n}")[0]["definition"]
    before = {(k, n): show(k, n) for k, n, _ in made}
    info["shown"] = {f"{k} {n}": v for (k, n), v in before.items()}
    drops = {"schema": None, "table": "DROP TABLE", "view": "DROP VIEW", "materialized view": "DROP MATERIALIZED VIEW", "macro": "DROP MACRO", "function": "DROP FUNCTION",
             "table function": "DROP FUNCTION", "procedure": "DROP PROCEDURE", "task": "DROP TASK", "role": "DROP ROLE", "sequence": "DROP SEQUENCE", "index": "DROP INDEX"}
    for k, n, _ in reversed(made):
        if drops[k] and k != "table":
            q(f"{drops[k]} {n}")
    for k, n, _ in reversed(made):
        if k == "table":
            q(f"DROP TABLE {n} PURGE")
    after_drop = [r["name"] for r in q("SELECT name FROM pondra.objects WHERE comment IS NOT NULL")]
    for k, n, _ in made:
        for stmt in [s for s in before[(k, n)].split(";\n") if k != "schema" or not s.startswith("CREATE")]:
            q(stmt.rstrip(";"))
    again = {(k, n): show(k, n) for k, n, _ in made}
    info["differs"] = {f"{k} {n}": [before[(k, n)], again[(k, n)]] for k, n, _ in made if before[(k, n)] != again[(k, n)]}
    checks["SHOW CREATE of every kind, run again after a drop, makes the same object, comments and all; a drop takes its comments"] = \
        not info["differs"] and after_drop == ["sales"] and "COMMENT ON COLUMN sales.orders.amount IS 'in euros, it''s net'" in again[("table", "sales.orders")] \
        and "COMMENT ON COLUMN eu_orders.amount IS 'net, in euros'" in again[("view", "eu_orders")]
    q("ALTER TABLE sales.orders RENAME TO orders_2025")
    moved = q("SELECT name, comment FROM pondra.objects WHERE kind = 'table' AND schema = 'sales'")
    checks["a renamed table keeps its comments, its columns' too"] = moved == [{"name": "orders_2025", "comment": "about sales.orders"}] \
        and "IS 'in euros, it''s net'" in show("table", "sales.orders_2025")
    # Indexes: objects with a notice, in pg_indexes, following renames, gone with their columns and tables
    def told(stmt):
        c = http_client.HTTPConnection("127.0.0.1", A.port, timeout=60)
        c.request("POST", "/sql", stmt.encode())
        r = c.getresponse()
        r.read()
        return r.status, " ".join(json.loads(r.getheader("x-pondra-notices") or "[]"))
    q("CREATE TABLE visits (page VARCHAR, n INT)")
    notice = told("CREATE INDEX ON visits (page)")
    again = told("CREATE INDEX IF NOT EXISTS visits_page_idx ON visits (page)")
    q("CREATE INDEX visits_lower ON visits USING brin (lower(page)) WHERE page IS NOT NULL")
    q("ALTER TABLE visits RENAME COLUMN page TO path")
    import psycopg
    with psycopg.connect(f"host=127.0.0.1 port={A.port + 10} user=pondra dbname=pondra", autocommit=True) as c:  # (Postgres's catalog is the Postgres port's)
        pg = [{"indexname": n, "indexdef": d} for n, d in c.execute("SELECT indexname, indexdef FROM pg_indexes WHERE tablename = 'visits' ORDER BY indexname").fetchall()]
    q("ALTER INDEX visits_page_idx RENAME TO visits_path")
    indexes = lambda: [r["name"] for r in q("SELECT name FROM pondra.objects WHERE kind = 'index' ORDER BY name")]
    renamed = indexes()
    refused_ix = [http(s) for s in ("CREATE INDEX v_idx ON eu_orders (id)", "CREATE INDEX ON visits (nothing)", "CREATE INDEX ON visits USING hnsw (path)",
                                    "CREATE UNIQUE INDEX ON visits (lower(path))", "CREATE TABLE visits_path (x INT)", "CREATE INDEX visits ON totals (region)")]
    q("ALTER TABLE visits DROP COLUMN path")
    after_column = indexes()
    q("CREATE INDEX ON totals (region)")
    q("DROP TABLE totals")
    after_table = indexes()
    info["indexes"] = [notice, again, pg, renamed, refused_ix, after_column, after_table, show("index", "sales.orders_region_at_idx")]
    checks["CREATE INDEX: an object with a notice, in pg_indexes, renamed, refused by name where it can't be, gone with its column and its table"] = \
        notice[0] == 200 and "nothing is built" in notice[1] and again == (200, 'relation "visits_page_idx" already exists, skipping') \
        and pg == [{"indexname": "visits_lower", "indexdef": "CREATE INDEX visits_lower ON public.visits USING brin (lower(path)) WHERE (path IS NOT NULL)"},
                   {"indexname": "visits_page_idx", "indexdef": "CREATE INDEX visits_page_idx ON public.visits (path)"}] \
        and renamed == ["clicks_lower_page", "orders_region_at_idx", "visits_lower", "visits_path"] and [r[0] for r in refused_ix] == [500, 500, 500, 500, 409, 409] \
        and "hnsw" in refused_ix[2][1] and "a view" in refused_ix[0][1] and "an index has the name" in refused_ix[4][1] \
        and after_column == ["clicks_lower_page", "orders_region_at_idx"] and after_table == after_column \
        and show("index", "sales.orders_region_at_idx") == "CREATE INDEX orders_region_at_idx ON sales.orders_2025 (region, at DESC);"
    # CREATE OR ALTER TABLE
    first = q("CREATE OR ALTER TABLE events (id BIGINT, kind VARCHAR) CLUSTER BY (kind) WITH (retention = '1 day')")
    q("INSERT INTO events VALUES (1, 'a')")
    same = q("CREATE OR ALTER TABLE events (id BIGINT, kind VARCHAR) CLUSTER BY (kind) WITH (retention = '1 day')")
    grown = q("CREATE OR ALTER TABLE events (id BIGINT, kind VARCHAR, note VARCHAR)")
    widened = q("CREATE OR ALTER TABLE events (id BIGINT, kind VARCHAR, note VARCHAR, n INT)")
    widened2 = q("CREATE OR ALTER TABLE events (id BIGINT, kind VARCHAR, note VARCHAR, n BIGINT)")
    refused = [http(s) for s in ("CREATE OR ALTER TABLE events (id BIGINT, kind VARCHAR)",
                                 "CREATE OR ALTER TABLE events (kind VARCHAR, id BIGINT, note VARCHAR, n BIGINT)",
                                 "CREATE OR ALTER TABLE events (id BIGINT PRIMARY KEY, kind VARCHAR, note VARCHAR, n BIGINT)",
                                 "CREATE OR ALTER TABLE events (id INT, kind VARCHAR, note VARCHAR, n BIGINT)",
                                 "CREATE OR ALTER TABLE events AS SELECT 1 AS id")]
    view_again = [q("CREATE OR ALTER VIEW recent AS SELECT id FROM events"), q("CREATE OR ALTER VIEW recent AS SELECT id, kind FROM events")]
    info["or_alter"] = [first, same, grown, widened, widened2, refused, view_again]
    o = call(A.port, "GET", "/objects")
    ev = next(t for t in o["tables"] if t["name"] == "events") if isinstance(o, dict) and "tables" in o else None
    checks["CREATE OR ALTER TABLE: made, then nothing to do, a column added, options taken away, a type widened; what would lose rows refused"] = \
        first.get("created") is True and same.get("unchanged") is True and "+ note" in grown.get("altered", []) \
        and any(a.startswith("CLUSTER BY") for a in grown.get("altered", [])) and any(a.startswith("retention") for a in grown.get("altered", [])) \
        and "n BIGINT" in widened2.get("altered", []) and [r[0] for r in refused] == [500] * 5 \
        and q("SELECT id, kind, note, n FROM events") == [{"id": 1, "kind": "a"}] \
        and q("SELECT * FROM recent") == [{"id": 1, "kind": "a"}] and "CLUSTER BY" not in show("table", "events")
    q("CREATE TABLE kv (k BIGINT PRIMARY KEY, v VARCHAR)")
    q("INSERT INTO kv VALUES (1, 'a'), (2, 'b')")
    kv = [q("CREATE OR ALTER TABLE kv (k BIGINT PRIMARY KEY, v VARCHAR, w INT)"), q("CREATE OR ALTER TABLE kv (k BIGINT PRIMARY KEY, v VARCHAR, w INT)")]
    q("INSERT INTO kv VALUES (3, 'c', 3)")
    q("DELETE FROM kv WHERE k = 1")
    info["kv"] = kv + [show("table", "kv")]
    checks["a keyed table: a column added, its _deleted its own (never in its definition), DELETE still works"] = kv[0].get("altered") == ["+ w"] \
        and kv[1].get("unchanged") is True and "_deleted" not in show("table", "kv") and q("SELECT k, w FROM kv ORDER BY k") == [{"k": 2}, {"k": 3, "w": 3}]
    # Branches (ADR-047) are made again by their clone: DROP DATABASE deletes one, so no ATTACH would find it
    here = q("SELECT name FROM pondra.databases")[0]["name"]
    dev_at, slim_at = f"{lake}-dev", f"{lake}-slim"
    LAKES.extend([dev_at, slim_at])
    q("CREATE SECRET reg_secret (TYPE http, BEARER_TOKEN 'reg-token-1', SCOPE 'https://reg.example.com/')")  # (a secret the clone must leave)
    q(f"CREATE DATABASE dev LOCATION '{dev_at}' CLONE \"{here}\"")
    # What the clone took, as the registry says (pondra.kinds' on_clone, read here, never written in), against what each lake lists
    on_clone = {r["kind"]: r for r in q("SELECT * FROM pondra.kinds") if r["is"] == "object"}
    cloned_families = ("schema", "relation", "routine", "task", "type", "secret")
    lists = lambda rows: {(r["kind"], r.get("schema"), r["name"]) for r in rows if on_clone[r["kind"]]["family"] in cloned_families}
    base = lists(q(f"SELECT kind, schema, name FROM pondra.objects WHERE lake = '{here}'"))
    branch = lists(q("SELECT kind, schema, name FROM pondra.objects WHERE lake = 'dev'"))
    how = lambda e: on_clone[e[0]]["on_clone"]
    info["clone"] = {"base": sorted(map(str, base)), "branch": sorted(map(str, branch)),
                     "missing_in_branch": sorted(str(e) for e in base if how(e) in ("copy", "pin") and e not in branch)}
    checks["a clone takes what the registry says (copy, pin) and leaves what it says (leave): the secret stays the base's"] = \
        not any(e in branch for e in base if how(e) == "leave") and all(e in branch for e in base if how(e) in ("copy", "pin")) \
        and ("secret", None, "reg_secret") in base
    q("DROP SECRET reg_secret")
    q(f"CREATE DATABASE slim LOCATION '{slim_at}' CLONE \"{here}\" WITH (schemas = (sales)) WITH NO DATA")
    q("COMMENT ON DATABASE dev IS 'a branch'")
    branches = {n: show("database", n) for n in ("dev", "slim")}
    listed = {r["name"]: r.get("definition") for r in q("SELECT name, definition FROM pondra.objects WHERE kind = 'database'")}
    for n in ("slim", "dev"):
        q(f"DROP DATABASE {n}")
    for n in ("dev", "slim"):
        for stmt in branches[n].split(";\n"):
            q(stmt.rstrip(";"))
    info["branches"] = [branches, listed]
    checks["a branch's SHOW CREATE is its clone (where, which schemas, no data), and run again after a drop makes it again"] = \
        branches["dev"].startswith(f"CREATE DATABASE dev LOCATION '{dev_at}' CLONE \"{here}\";\nCOMMENT ON DATABASE dev IS 'a branch'") \
        and branches["slim"].startswith(f"CREATE DATABASE slim LOCATION '{slim_at}' CLONE \"{here}\" WITH (schemas = (sales)) WITH NO DATA") \
        and branches["dev"].startswith(listed["dev"]) and {n: show("database", n) for n in ("dev", "slim")} == branches \
        and q("SELECT count(*) AS n FROM slim.sales.orders_2025") == [{"n": 0}] and q("SELECT count(*) AS n FROM dev.events") == [{"n": 1}]
    kinds = call(A.port, "GET", "/kinds")
    checks["GET /kinds and pondra.kinds list every kind and its statements"] = {k["kind"] for k in kinds} >= {"table", "view", "materialized view", "function", "procedure", "task", "schema"} \
        and q("SELECT statements FROM pondra.kinds WHERE kind = 'table'")[0]["statements"].startswith("CREATE, CREATE OR ALTER")
    listed_kinds = q('SELECT kind, "is" FROM pondra.kinds')
    object_kinds = {r["kind"] for r in listed_kinds if r["is"] == "object"}
    made_kinds = {k for k, _, _ in made}
    info["kinds"] = {"objects": sorted(object_kinds), "made": sorted(made_kinds), "elsewhere": sorted(ELSEWHERE),
                     "unchecked": sorted(object_kinds - made_kinds - set(ELSEWHERE)), "unknown": sorted((made_kinds | set(ELSEWHERE)) - object_kinds)}
    checks["every kind is checked: made here, or named in ELSEWHERE (a kind added without a check fails here)"] = object_kinds == made_kinds | set(ELSEWHERE)
    names = [k["kind"] for k in kinds]
    object_names = {k["kind"] for k in kinds if k["is"] == "object"}
    checks["pondra.kinds and GET /kinds are one list: objects, parts and patterns, each answering its questions"] = \
        sorted((r["kind"], r["is"]) for r in listed_kinds) == sorted((k["kind"], k["is"]) for k in kinds) and len(set(names)) == len(names) \
        and all(k["statements"] and k["on_clone"] in ("copy", "pin", "leave") for k in kinds if k["is"] == "object") \
        and all(k["inside"] and set(k["inside"]) <= object_names for k in kinds if k["is"] == "part") \
        and all(k["lists"] for k in kinds if k["is"] == "pattern") \
        and {k["kind"] for k in kinds if k["is"] == "object" and k["on_clone"] == "leave"} == {"secret", "share", "recipient"}
    missing = [http(s)[0] for s in ("SHOW CREATE TABLE nothing_here", "COMMENT ON TABLE nothing_here IS 'x'", "COMMENT ON COLUMN events.nothing IS 'x'", "COMMENT ON COLUMN eu_orders.region IS 'x'")]
    quiet = q("COMMENT IF EXISTS ON TABLE nothing_here IS 'x'")
    checks["what isn't there: refused by name (4xx), or nothing with IF EXISTS"] = all(400 <= s < 500 for s in missing) and quiet.get("exists") is False
    node.kill()
    ok = all(checks.values())
    print(json.dumps({"registry": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)


def find():
    """`pondra.parts` and `pondra.find` (L5-1): every part of every object, and a search of objects, parts and concepts by name, comment and definition, at every door, as the caller may see them."""
    import base64, psycopg
    lake = new_lake()
    shop_at = f"{lake}-shop"
    LAKES.append(shop_at)
    node = Node(lake, A.port, pg=f"127.0.0.1:{A.port + 10}").start()
    q = lambda s: sql(A.port, s)
    def http(body):
        c = http_client.HTTPConnection("127.0.0.1", A.port, timeout=60)
        c.request("POST", "/sql", body.encode())
        r = c.getresponse()
        data = r.read()
        return r.status, data.decode()[:400]
    checks, info = {}, {}
    for s in [
        "CREATE SCHEMA sales",
        "CREATE TYPE status AS ENUM ('open', 'paid', 'void')",
        "CREATE TABLE customers (id BIGINT PRIMARY KEY NOT ENFORCED, name VARCHAR, segment VARCHAR)",
        "CREATE TABLE sales.orders (id BIGINT, customer_id BIGINT REFERENCES customers (id) NOT ENFORCED, amount DECIMAL(12, 2), state status, card VARCHAR, at TIMESTAMP, CONSTRAINT positive CHECK (amount >= 0))",
        "CREATE TABLE totals (region VARCHAR PRIMARY KEY, amount DOUBLE)",
        "COMMENT ON TABLE sales.orders IS 'every order, one row each'",
        "COMMENT ON COLUMN sales.orders.amount IS 'the revenue of the order, in euros'",
        "CREATE VIEW revenue AS SELECT customer_id, sum(amount) AS total FROM sales.orders GROUP BY customer_id",
        "CREATE VIEW revenue_daily AS SELECT date_trunc('day', at) AS day, sum(amount) AS total FROM sales.orders GROUP BY 1",
        "COMMENT ON COLUMN revenue.total IS 'net revenue'",
        "CREATE MATERIALIZED VIEW big_orders (CONSTRAINT has_amount EXPECT (amount IS NOT NULL) ON VIOLATION DROP ROW) AS SELECT id, amount FROM sales.orders",
        "CREATE FUNCTION net(x DOUBLE, rate DOUBLE DEFAULT 0.2) RETURNS DOUBLE IMMUTABLE RETURN x * (1 - rate)",
    ]:
        q(s)
    q(f"CREATE DATABASE shop LOCATION '{shop_at}'")
    q("CREATE TABLE shop.products (sku VARCHAR, price DOUBLE)")
    # (the JSON leaves out NULLs: a concept's object or a column's comment is missing from its row, so read them with .get)

    # pondra.parts: every part, with its type, comment and definition
    parts = q("SELECT * FROM pondra.parts")
    info["parts"] = parts
    def part(obj, kind, name=None):
        return next((r for r in parts if r.get("object") == obj and r["kind"] == kind and (name is None or r["name"] == name)), None) or {}
    amount = part("orders", "column", "amount")
    labels = {r["name"] for r in parts if r.get("object") == "status" and r["kind"] == "label"}
    link_defs = [r.get("definition") or "" for r in parts if r.get("object") == "orders" and r["kind"] == "link"]
    checks["pondra.parts: columns with their types and comments, keys, links, checks, expectations, parameters and labels, a view's columns too"] = bool(
        amount.get("schema") == "sales" and amount.get("object_kind") == "table" and (amount.get("type") or "").startswith("DECIMAL")
        and amount.get("comment") == "the revenue of the order, in euros"
        and bool(part("orders", "column", "state"))
        and any("REFERENCES" in d and "customers" in d for d in link_defs)
        and part("orders", "check", "positive").get("definition") == "CHECK (amount >= 0)"
        and any(r.get("object") == "customers" and r["kind"] == "key" for r in parts)
        and part("totals", "key", "totals_pkey").get("definition") == "PRIMARY KEY (region)"
        and bool(part("revenue", "column", "customer_id"))
        and part("revenue", "column", "total").get("object_kind") == "view"
        and part("revenue", "column", "total").get("comment") == "net revenue"
        and (part("big_orders", "expectation", "has_amount").get("definition") or "").startswith("EXPECT (amount IS NOT NULL)")
        and bool(part("net", "parameter", "x")) and part("net", "parameter", "rate").get("definition") == "DEFAULT 0.2"
        and labels == {"open", "paid", "void"}
        and part("products", "column", "sku").get("lake") == "shop"
        and not any(r["kind"] == "column" and r["name"].startswith("_") for r in parts))
    info["checked"] = {"amount": amount, "labels": sorted(labels), "link_defs": link_defs}

    # pondra.find: a name first, then longer names, then comments; each row says which field matched
    f = q("SELECT * FROM pondra.find('revenue')")
    info["find_revenue"] = f
    row = lambda rows, pred: next((r for r in rows if pred(r)), {})
    first = (f or [{}])[0]
    day = row(f, lambda r: r["name"] == "revenue_daily")
    amt = row(f, lambda r: r.get("object") == "orders" and r["name"] == "amount")
    total = row(f, lambda r: r["is"] == "part" and r.get("object") == "revenue" and r["name"] == "total")
    checks["pondra.find: a name first, then longer names, then comments, each saying what matched"] = bool(
        first.get("name") == "revenue" and first.get("kind") == "view" and first.get("is") == "object" and first.get("matched") == "name" and first.get("rank") == 1
        and [r["rank"] for r in f] == list(range(1, len(f) + 1))
        and day.get("rank", 99) < amt.get("rank", 0) and amt.get("matched") == "comment" and bool(total))

    # kind => 'column': columns only, no concepts
    cols = q("SELECT * FROM pondra.find('revenue', kind => 'column')")
    info["find_column"] = cols
    checks["kind => 'column' keeps columns only, and concepts out"] = bool(cols) and all(r["kind"] == "column" and r["is"] == "part" for r in cols) \
        and any(r.get("object") == "orders" and r["name"] == "amount" for r in cols) and any(r.get("object") == "revenue" and r["name"] == "total" for r in cols)

    # every word in one field: 'revenue' and 'euros' are both in orders.amount's comment, and in no one name
    both = q("SELECT * FROM pondra.find('revenue euros')")
    info["find_two_words"] = both
    checks["every word in one field"] = any(r.get("object") == "orders" and r["name"] == "amount" for r in both) \
        and not any(r["is"] == "object" and r["name"] == "revenue" for r in both)

    # concepts, under other products' names; a kind leaves them out
    fk = q("SELECT * FROM pondra.find('foreign key')")
    pipe = q("SELECT * FROM pondra.find('pipeline')")
    fk_link = q("SELECT * FROM pondra.find('foreign key', kind => 'link')")
    info["concepts"] = [fk, pipe, fk_link]
    checks["concepts by other products' names: 'foreign key' is the link part, 'pipeline' the flow pattern; a kind leaves them out"] = \
        any(r["is"] == "part" and r["kind"] == "link" and r.get("matched") == "also" and r.get("object") is None for r in fk) \
        and any(r["is"] == "pattern" and r["kind"] == "flow" for r in pipe) and not any(r.get("object") is None for r in fk_link)

    # an attached lake's objects
    prod = q("SELECT * FROM pondra.find('products')")
    info["find_products"] = prod
    checks["an attached lake's objects are found"] = any(r.get("lake") == "shop" and r["name"] == "products" and r["is"] == "object" for r in prod)

    # refused by name, with the words that say why
    refused = [http(s) for s in ("SELECT * FROM pondra.find('')", "SELECT * FROM pondra.find('x', kind => 'nothing')", "SELECT * FROM pondra.find(42)")]
    info["refused"] = refused
    checks["refused by name: no words, a kind there isn't, a call that isn't pondra.find('words')"] = \
        [r[0] for r in refused] == [500, 500, 500] and "give the words" in refused[0][1] and "no kind nothing" in refused[1][1] and "pondra.find('words'" in refused[2][1]

    # never a remembered answer: a table made and a comment set are found at once
    before = [r for r in q("SELECT * FROM pondra.find('newthing')") if r["is"] == "object" and r["name"] == "newthing"]
    q("CREATE TABLE newthing (x INT)")
    at_once = [r for r in q("SELECT * FROM pondra.find('newthing')") if r["is"] == "object" and r["name"] == "newthing"]
    q("COMMENT ON TABLE newthing IS 'hello there'")
    by_comment = [r for r in q("SELECT * FROM pondra.find('hello there')") if r["name"] == "newthing" and r.get("matched") == "comment"]
    count = q("SELECT count(*) AS n FROM pondra.parts WHERE object = 'newthing'")
    info["fresh"] = [before, at_once, by_comment, count]
    checks["never a remembered answer: a table made, and a comment set on it, are found at once"] = before == [] and len(at_once) == 1 \
        and len(by_comment) == 1 and count == [{"n": 1}]

    # in a query like any table
    per = q("SELECT object, count(*) AS n FROM pondra.parts WHERE kind = 'column' AND object IN ('orders', 'revenue') GROUP BY object ORDER BY object")
    top2 = q("SELECT name FROM pondra.find('revenue') WHERE \"is\" = 'object' ORDER BY rank LIMIT 2")
    info["sql"] = [per, top2]
    checks["in a query like any table: parts grouped by object, find filtered and ordered"] = \
        per == [{"object": "orders", "n": 6}, {"object": "revenue", "n": 2}] and [r["name"] for r in top2] == ["revenue", "revenue_daily"]

    # over Postgres
    with psycopg.connect(f"host=127.0.0.1 port={A.port + 10} user=pondra dbname=pondra", autocommit=True) as c:
        over_pg = c.execute("SELECT name FROM pondra.find('revenue') ORDER BY rank LIMIT 1").fetchall()
        pg_count = c.execute("SELECT count(*) FROM pondra.parts").fetchone()[0]
    http_count = q("SELECT count(*) AS n FROM pondra.parts")[0]["n"]
    info["postgres"] = [over_pg, pg_count, http_count]
    checks["over Postgres: find and parts answer as they do over HTTP"] = over_pg == [("revenue",)] and pg_count == http_count

    # MCP: a tool named find, answering as the SQL does
    rpc = lambda method, params: call(A.port, "POST", "/mcp", json.dumps({"jsonrpc": "2.0", "id": 1, "method": method, "params": params}).encode(),
                                      headers={"content-type": "application/json"})["result"]
    tool = next((t for t in rpc("tools/list", {})["tools"] if t["name"] == "find"), {})
    reply = rpc("tools/call", {"name": "find", "arguments": {"text": "revenue", "kind": "column"}})
    body = json.loads(reply["content"][0]["text"]) if not reply["isError"] else {}
    mcp_names = [r["name"] for r in body.get("rows", [])]
    info["mcp"] = [tool.get("inputSchema", {}).get("required"), reply["isError"], mcp_names]
    checks["MCP: find is a tool, answering as the SQL does"] = "text" in tool.get("inputSchema", {}).get("required", []) and not reply["isError"] \
        and bool(mcp_names) and mcp_names == [r["name"] for r in cols]

    # the Python client
    db = _client(A.port)
    py_first, py_cols = db.find("revenue"), db.find("revenue", kind="column")
    info["python"] = [py_first[0]["name"], sorted({r["kind"] for r in py_cols})]
    checks["the Python client's db.find: the best match first, and kind= keeps columns"] = py_first[0]["name"] == "revenue" and bool(py_cols) \
        and all(r["kind"] == "column" for r in py_cols)

    # the JavaScript client, as the other clients' checks run it
    js = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "js", "index.js")
    script = f"""import {{ connect }} from {json.dumps(js)};
const db = connect("http://127.0.0.1:{A.port}");
const first = await db.find("revenue"), cols = await db.find("revenue", {{ kind: "column" }});
console.log(JSON.stringify([first[0].name, [...new Set(cols.map(r => r.kind))], cols.every(r => r.is === "part")]));
await db.close?.();"""
    path = os.path.join(tempfile.mkdtemp(prefix="pondra-find-"), "find.mjs")
    open(path, "w").write(script)
    js_out = subprocess.run(["node", path], capture_output=True, text=True, timeout=60)
    info["javascript"] = js_out.stdout.strip() or js_out.stderr[-1500:]
    checks["JavaScript: db.find(text, { kind }) gives the best match first, and kind keeps columns"] = \
        info["javascript"] == json.dumps(["revenue", ["column"], True], separators=(",", ":"))

    # timing: 1,000 tables; the median of five runs of each
    for start in range(0, 1000, 100):
        call(A.port, "POST", "/sql", ";\n".join(f"CREATE TABLE t_{i} (id BIGINT, name VARCHAR, amount DOUBLE)" for i in range(start, start + 100)).encode(), timeout=600)
    def timed(s):
        ms, got = [], None
        for _ in range(5):
            t0 = time.perf_counter()
            got = q(s)
            ms.append((time.perf_counter() - t0) * 1000)
        return sorted(ms)[2], got[0]["n"]
    find_ms, find_n = timed("SELECT count(*) AS n FROM pondra.find('amount')")
    parts_ms, parts_n = timed("SELECT count(*) AS n FROM pondra.parts")
    info.update(find_ms_1000_tables=round(find_ms, 1), find_rows=find_n, parts_ms_1000_tables=round(parts_ms, 1), parts_rows=parts_n)
    call(A.port, "POST", "/sql", ";\n".join(f"CREATE VIEW v_{i} AS SELECT id, amount FROM t_{i}" for i in range(200)).encode(), timeout=600)
    views_ms, views_n = timed("SELECT count(*) AS n FROM pondra.find('amount')")
    info.update(find_ms_1000_tables_200_views=round(views_ms, 1), find_rows_with_views=views_n)
    checks["a find over 1,000 tables and 200 views answers in under 2 s"] = find_ms < 2000 and find_n >= 1000 and views_ms < 2000 and views_n >= find_n + 200

    # last: signing in closes the node to anyone unsigned
    basic = lambda u, p: "Basic " + base64.b64encode(f"{u}:{p}".encode()).decode()
    as_ = lambda auth, s: call(A.port, "POST", "/sql", s.encode(), headers={"Authorization": auth})
    boss = basic("boss", "boss-password-1")
    q("CREATE USER boss PASSWORD 'boss-password-1' SUPERUSER")
    info["closed"] = until(lambda: http("SELECT 1 AS x")[0], 401, 30)
    for s in ["CREATE USER ann PASSWORD 'ann-password-1'", "GRANT SELECT ON sales.orders TO ann",
              "CREATE USER cal PASSWORD 'cal-password-1'", "GRANT SELECT (id, amount) ON sales.orders TO cal"]:
        as_(boss, s)
    ann, cal_user = basic("ann", "ann-password-1"), basic("cal", "cal-password-1")
    ann_parts = as_(ann, "SELECT DISTINCT object FROM pondra.parts WHERE object_kind NOT IN ('function', 'type')")  # (functions and types are everyone's, as on Postgres)
    ann_revenue = as_(ann, "SELECT * FROM pondra.find('revenue')")
    ann_customers = as_(ann, "SELECT * FROM pondra.find('customers')")
    info["ann"] = [ann_parts, ann_revenue, ann_customers]
    checks["a user granted one table sees its parts only (and the functions and types everyone may use), and finds only what it may read"] = \
        sorted(r["object"] for r in ann_parts) == ["orders"] \
        and any(r.get("object") == "orders" and r["name"] == "amount" for r in ann_revenue) \
        and not any(r["name"] in ("revenue", "revenue_daily", "total") for r in ann_revenue) \
        and not any(r["is"] == "object" and "customers" in (r.get("object"), r["name"]) for r in ann_customers)
    cal_parts = as_(cal_user, "SELECT kind, name FROM pondra.parts WHERE object = 'orders' ORDER BY name")
    cal_def = as_(cal_user, "SELECT definition FROM pondra.objects WHERE name = 'orders'")
    cal_card = as_(cal_user, "SELECT * FROM pondra.find('card')")
    info["cal"] = [cal_parts, cal_def, cal_card]
    checks["a user granted some columns sees those columns only, and no definition naming the others"] = \
        cal_parts == [{"kind": "column", "name": "amount"}, {"kind": "column", "name": "id"}] \
        and cal_def in ([{}], [{"definition": None}]) and not any(r["name"] == "card" for r in cal_card)

    node.kill()
    ok = all(checks.values())
    print(json.dumps({"find": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"{sum(bool(v) for v in checks.values())} of {len(checks)} find checks"


def measures():
    """Measures in views (ADR-065 §3, L5-3): `AS MEASURE` in a view's SELECT, `MEASURE(m)` at each query's own grain, against the GROUP BY written by hand, at every door; the refusals; what it costs."""
    import datetime, psycopg
    lake = new_lake()
    node = Node(lake, A.port, pg=f"127.0.0.1:{A.port + 10}").start()
    q = lambda s, path="/sql": call(A.port, "POST", path, s.encode(), timeout=120)
    def http(body):
        c = http_client.HTTPConnection("127.0.0.1", A.port, timeout=60)
        c.request("POST", "/sql", body.encode())
        r = c.getresponse()
        data = r.read()
        return r.status, data.decode()[:400]
    dsn = f"host=127.0.0.1 port={A.port + 10} user=pondra dbname=pondra"
    def over_pg(s):
        """The column names and the rows (dicts, NULLs kept) of a statement over the Postgres port."""
        with psycopg.connect(dsn, autocommit=True) as c:
            cur = c.execute(s)
            names = [d.name for d in cur.description]
            return names, [dict(zip(names, r)) for r in cur.fetchall()]
    def tuples(rows, keys=None):
        """Rows as tuples of their values: under `keys` (JSON leaves out NULLs, so a key a row lacks is None), else in each row's own key order; floats rounded to 6 places."""
        pick = (lambda r: [r.get(k) for k in keys]) if keys else (lambda r: list(r.values()))
        return [tuple(round(v, 6) if isinstance(v, float) else v for v in pick(r)) for r in rows]
    same = lambda a, b, keys=None: sorted(tuples(a, keys), key=repr) == sorted(tuples(b, keys), key=repr)
    ordered = lambda a, b: tuples(a) == tuples(b)
    median = lambda xs: sorted(xs)[len(xs) // 2]
    fresh = itertools.count(1)  # (the result cache answers a text it has seen at this catalog version: each timed run gets a comment of its own)
    def ms(s):
        """One run of `s`, in milliseconds."""
        t0 = time.perf_counter()
        q(f"{s} /* run {next(fresh)} */")
        return (time.perf_counter() - t0) * 1000
    def insert(table, rows):
        for lo in range(0, len(rows), 500):
            q(f"INSERT INTO {table} VALUES " + ", ".join(rows[lo:lo + 500]))
    def customer(i):
        region = None if i % 37 == 0 else ["north", "south", "east", "west"][i % 4]
        return f"({i}, {'NULL' if region is None else repr(region)})"
    def order(i):
        when = datetime.datetime(2026, 1, 1) + datetime.timedelta(days=i % 40, hours=i % 24)
        status = "void" if i % 17 == 0 else "paid" if i % 3 else "open"
        return f"({i}, {(i * 7) % 230 + 1}, TIMESTAMP '{when:%Y-%m-%d %H:%M:%S}', {((i * 13) % 500) + 0.25 * (i % 4)!r}, '{status}')"
    B = "FROM orders o LEFT JOIN customers c ON o.customer_id = c.id WHERE o.status <> 'void'"
    SALES = ("CREATE VIEW sales AS SELECT o.ordered_at::date AS day, c.region, o.status, sum(o.amount) AS MEASURE revenue, "
             "count(DISTINCT o.customer_id) AS MEASURE customers, revenue / customers AS MEASURE per_customer, count(*) AS MEASURE orders_n, "
             "sum(net(o.amount)) AS MEASURE net_revenue FROM orders o LEFT JOIN customers c ON o.customer_id = c.id WHERE o.status <> 'void'")
    MQ2 = "SELECT region, MEASURE(per_customer) AS pc FROM sales GROUP BY region"
    H2 = f"SELECT c.region, sum(o.amount) / count(DISTINCT o.customer_id) AS pc {B} GROUP BY 1"
    MQ3 = "SELECT region, MEASURE(revenue) AS r FROM sales GROUP BY region"
    H3 = f"SELECT c.region, sum(o.amount) AS r {B} GROUP BY 1"
    checks, info = {}, {}
    for s in [
        "CREATE TABLE customers (id BIGINT PRIMARY KEY NOT ENFORCED, region VARCHAR)",
        "CREATE TABLE orders (id BIGINT, customer_id BIGINT, ordered_at TIMESTAMP, amount DOUBLE, status VARCHAR)",
        "CREATE FUNCTION net(x DOUBLE) RETURNS DOUBLE IMMUTABLE RETURN x * 0.8",
        "CREATE VIEW plain_view AS SELECT status, sum(amount) AS total FROM orders GROUP BY status",
        SALES,
    ]:
        q(s)
    insert("customers", [customer(i) for i in range(1, 201)])
    insert("orders", [order(i) for i in range(1, 3001)])
    followers = [Node(lake, A.port + i).start() for i in (1, 2)]  # two more nodes on the lake: check 11 spreads over all three
    time.sleep(1)  # (the followers hear of each other: spread queries need them)

    # 1. a read of the view as stored: its dimensions and each measure, grouped by every dimension
    plain = q("SELECT * FROM sales")
    plain_h = q(f"SELECT o.ordered_at::date AS day, c.region, o.status, sum(o.amount) AS revenue, count(DISTINCT o.customer_id) AS customers, sum(o.amount) / count(DISTINCT o.customer_id) AS per_customer, count(*) AS orders_n, sum(o.amount * 0.8) AS net_revenue {B} GROUP BY 1, 2, 3")
    names, _ = over_pg("SELECT * FROM sales LIMIT 1")  # (the cursor's column names: a row with a NULL leaves its key out of JSON)
    info["plain"] = [plain, plain_h, names]
    checks["a plain read is the view at its own grain: its dimensions and measures, grouped by every dimension"] = same(plain, plain_h) \
        and names == ["day", "region", "status", "revenue", "customers", "per_customer", "orders_n", "net_revenue"]

    # 2. per customer by region is the region's revenue over its distinct customers, not an average of the view's ratios
    m2, h2 = q(MQ2), q(H2)
    avg2 = q("SELECT region, avg(per_customer) AS pc FROM (SELECT * FROM sales) s GROUP BY region")
    info["per_customer"] = [m2, h2, avg2]
    checks["MEASURE() at the query's own grain: per customer by region is the region's revenue over its distinct customers, never an average of the view's rows"] = \
        same(m2, h2) and not same(m2, avg2)

    # 3. every way of naming a measure is one answer
    hand3 = q(H3)
    forms = ["MEASURE(revenue)", "AGG(revenue)", "AGGREGATE(revenue)", "measure(revenue)", "sum(revenue)", "max(revenue)", "revenue", "sales.revenue"]
    got3 = {x: q(f"SELECT region, {x} AS r FROM sales GROUP BY region") for x in forms}
    info["forms"] = [got3, hand3]
    checks["every way of naming a measure gives one answer: MEASURE, AGG, AGGREGATE, sum() as BI tools send it, the bare name, qualified"] = \
        all(same(v, hand3) for v in got3.values())

    # 4. the columns that read no measure group; with none, one row
    st, st_h = q("SELECT status, MEASURE(orders_n) AS n FROM sales"), q(f"SELECT o.status, count(*) AS n {B} GROUP BY 1")
    one, one_h = q("SELECT MEASURE(revenue) AS r, MEASURE(customers) AS c FROM sales"), q(f"SELECT sum(o.amount) AS r, count(DISTINCT o.customer_id) AS c {B}")
    info["no_group"] = [st, st_h, one, one_h]
    checks["with no GROUP BY, the columns that read no measure group; with none, one row"] = same(st, st_h) and same(one, one_h) and len(one) == 1

    # 5. WHERE on a dimension, HAVING, ORDER BY and LIMIT on measures
    top = q("SELECT region, MEASURE(revenue) AS r FROM sales WHERE day >= DATE '2026-01-20' GROUP BY region HAVING MEASURE(orders_n) > 10 ORDER BY MEASURE(revenue) DESC LIMIT 3")
    top_h = q(f"SELECT c.region, sum(o.amount) AS r {B} AND o.ordered_at::date >= DATE '2026-01-20' GROUP BY 1 HAVING count(*) > 10 ORDER BY sum(o.amount) DESC LIMIT 3")
    info["top"] = [top, top_h]
    checks["WHERE on a dimension, HAVING, ORDER BY and LIMIT on measures"] = ordered(top, top_h)

    # 6. grouped by an expression of a dimension
    mo = q("SELECT date_trunc('month', day) AS m, MEASURE(customers) AS n FROM sales GROUP BY 1")
    mo_h = q(f"SELECT date_trunc('month', o.ordered_at::date) AS m, count(DISTINCT o.customer_id) AS n {B} GROUP BY 1")
    info["by_month"] = [mo, mo_h]
    checks["grouped by an expression of a dimension"] = same(mo, mo_h)

    # 7. a measure through the lake's own function
    nr = q("SELECT status, MEASURE(net_revenue) AS n FROM sales GROUP BY status")
    nr_h = q(f"SELECT o.status, sum(o.amount * 0.8) AS n {B} GROUP BY 1")
    info["net"] = [nr, nr_h]
    checks["a measure through the lake's own function"] = same(nr, nr_h)

    # 8. a join no used column reads is left out of the query
    plan_day = json.dumps(q("EXPLAIN SELECT day, MEASURE(revenue) AS r FROM sales GROUP BY day"))
    plan_region = json.dumps(q("EXPLAIN SELECT region, MEASURE(revenue) AS r FROM sales GROUP BY region"))
    info["explain"] = [plan_day, plan_region]
    checks["a join nothing reads is left out"] = "customers" not in plan_day and "customers" in plan_region

    # 9. a view and a CTE over the view with measures
    q("CREATE VIEW by_region AS SELECT region, MEASURE(revenue) AS revenue FROM sales GROUP BY region")
    by_region = q("SELECT * FROM by_region")
    m9 = q("WITH t AS (SELECT region, MEASURE(revenue) AS r FROM sales GROUP BY region) SELECT max(r) AS m FROM t")
    h9 = q(f"SELECT max(r) AS m FROM (SELECT c.region, sum(o.amount) AS r {B} GROUP BY 1) t")
    info["views"] = [by_region, m9, h9]
    checks["views and CTEs over a view with measures"] = same(by_region, hand3) and same(m9, h9)

    # 10. rows written after are counted
    before10 = q(MQ3)
    insert("orders", [order(i) for i in range(3001, 3301)])
    after10, h10 = q(MQ3), q(H3)
    info["after_writes"] = [before10, after10, h10]
    checks["rows written after are counted"] = same(after10, h10) and not same(after10, before10)

    # 11. spread over three nodes == one node
    def spreads():
        m = metrics_of(A.port)
        return m.get("pondra_spread_queries_total", 0) + m.get("pondra_shuffled_queries_total", 0)
    until(lambda: _try(lambda: call(A.port + 1, "POST", "/sql", b"SELECT count(*) AS n FROM orders")), [{"n": 3300}], 30)
    spread_queries = [MQ2, "SELECT status, MEASURE(orders_n) AS n FROM sales", "WITH t AS (SELECT region, MEASURE(revenue) AS r FROM sales GROUP BY region) SELECT max(r) AS m FROM t"]
    before_spread = spreads()
    spread = [(q(s, "/sql?spread=1"), q(s, "/sql?spread=0")) for s in spread_queries]
    info["spread"] = [spread, [before_spread, spreads()]]  # (the spread counters: whether the queries spread)
    checks["spread over three nodes == one node"] = all(same(a, b) for a, b in spread)

    # 12. over Postgres: the same answers, and the catalog lists the view's columns and its definition
    http_rows = q(MQ3)
    _, pg_rows = over_pg(MQ3)
    _, cat = over_pg("SELECT column_name FROM information_schema.columns WHERE table_name = 'sales' ORDER BY ordinal_position")
    _, defs = over_pg("SELECT definition FROM pg_views WHERE viewname = 'sales'")
    cols = [r["column_name"] for r in cat]
    info["postgres"] = [http_rows, pg_rows, cols, defs]
    checks["over Postgres: MEASURE answers as over HTTP, and the catalog lists the view's dimensions and measures"] = \
        same(http_rows, pg_rows, ["region", "r"]) and cols == ["day", "region", "status", "revenue", "customers", "per_customer", "orders_n", "net_revenue"] \
        and any("AS MEASURE revenue" in (r["definition"] or "") for r in defs)

    # 18. frames: pondra.measure through a frame's steps (a filter is a CTE the measure is read through)
    db = _client(A.port)
    import pondra as pondra_client
    frame = db.table("sales").filter(pondra_client.col("day") >= pondra_client.sql_expr("DATE '2026-01-20'")).group_by("region").agg(pondra_client.measure("revenue"))
    try:
        framed = [{k: v for k, v in r.items() if v is not None} for r in frame.rows()]  # (the client puts nulls back; the node's JSON leaves them out)
    except Exception as e:  # (kept in info: the frame's SQL and why it failed)
        framed = [{"error": str(e)[:300]}]
    framed_h = q(f"SELECT c.region, sum(o.amount) AS revenue {B} AND o.ordered_at::date >= DATE '2026-01-20' GROUP BY 1")
    info["frames"] = [frame.sql, framed, framed_h]
    checks["frames: pondra.measure through a frame's steps answers as the SQL does"] = bool(framed) and same(framed, framed_h)

    # 13. SHOW CREATE and pondra.objects show AS MEASURE; the statement makes the view again (after its drops)
    shown = q("SHOW CREATE VIEW sales")[0]["definition"] or ""
    listed_def = [r.get("definition") or "" for r in q("SELECT definition FROM pondra.objects WHERE name = 'sales'")]
    q("DROP VIEW by_region")
    q("DROP VIEW sales")
    made = _raises_text(lambda: q(shown))  # ("" when it made the view)
    again = _try(lambda: q(MQ2)) or []
    info["show_create"] = [shown, listed_def, made, again]
    checks["SHOW CREATE VIEW and pondra.objects show AS MEASURE, and the statement makes the view again"] = \
        "AS MEASURE revenue" in shown and "pondra_measure" not in shown and any("AS MEASURE" in d for d in listed_def) \
        and made == "" and same(again, q(H2))  # (the hand query again: check 10 wrote rows since h2)

    # 14. pondra.parts lists each measure with its expression; find() finds them
    parts = q("SELECT kind, name, definition FROM pondra.parts WHERE object = 'sales'")
    measure_names = {r["name"] for r in parts if r["kind"] == "measure"}
    column_names = {r["name"] for r in parts if r["kind"] == "column"}
    rev_def = next((r.get("definition") or "" for r in parts if r["kind"] == "measure" and r["name"] == "revenue"), "")
    found = q("SELECT * FROM pondra.find('revenue', kind => 'measure')")
    metric = q("SELECT * FROM pondra.find('metric')")
    info["parts"] = [parts, found, metric]
    checks["pondra.parts lists each measure with its expression, and find(kind => 'measure') finds them"] = \
        measure_names == {"revenue", "customers", "per_customer", "orders_n", "net_revenue"} and column_names == {"day", "region", "status"} \
        and "sum(o.amount)" in rev_def and bool(found) and found[0]["name"] == "revenue" \
        and any(r["kind"] == "measure" and r["is"] == "part" for r in metric)

    # 15. refused by name, and nothing made
    refusals = [
        ("SELECT region FROM sales WHERE revenue > 5", "HAVING"),
        ("SELECT sum(revenue * 2) AS x FROM sales", "inside sum"),
        ("SELECT MEASURE(revenue) FROM sales s JOIN customers c ON s.region = c.region", "inside the view"),
        ("SELECT MEASURE(nothing) FROM sales", "no measure nothing"),
        ("SELECT MEASURE(total) FROM plain_view", "reads none"),
        ("CREATE VIEW bad1 AS SELECT status, sum(amount) AS MEASURE m FROM orders GROUP BY status", "GROUP BY"),
        ("CREATE VIEW bad2 AS SELECT o.status, sum(o.amount) AS MEASURE m FROM orders o RIGHT JOIN customers c ON o.customer_id = c.id", "LEFT JOIN"),
        ("CREATE VIEW bad3 AS SELECT o.status, sum(o.amount) AS MEASURE m FROM orders o LEFT JOIN customers c ON o.status = c.region", "not on a key"),
        ("CREATE VIEW bad4 AS SELECT o.status, sum(o.amount) AS MEASURE m FROM orders o LEFT JOIN orders o2 ON o.id = o2.id", "has no key"),
        ("CREATE VIEW bad5 AS SELECT a + 1 AS MEASURE b, b + 1 AS MEASURE a FROM orders", "refer to each other"),
        ("CREATE MATERIALIZED VIEW bad6 AS SELECT sum(amount) AS MEASURE m FROM orders", "materialized view"),
        ("CREATE VIEW bad7 (s, m) AS SELECT status, sum(amount) AS MEASURE m FROM orders", "not in a list"),
    ]
    refused = [http(s) for s, _ in refusals]
    info["refused"] = [[st_code, text[:200]] for st_code, text in refused]
    no_bad = q("SELECT name FROM pondra.objects WHERE name LIKE 'bad%'")
    checks["refused by name, and nothing made"] = all(st_code >= 400 and phrase in text for (st_code, text), (_, phrase) in zip(refused, refusals)) and no_bad == []
    # a dimension written as a qualified column takes its name, a word that is also a function's (`user`) too
    q('CREATE TABLE ev_user ("user" TEXT, amount INT)')
    q("INSERT INTO ev_user VALUES ('a', 1), ('a', 2), ('b', 5)")
    made_user = http("CREATE VIEW ut AS SELECT e.user, sum(e.amount) AS MEASURE total FROM ev_user e")
    by_user = q('SELECT "user", MEASURE(total) AS t FROM ut GROUP BY "user" ORDER BY 1') if made_user[0] == 200 else []
    info["qualified_dimension"] = [made_user, by_user]
    checks["a dimension written e.user (a qualified column, its word a function's too) is named user"] = \
        made_user[0] == 200 and by_user == [{"user": "a", "t": 3}, {"user": "b", "t": 5}]

    # 16. a query with measures costs what its GROUP BY written by hand costs (each run its own text: none from the result cache,
    # which keys on the text as expanded; a measure's query is written anew there, without its comment, so each run names its column apart)
    named = lambda s: s.replace(" AS pc ", f" AS pc_{next(fresh)} ")
    for _ in range(3):
        ms(named(MQ2)), ms(named(H2))
    m_ms, h_ms = [], []
    for _ in range(15):
        m_ms.append(ms(named(MQ2)))
        h_ms.append(ms(named(H2)))
    measure_ms, hand_ms = median(m_ms), median(h_ms)
    info["timing_ms"] = {"measure": round(measure_ms, 2), "hand": round(hand_ms, 2)}
    checks["a query with measures costs what its GROUP BY written by hand costs"] = measure_ms <= hand_ms * 1.25 + 3

    # 17. a query naming no measure pays nothing for 100 views with measures
    CNT = "SELECT count(*) AS n FROM orders WHERE amount > 100"
    before_ms = [ms(CNT) for _ in range(15)]
    call(A.port, "POST", "/sql", ";\n".join(f"CREATE VIEW mv_{i} AS SELECT status, sum(amount) AS MEASURE m FROM orders" for i in range(100)).encode(), timeout=600)
    after_ms = [ms(CNT) for _ in range(15)]
    before_med, after_med = median(before_ms), median(after_ms)
    info["no_measure_ms"] = {"before": round(before_med, 2), "after": round(after_med, 2)}
    checks["a query naming no measure pays nothing for 100 views with measures"] = after_med <= before_med * 1.25 + 2

    for n in followers + [node]:
        n.kill()
    ok = all(checks.values())
    print(json.dumps({"measures": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"{sum(bool(v) for v in checks.values())} of {len(checks)} measures checks"


def facts():
    """Key facts on views (ADR-065 §2, L5-2): PRIMARY KEY, UNIQUE and FOREIGN KEY said NOT ENFORCED, kept with the view: listed, shown, moved and dropped with it, seen by Postgres and by a measure's join, refused by name where they can't hold, exported, and never checked."""
    import psycopg
    lake = new_lake()
    node = Node(lake, A.port, pg=f"127.0.0.1:{A.port + 10}").start()
    dsn = f"host=127.0.0.1 port={A.port + 10} user=pondra dbname=pondra"
    q = lambda s: call(A.port, "POST", "/sql", s.encode(), timeout=120)
    def run(s):
        """(status, text) of a statement sent to /sql: a refusal is a status of 400 or more, its words in the text."""
        c = http_client.HTTPConnection("127.0.0.1", A.port, timeout=60)
        c.request("POST", "/sql", s.encode())
        r = c.getresponse()
        return r.status, r.read().decode()
    def over_pg(s):
        """The rows (dicts) of a statement over the Postgres port."""
        with psycopg.connect(dsn, autocommit=True) as c:
            cur = c.execute(s)
            names = [d.name for d in cur.description]
            return [dict(zip(names, r)) for r in cur.fetchall()]
    def parts(obj):
        """The key and link parts of an object (pondra.parts), as sorted (kind, name, definition)."""
        rows = q(f"SELECT kind, name, definition FROM pondra.parts WHERE object = '{obj}'")
        return sorted((r["kind"], r["name"], r.get("definition") or "") for r in rows if r["kind"] in ("key", "link"))
    def shown(kind, name):
        """SHOW CREATE of an object, as its statement."""
        return q(f"SHOW CREATE {kind} {name}")[0]["definition"]
    def made_now(names):
        """The names, of these, that the lake holds (as pondra.objects lists them)."""
        listed = q("SELECT name FROM pondra.objects WHERE name IN (" + ", ".join(f"'{n}'" for n in names) + ")")
        return sorted(r["name"] for r in listed)

    PK = "PRIMARY KEY (id) NOT ENFORCED"
    FK = "FOREIGN KEY (region) REFERENCES regions(code) NOT ENFORCED"
    for s in [
        "CREATE TABLE regions (code VARCHAR PRIMARY KEY NOT ENFORCED, name VARCHAR)",
        "CREATE TABLE customers (id BIGINT PRIMARY KEY NOT ENFORCED, name VARCHAR, region VARCHAR)",
        "CREATE TABLE orders (id BIGINT, customer_id BIGINT, amount DOUBLE)",
        "INSERT INTO regions VALUES ('north', 'North'), ('south', 'South'), ('east', 'East')",
        "INSERT INTO customers VALUES (1, 'ann', 'north'), (2, 'bob', 'south'), (3, 'cy', 'north'), (4, 'dee', 'east')",
        "INSERT INTO orders VALUES (1, 1, 10.0), (2, 2, 20.5), (3, 3, 5.0), (4, 1, 7.0), (5, 4, 3.0)",
    ]:
        q(s)
    checks, info = {}, {}

    # 1. a view's key and link made with it, listed as parts; find() finds the key
    q("CREATE VIEW customers_v (PRIMARY KEY (id) NOT ENFORCED, CONSTRAINT customers_v_region_fkey FOREIGN KEY (region) REFERENCES regions (code) NOT ENFORCED) AS SELECT id, name, region FROM customers")
    key_parts = sorted([("key", "customers_v_pkey", PK), ("link", "customers_v_region_fkey", FK)])
    found = q("SELECT * FROM pondra.find('customers_v_pkey')")
    info["parts"] = parts("customers_v")
    checks["a view's key and link made with it are listed as parts with their definitions, and find() finds the key"] = \
        parts("customers_v") == key_parts and any(r.get("name") == "customers_v_pkey" for r in found)

    # 8. Postgres sees them: pg_constraint's p and f rows, and information_schema lists them for the view
    pg_rows = over_pg("SELECT c.conname, c.contype FROM pg_constraint c JOIN pg_class r ON c.conrelid = r.oid WHERE r.relname = 'customers_v'")
    info_rows = over_pg("SELECT constraint_name, constraint_type FROM information_schema.table_constraints WHERE table_name = 'customers_v'")
    info["pg"] = [pg_rows, info_rows]
    checks["Postgres sees them: pg_constraint's p and f rows for the view, and information_schema.table_constraints lists them"] = \
        sorted((r["conname"], r["contype"]) for r in pg_rows) == [("customers_v_pkey", "p"), ("customers_v_region_fkey", "f")] \
        and sorted((r["constraint_name"], r["constraint_type"]) for r in info_rows) == [("customers_v_pkey", "PRIMARY KEY"), ("customers_v_region_fkey", "FOREIGN KEY")]

    # 9a. a measure view joins a view whose PRIMARY KEY is a fact (its key is the join's)
    joined = run("CREATE VIEW sales_v AS SELECT c.region, sum(o.amount) AS MEASURE revenue FROM orders o LEFT JOIN customers_v c ON o.customer_id = c.id")
    run("DROP VIEW sales_v")
    info["measure_join"] = joined
    checks["a measure view joins onto a view whose PRIMARY KEY is a fact"] = joined[0] < 400

    # 2. ALTER VIEW adds and drops one fact; IF NOT EXISTS and IF EXISTS say nothing twice; a bare DROP names what's missing
    U = "customers_v_name_key"
    ADD = f"ALTER VIEW customers_v ADD CONSTRAINT {U} UNIQUE (name) NOT ENFORCED"
    added = run(ADD)[0]
    added_again = run(ADD.replace("ADD CONSTRAINT", "ADD CONSTRAINT IF NOT EXISTS"))[0]
    listed_once = [p for p in parts("customers_v") if p[1] == U]
    dropped = run(f"ALTER VIEW customers_v DROP CONSTRAINT {U}")[0]
    gone = not [p for p in parts("customers_v") if p[1] == U]
    dropped_again = run(f"ALTER VIEW customers_v DROP CONSTRAINT IF EXISTS {U}")[0]
    bare_status, bare_text = run(f"ALTER VIEW customers_v DROP CONSTRAINT {U}")
    info["alter"] = [added, added_again, listed_once, dropped, dropped_again, bare_status, bare_text[:300]]
    checks["ALTER VIEW adds and drops one fact: listed, IF NOT EXISTS and IF EXISTS say nothing twice, a bare DROP of a missing one is refused by name"] = \
        added < 400 and added_again < 400 and listed_once == [("key", U, "UNIQUE (name) NOT ENFORCED")] and dropped < 400 and gone \
        and dropped_again < 400 and bare_status >= 400 and U in bare_text

    # 10. refused by name, and nothing made: each refusal's words, the catalog as it was
    before_def, before_parts = shown("VIEW", "customers_v"), parts("customers_v")
    q("CREATE MATERIALIZED VIEW mv_big (CONSTRAINT big CHECK (amount > 0) ON VIOLATION DROP ROW) AS SELECT id, amount FROM orders")
    refusals = [
        ("CREATE VIEW r1 (UNIQUE (name)) AS SELECT name FROM customers", ["write UNIQUE (name) NOT ENFORCED"]),
        ("CREATE VIEW r2 (PRIMARY KEY (id)) AS SELECT id FROM customers", ["write PRIMARY KEY (id) NOT ENFORCED"]),
        ("CREATE VIEW r3 (CONSTRAINT r3_c CHECK (id > 0)) AS SELECT id FROM customers", ["a view's CHECK"]),
        ("CREATE VIEW r4 (PRIMARY KEY (nothing) NOT ENFORCED) AS SELECT id FROM customers", ["nothing", "does not exist"]),
        ("CREATE VIEW r5 (PRIMARY KEY (id) NOT ENFORCED, CONSTRAINT r5_b PRIMARY KEY (name) NOT ENFORCED) AS SELECT id, name FROM customers", ["multiple primary keys", "r5"]),
        ("ALTER VIEW customers_v ADD CONSTRAINT customers_v_pkey UNIQUE (name) NOT ENFORCED", ["already exists", "customers_v_pkey"]),
        ("ALTER MATERIALIZED VIEW mv_big ADD CONSTRAINT big UNIQUE (amount) NOT ENFORCED", ["already exists", "big"]),
        ("ALTER VIEW customers ADD CONSTRAINT customers_u UNIQUE (name) NOT ENFORCED", ["is a table", "ALTER TABLE"]),
        ("ALTER TABLE customers_v ADD CONSTRAINT customers_v_u UNIQUE (name) NOT ENFORCED", ["ALTER VIEW customers_v"]),
        ("ALTER VIEW nope ADD CONSTRAINT nope_u UNIQUE (id) NOT ENFORCED", ["nope", "does not exist"]),
        ("ALTER VIEW customers_v ADD CONSTRAINT customers_v_c CHECK (id > 0)", ["a view's CHECK"]),
        ("CREATE VIEW m_v (PRIMARY KEY (total) NOT ENFORCED) AS SELECT customer_id, sum(amount) AS MEASURE total FROM orders", ["total", "does not exist"]),
        ("CREATE TEMP VIEW t_v (PRIMARY KEY (id) NOT ENFORCED) AS SELECT id FROM customers", ["temporary view"]),
    ]
    got = [(s, *run(s)) for s, _ in refusals]
    info["refusals"] = [[status, text[:300]] for _, status, text in got]
    refused_by_name = all(status >= 400 and all(w in text for w in words) for (_, status, text), (_, words) in zip(got, refusals))
    missing_ok = run("ALTER VIEW IF EXISTS nope DROP CONSTRAINT nope_u")[0] < 400
    pg_code, pg_msg = "", ""
    with psycopg.connect(dsn, autocommit=True) as c:
        try:
            c.execute("ALTER TABLE customers_v ADD CONSTRAINT customers_v_u UNIQUE (name) NOT ENFORCED")
        except psycopg.Error as e:
            pg_code, pg_msg = e.sqlstate or "", str(e)
    info["pg_refused"] = [pg_code, pg_msg[:300]]
    q("DROP MATERIALIZED VIEW mv_big")
    unchanged = shown("VIEW", "customers_v") == before_def and parts("customers_v") == before_parts
    checks["refused by name, its words naming it, and nothing made: the view's facts as they were (42809 over Postgres, pointing at ALTER VIEW)"] = \
        refused_by_name and missing_ok and pg_code == "42809" and "ALTER VIEW customers_v" in pg_msg \
        and made_now(["r1", "r2", "r3", "r4", "r5", "m_v", "t_v", "nope"]) == [] and unchanged

    # 3. SHOW CREATE VIEW run again after a drop makes the same view, with the same parts
    shown_1, parts_1 = shown("VIEW", "customers_v"), parts("customers_v")
    q("DROP VIEW customers_v")
    q(shown_1)
    shown_2 = shown("VIEW", "customers_v")
    info["show_create"] = [shown_1, shown_2]
    checks["SHOW CREATE VIEW holds the list, and run again after a drop makes the same view with the same parts"] = \
        PK in shown_1 and "customers_v_region_fkey" in shown_1 and shown_2 == shown_1 and parts("customers_v") == parts_1

    # 4. kept through CREATE OR REPLACE while their columns are there; a column gone is refused by name
    q("CREATE OR REPLACE VIEW customers_v (id, name, region) AS SELECT id, name, region FROM customers")
    kept_by_list = parts("customers_v") == key_parts  # (a column list of the same names keeps them)
    st_list, text_list = run("CREATE OR REPLACE VIEW customers_v (cid, name, region) AS SELECT id, name, region FROM customers")
    info["list_refused"] = [st_list, text_list[:300]]
    refused_list = st_list >= 400 and all(w in text_list for w in ["customers_v_pkey", "id", "DROP CONSTRAINT"]) and parts("customers_v") == key_parts
    q("CREATE OR REPLACE VIEW customers_v AS SELECT id, name, region, 1 AS extra FROM customers")
    kept_both = parts("customers_v") == key_parts
    kept_def = shown("VIEW", "customers_v")
    st, text = run("CREATE OR REPLACE VIEW customers_v AS SELECT id, name FROM customers")
    info["replace_refused"] = [st, text[:300]]
    refused_replace = st >= 400 and all(w in text for w in ["customers_v_region_fkey", "region", "DROP CONSTRAINT"]) and shown("VIEW", "customers_v") == kept_def
    q("ALTER VIEW customers_v DROP CONSTRAINT customers_v_region_fkey")
    q("CREATE OR REPLACE VIEW customers_v AS SELECT id, name FROM customers")
    pk_stays = parts("customers_v") == [("key", "customers_v_pkey", PK)]
    q("CREATE OR REPLACE VIEW customers_v (UNIQUE (name) NOT ENFORCED) AS SELECT id, name FROM customers")
    only_listed = parts("customers_v") == [("key", U, "UNIQUE (name) NOT ENFORCED")]
    checks["kept through CREATE OR REPLACE while their columns are there (a column list of the same names too; one renaming a fact's column is refused by name); one whose column is gone is refused; a list replaces them"] = \
        kept_by_list and refused_list and kept_both and refused_replace and pk_stays and only_listed

    # 5. moved by a rename, gone with a drop, and a view made without a list has none
    before_rename = parts("customers_v")
    q("ALTER VIEW customers_v RENAME TO clients_v")
    moved = parts("clients_v") == before_rename and parts("customers_v") == []
    q("DROP VIEW clients_v")
    dropped_both = parts("clients_v") == [] and parts("customers_v") == []
    q("CREATE VIEW customers_v AS SELECT id, name, region FROM customers")
    no_list = parts("customers_v") == []
    checks["moved by a rename, gone with a drop, and a view made without a list has no key"] = moved and dropped_both and no_list

    # 9b. the same measure join onto a view with no key fact is refused: "has no key"
    no_key = run("CREATE VIEW sales_bad AS SELECT c.region, sum(o.amount) AS MEASURE revenue FROM orders o LEFT JOIN customers_v c ON o.customer_id = c.id")
    info["measure_no_key"] = no_key
    checks["a measure view joining a view with no key fact is refused: has no key"] = no_key[0] >= 400 and "has no key" in no_key[1]

    # 6. never checked: a PRIMARY KEY column with duplicates reads every row
    q("CREATE VIEW dup_v (PRIMARY KEY (region) NOT ENFORCED) AS SELECT region FROM customers")
    dup_rows = q("SELECT region FROM dup_v")
    checks["never checked: a view whose PRIMARY KEY column has duplicate values reads all its rows"] = \
        len(dup_rows) == 4 and sorted(r["region"] for r in dup_rows) == sorted(r["region"] for r in q("SELECT region FROM customers"))

    # 7. a materialized view's facts: the GROUP BY key listed, ALTER adds one, SHOW CREATE runs again, rows keep flowing
    q("CREATE MATERIALIZED VIEW region_totals (PRIMARY KEY (region) NOT ENFORCED) AS SELECT c.region, sum(o.amount) AS total FROM orders o JOIN customers c ON o.customer_id = c.id GROUP BY c.region")
    q("ALTER MATERIALIZED VIEW region_totals ADD UNIQUE (total) NOT ENFORCED")
    mv_parts = parts("region_totals")
    info["mv_parts"] = mv_parts
    mv_listed = ("key", "region_totals_pkey", "PRIMARY KEY (region)") in mv_parts and ("key", "region_totals_total_key", "UNIQUE (total) NOT ENFORCED") in mv_parts
    mv_shown = shown("MATERIALIZED VIEW", "region_totals")
    q("DROP MATERIALIZED VIEW region_totals")
    q(mv_shown)
    mv_same = shown("MATERIALIZED VIEW", "region_totals") == mv_shown and parts("region_totals") == mv_parts
    q("INSERT INTO orders VALUES (6, 2, 1.5)")
    got_rows = sorted((r["region"], round(r["total"], 6)) for r in q("SELECT region, total FROM region_totals"))
    want_rows = sorted((r["region"], round(r["total"], 6)) for r in q("SELECT c.region, sum(o.amount) AS total FROM orders o JOIN customers c ON o.customer_id = c.id GROUP BY c.region"))
    checks["a materialized view's facts: the GROUP BY key and ALTER's UNIQUE listed, SHOW CREATE runs again to the same view, rows keep flowing"] = \
        mv_listed and mv_same and got_rows == want_rows and len(want_rows) == 3

    # 11. export writes the list: the view made again with its key and link, then GET /export holds them
    q("CREATE OR REPLACE VIEW customers_v (PRIMARY KEY (id) NOT ENFORCED, CONSTRAINT customers_v_region_fkey FOREIGN KEY (region) REFERENCES regions (code) NOT ENFORCED) AS SELECT id, name, region FROM customers")
    exported = call(A.port, "GET", "/export")
    text = next((t for t in exported.values() if "CREATE VIEW customers_v" in t), "")
    info["export"] = text[:400]
    checks["export writes them: the view's file holds its key and link"] = \
        "CONSTRAINT customers_v_pkey PRIMARY KEY (id) NOT ENFORCED" in text and "CONSTRAINT customers_v_region_fkey FOREIGN KEY (region) REFERENCES regions(code) NOT ENFORCED" in text

    node.kill()
    ok = all(checks.values())
    print(json.dumps({"facts": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"{sum(bool(v) for v in checks.values())} of {len(checks)} facts checks"


def sparksql():
    """Spark SQL where PySpark code sends it (H8): `spark.sql(…)` read with Spark's grammar and
    turned into Pondra's SQL (`spark_sql('…')`): `"text"`, backticks, `LATERAL VIEW [OUTER]
    explode`, `explode`, `DIV`, `<=>`, `RLIKE`, Spark's answers for names both have; frames built on
    it, its sort, `args` and `{df}`; the SQL door's `spark_sql`, a view over it, and what it refuses.
    Pondra's own SQL answers as before."""
    lake = new_lake()
    node = Node(lake, A.port).start()
    db = _client(A.port)
    from pondra.spark import SparkSession, functions as F
    spark = SparkSession(db)
    q = lambda s: sql(A.port, s)
    checks, info = {}, {}
    q("CREATE TABLE people AS SELECT id, name, xs, CAST(d AS DOUBLE) AS d FROM (VALUES (1, 'ann', make_array(1, 2, 3), 2.5), (2, 'bob', make_array(4), -2.5), "
      "(3, 'cy', CAST(make_array() AS BIGINT[]), 0.5), (4, 'dee', CAST(NULL AS BIGINT[]), 7.5)) AS v(id, name, xs, d)")  # (Spark's floor of a DOUBLE is a BIGINT; 2.5 is a DECIMAL, whose floor has scale 0)
    rows = lambda df: [r.asDict() for r in df.collect()]
    got = {
        "text": rows(spark.sql('SELECT "hi" AS s, `name` FROM people WHERE name = "ann"')),
        "floor": rows(spark.sql("SELECT id, floor(d) AS f, ceil(d) AS c FROM people ORDER BY id")),
        "substring": rows(spark.sql("SELECT substring('Spark SQL', 5, 1) AS a, substring('Spark SQL', -3, 2) AS b, substr('Spark SQL', -3) AS c")),
        "ours": q("SELECT floor(CAST(2.5 AS DOUBLE)) AS f, substring('Spark SQL', -3, 2) AS b"),
        "lateral": rows(spark.sql("SELECT id, x FROM people LATERAL VIEW explode(xs) v AS x ORDER BY id, x")),
        "outer": rows(spark.sql("SELECT p.name, v.e FROM people p LATERAL VIEW OUTER explode(p.xs) v AS e WHERE p.id >= 2 ORDER BY p.name, v.e")),
        "two": rows(spark.sql("SELECT id, a, b FROM people LATERAL VIEW explode(xs) v AS a LATERAL VIEW explode(xs) w AS b WHERE id = 1 ORDER BY a, b"))[:4],
        "explode": rows(spark.sql("SELECT explode(xs) FROM people WHERE id = 1")),
        "operators": rows(spark.sql("SELECT 7 DIV 2 AS d, -7 DIV 2 AS e, NULL <=> NULL AS n, 'abc' RLIKE 'b' AS r, !(1 = 2) AS t")),
        "composed": rows(spark.sql("SELECT id, floor(d) AS f FROM people").where(F.col("f") > 0).orderBy("id")),
        "sorted": [r["id"] for r in rows(spark.sql("SELECT id FROM people ORDER BY id DESC"))],
        "sorted out": [r["name"] for r in rows(spark.sql("SELECT name FROM people ORDER BY d DESC"))] + [r["name"] for r in sql(A.port, "SELECT * FROM spark_sql('SELECT name FROM people ORDER BY d')")],
        "args": [r["id"] for r in rows(spark.sql("SELECT id FROM people WHERE id > :m ORDER BY id", args={"m": 2}))],
        "frame": rows(spark.sql("SELECT count(*) AS n FROM {d} WHERE `name` <> \"bob\"", d=spark.table("people"))),
        "door": q("SELECT f, arrow_typeof(f) AS t FROM spark_sql('SELECT floor(CAST(2.5 AS DOUBLE)) AS f')"),
    }
    q("CREATE VIEW floors AS SELECT * FROM spark_sql('SELECT id, floor(d) AS f FROM people')")
    got["view"] = q("SELECT sum(f) AS s FROM floors")
    refused = {
        "a statement that isn't a query": _raises_text(lambda: q("SELECT * FROM spark_sql('INSERT INTO people SELECT * FROM people')")),
        "posexplode": _raises_text(lambda: q("SELECT * FROM spark_sql('SELECT id, p, x FROM people LATERAL VIEW posexplode(xs) v AS p, x')")),
        "a lateral view over a join": _raises_text(lambda: q("SELECT * FROM spark_sql('SELECT * FROM people a JOIN people b ON a.id = b.id LATERAL VIEW explode(a.xs) v AS x')")),
    }
    info.update(got=got, refused=refused)
    checks['"text" is a string, `name` a name'] = got["text"] == [{"s": "hi", "name": "ann"}]
    checks["floor and ceil answer as Spark's (whole numbers, BIGINT), and Pondra's own SQL as before (a DOUBLE)"] = \
        got["floor"] == [{"id": 1, "f": 2, "c": 3}, {"id": 2, "f": -3, "c": -2}, {"id": 3, "f": 0, "c": 1}, {"id": 4, "f": 7, "c": 8}] \
        and all(type(r["f"]) is int for r in got["floor"]) and got["ours"][0]["f"] == 2.0 and isinstance(got["ours"][0]["f"], float)
    checks["substring and substr as Spark's (a negative start counts from the end), Pondra's as before"] = \
        got["substring"] == [{"a": "k", "b": "SQ", "c": "SQL"}] and got["ours"][0]["b"] != "SQ"
    checks["LATERAL VIEW explode: a row a value, none for an empty or NULL array"] = \
        got["lateral"] == [{"id": 1, "x": 1}, {"id": 1, "x": 2}, {"id": 1, "x": 3}, {"id": 2, "x": 4}]
    checks["LATERAL VIEW OUTER: a NULL for an empty or NULL array; the view's columns by its name, the table's by its alias"] = \
        got["outer"] == [{"name": "bob", "e": 4}, {"name": "cy", "e": None}, {"name": "dee", "e": None}]
    checks["two lateral views cross, not pair"] = got["two"] == [{"id": 1, "a": 1, "b": 1}, {"id": 1, "a": 1, "b": 2}, {"id": 1, "a": 1, "b": 3}, {"id": 1, "a": 2, "b": 1}]
    checks["explode in the select list: named col, as Spark names it"] = got["explode"] == [{"col": 1}, {"col": 2}, {"col": 3}]
    checks["DIV, <=>, RLIKE, !"] = got["operators"] == [{"d": 3, "e": -3, "n": True, "r": True, "t": True}]
    checks["a frame built on spark.sql composes; its ORDER BY is kept, by a column it leaves out too; args; {df}"] = \
        got["composed"] == [{"id": 1, "f": 2}, {"id": 4, "f": 7}] and got["sorted"] == [4, 3, 2, 1] \
        and got["sorted out"] == ["dee", "ann", "cy", "bob", "bob", "cy", "ann", "dee"] and got["args"] == [3, 4] and got["frame"] == [{"n": 3}]
    checks["spark_sql('…') from any door, and a view over it"] = got["door"] == [{"f": 2, "t": "Int64"}] and got["view"] == [{"s": 6}]
    checks["refused by name: " + ", ".join(refused)] = "takes a query" in refused["a statement that isn't a query"] and "posexplode" in refused["posexplode"] \
        and "over a join" in refused["a lateral view over a join"]
    node.kill()
    ok = all(checks.values())
    print(json.dumps({"sparksql": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)



def scripts():
    """Scripts that decide (ADR-045, phases 1 and 2): blocks with handlers, IF / ELSEIF / CASE, WHILE,
    REPEAT, LOOP and FOR over a query's rows (`$r.col`), LEAVE and ITERATE by label, RETURN, RAISE
    (P0001), PRINT and RAISE NOTICE as notices, ASSERT (P0004), EXECUTE IMMEDIATE … INTO … USING,
    CALL … INTO and IDENTIFIER(), from HTTP, Python, Postgres (simple and extended protocol) and in
    procedures; a block's DECLAREs its own; a script run again with its job writes once; a file's
    parameters leave out what its blocks bind. FOR … PARALLEL n runs passes at once, ASYNC runs a
    statement beside the script and AWAIT ALL waits (in a block too), `$h = ASYNC …` and `AWAIT $h` for
    one, `AWAIT 'id'` for a run pondra.start began: each with a copy of the variables, once per job.
    VALUES with a subquery in a row (DataFusion worked the rows out before the subquery ran)."""
    import psycopg
    lake = new_lake()
    here = os.path.dirname(os.path.abspath(__file__))
    pg = A.port + 10
    node = Node(lake, A.port, pg=f"127.0.0.1:{pg}", python="auto", env={"PYTHONPATH": os.path.join(here, "..", "python")}).start()
    h = {"x-pondra-session": "harness-scripts"}
    q = lambda s, hh=h, path="/sql": call(A.port, "POST", path, s.encode(), headers=hh)
    db = _client(A.port)
    def said(script):
        out = db.sql(script)
        return list(db.notices), (out.rows() if hasattr(out, "rows") else out)
    checks, info, got = {}, {}, {}
    q("CREATE TABLE orders (id BIGINT, day DATE, amount DOUBLE)")
    q("INSERT INTO orders VALUES (1, DATE '2026-09-29', 10), (2, DATE '2026-09-30', 20), (3, DATE '2026-09-30', 5)")
    # Branches, and what a script says.
    branch = """DECLARE $n = (SELECT count(*) FROM orders WHERE day = DATE '2026-09-30');
IF $n = 0 THEN
  PRINT 'nothing';
ELSEIF $n > 1 THEN
  PRINT 'many: ' || $n;
  RAISE NOTICE 'checked % of %', $n, (SELECT count(*) FROM orders);
ELSE
  PRINT 'one';
END IF;
CASE $n WHEN 1 THEN PRINT 'case one'; WHEN 2 THEN PRINT 'case two'; ELSE PRINT 'case else'; END CASE;
IF EXISTS (SELECT 1 FROM orders WHERE amount > 15) THEN PRINT 'big'; END IF;
SELECT $n AS n"""
    got["branch"] = said(branch)
    checks["IF … ELSEIF … ELSE and CASE take the branch their conditions say (a subquery too); PRINT and RAISE NOTICE are notices; the last statement answers"] = \
        got["branch"] == (["many: 2", "checked 2 of 3", "case two", "big"], [{"n": 2}])
    # Loops.
    loops = """DECLARE $i = 0; DECLARE $odd = 0;
outer: WHILE $i < 10 DO
  $i = $i + 1;
  IF $i % 2 = 0 THEN ITERATE outer; END IF;
  IF $i > 7 THEN LEAVE outer; END IF;
  $odd = $odd + $i;
END WHILE outer;
DECLARE $r = 0;
REPEAT $r = $r + 5; UNTIL $r >= 12 END REPEAT;
DECLARE $l = 0;
LOOP $l = $l + 1; IF $l = 3 THEN LEAVE; END IF; END LOOP;
DECLARE $sum = 0;
FOR o IN (SELECT id, amount FROM orders ORDER BY id) DO
  $sum = $sum + $o.amount * $o.id;
END FOR;
SELECT $i AS i, $odd AS odd, $r AS r, $l AS l, $sum AS sum"""
    got["loops"] = said(loops)
    checks["WHILE with ITERATE and LEAVE by label, REPEAT … UNTIL, LOOP … LEAVE, FOR over a query's rows ($o.amount)"] = \
        got["loops"][1] == [{"i": 9, "odd": 16, "r": 15, "l": 3, "sum": 65.0}]
    # Handlers, errors and their codes.
    handled = """BEGIN
  SELECT 1 / 0;
  PRINT 'not here';
EXCEPTION
  WHEN unique_violation THEN PRINT 'wrong one';
  WHEN division_by_zero THEN PRINT 'caught ' || $sqlstate;
END;
BEGIN
  RAISE 'too many rows for %: %', DATE '2026-09-30', 2;
EXCEPTION WHEN OTHERS THEN PRINT $sqlstate || ' ' || $error;
END;
SELECT getvariable('error') IS NULL AS gone"""
    got["handled"] = said(handled)
    checks["EXCEPTION WHEN takes the error its name or code says ($sqlstate, $error); RAISE formats with %; a handler's variables end with it"] = \
        got["handled"] == (["caught 22012", "P0001 too many rows for 2026-09-30: 2"], [{"gone": True}])
    reraised = _raises_text(lambda: q("BEGIN SELECT 1 / 0; EXCEPTION WHEN OTHERS THEN PRINT 'x'; RAISE; END"))
    asserted = _raises_text(lambda: q("ASSERT (SELECT count(*) FROM orders) = 4, 'orders: ' || (SELECT count(*) FROM orders)"))
    unclosed = _raises_text(lambda: q("IF true THEN SELECT 1;"))
    where = _raises_text(lambda: q("SELECT 1;\nIF true THEN\n  SELECT nope FROM orders;\nEND IF"))
    info["errors"] = {"reraised": reraised, "asserted": asserted, "unclosed": unclosed, "where": where}
    checks["RAISE; in a handler raises its error again; ASSERT fails with its text; a block not closed and an error inside one say where"] = \
        "Divide by zero" in reraised and "orders: 3" in asserted and "isn't closed" in unclosed and "statement 2" in where and "line 3" in where
    # Scopes.
    got["scopes"] = said("DECLARE $x = 1; BEGIN DECLARE $x = 2; PRINT $x; $x = 3; PRINT $x; END; PRINT $x; FOR r IN (SELECT 7 AS v) DO PRINT $r.v; END FOR")
    refused = _raises_text(lambda: q("SELECT 1; BEGIN DECLARE PARAMETER $p = 1; END"))
    got["sole block"] = q("BEGIN DECLARE PARAMETER $p = 1; SELECT $p AS p; END")  # (a script that is one block: its top is the script's)
    checks["a block's DECLARE is its own (the outer one back after it); a DECLARE PARAMETER inside a block is refused, unless the block is the whole script"] = got["sole block"] == [{"p": 1}] and \
        got["scopes"][0] == ["2", "3", "1", "7"] and "declared at its top" in refused
    # RETURN, dynamic SQL, names from values, CALL … INTO.
    got["return"] = said("DECLARE $n = 41; IF $n > 40 THEN RETURN $n + 1; END IF; PRINT 'not here'")
    q("CREATE PROCEDURE total(d DATE) LANGUAGE sql AS $$ SELECT sum(amount) AS t FROM orders WHERE day = $d $$")
    q("""CREATE PROCEDURE count_to(n BIGINT) LANGUAGE sql AS $$ DECLARE $i = 0; WHILE $i < $n DO $i = $i + 1; END WHILE; RETURN $i * 10; $$""")
    dynamic = """DECLARE $big = 0;
EXECUTE IMMEDIATE 'SELECT count(*) FROM orders WHERE amount > $1 AND day = $2' INTO $big USING 6, DATE '2026-09-30';
FOR t IN (SELECT 'a' AS name UNION ALL SELECT 'b' AS name ORDER BY name) DO
  EXECUTE IMMEDIATE 'CREATE TABLE IF NOT EXISTS ' || 'made_' || $t.name || ' (x BIGINT)';
  INSERT INTO IDENTIFIER('made_' || $t.name) VALUES (1);
END FOR;
CALL total(DATE '2026-09-30') INTO $t;
CALL count_to(4) INTO $c;
SELECT $big AS big, $t AS t, $c AS c, (SELECT count(*) FROM made_a) + (SELECT count(*) FROM made_b) AS made"""
    got["dynamic"] = said(dynamic)
    checks["RETURN ends the script with its value; EXECUTE IMMEDIATE … INTO … USING; IDENTIFIER() names a table; CALL … INTO (a procedure that loops and returns)"] = \
        got["return"] == ([], [{"result": 42}]) and got["dynamic"][1] == [{"big": 1, "t": 25.0, "c": 40, "made": 2}]
    # Exactly once: the same job, run again.
    q("CREATE TABLE ticks (n BIGINT)")
    tick = "DECLARE $i = 0; WHILE $i < 3 DO $i = $i + 1; INSERT INTO ticks VALUES ($i); END WHILE"
    q(tick, path="/sql?job=harness-ticks")
    q(tick, path="/sql?job=harness-ticks")
    got["ticks"] = q("SELECT count(*) AS n, sum(n) AS s FROM ticks")
    checks["a script run again with its job writes once (each statement's part its place and its loop's pass)"] = got["ticks"] == [{"n": 3, "s": 6}]
    # …a FOR loop's too when its rows come back in another order (no ORDER BY, a spread query): a
    # pass's place is its row (and how many equal rows came before it), not its number.
    q("CREATE TABLE seen (x BIGINT); CREATE TABLE halt (x BIGINT); INSERT INTO halt VALUES (3)")
    loop = "FOR r IN (SELECT x FROM (VALUES (1), (2), (3), (2)) t(x) ORDER BY x {}) DO IF EXISTS (SELECT 1 FROM halt WHERE x = $r.x) THEN RAISE 'halt at %', $r.x; END IF; INSERT INTO seen VALUES ($r.x); END FOR"
    halted = _raises_text(lambda: q(loop.format("ASC"), path="/sql?job=harness-order"))
    q("DELETE FROM halt")
    q(loop.format("DESC"), path="/sql?job=harness-order")
    got["order"] = q("SELECT x, count(*) AS n FROM seen GROUP BY x ORDER BY x")
    checks["a FOR loop that failed, run again with its job over its rows in another order: each row's statements once (equal rows each once)"] = \
        "halt at 3" in halted and got["order"] == [{"x": 1, "n": 1}, {"x": 2, "n": 2}, {"x": 3, "n": 1}]
    # Postgres: the simple protocol splits a script by its blocks; the extended one takes a block whole.
    heard = []
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=pondra dbname=pondra", autocommit=True, cursor_factory=psycopg.ClientCursor) as c:
        c.add_notice_handler(lambda d: heard.append(d.message_primary))
        cur = c.execute("DECLARE $k = 2; IF $k = 2 THEN PRINT 'simple ' || $k; END IF; SELECT $k AS k")
        simple = []
        while True:
            simple += cur.fetchall() if cur.description else []
            if not cur.nextset():
                break
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=pondra dbname=pondra", autocommit=True) as c:
        c.add_notice_handler(lambda d: heard.append(d.message_primary))
        c.execute("BEGIN PRINT 'extended ' || %s; END", ("too",))
        try:
            c.execute("RAISE 'refused %', 1")
            code = None
        except psycopg.Error as e:
            code = e.sqlstate
    info["postgres"] = {"simple": simple, "heard": heard, "code": code}
    checks["over Postgres: a script with blocks (simple protocol), a block alone (extended), notices as NOTICE, RAISE as P0001"] = \
        simple == [(2,)] and heard == ["simple 2", "extended too"] and code == "P0001"
    # A file's parameters: what its blocks bind isn't one.
    call(A.port, "PUT", "/files/etl/loop.sql", b"DECLARE PARAMETER $limit BIGINT = 2;\nFOR o IN (SELECT id FROM orders) DO\n  IF $o.id > $limit THEN PRINT $o.id; END IF;\nEND FOR;\nBEGIN SELECT 1; EXCEPTION WHEN OTHERS THEN PRINT $error; END;\nCALL total($day) INTO $t;\n")
    got["parameters"] = q("SELECT name, required FROM pondra.parameters('etl/loop.sql')")
    checks["a file's parameters leave out a loop's row, a handler's $error and INTO's names ($day, used unset, still one)"] = \
        got["parameters"] == [{"name": "limit", "required": False}, {"name": "day", "required": True}]
    # Phase 2: passes at once, and statements beside the script.
    q("CREATE TABLE done (n BIGINT, w TEXT)")
    got["parallel"] = q("DECLARE $total = 0; FOR d IN (SELECT value AS v FROM generate_series(1, 8)) PARALLEL 4 DO INSERT INTO done VALUES ($d.v, 'p'); $total = $total + $d.v; END FOR; SELECT $total AS total, (SELECT count(*) FROM done) AS c, (SELECT sum(n) FROM done) AS s", {})
    checks["FOR … PARALLEL 4: every pass once, each with a copy of the variables (what one sets stays its own)"] = got["parallel"] == [{"total": 0, "c": 8, "s": 36}]
    got["parallel refused"] = [_raises_text(lambda s=s: q(s, {})) for s in (
        "FOR d IN (SELECT value AS v FROM generate_series(1, 6)) PARALLEL 3 DO IF $d.v = 4 THEN RAISE 'no %', $d.v; END IF; END FOR",
        "FOR d IN (SELECT 1 AS v) PARALLEL 2 DO LEAVE; END FOR",
        "FOR d IN (SELECT 1 AS v) PARALLEL 0 DO SELECT 1; END FOR")]
    checks["a PARALLEL pass that fails fails the loop, naming the pass; LEAVE can't end it; PARALLEL 0 refused"] = \
        "pass 4: no 4" in got["parallel refused"][0] and "can't end a PARALLEL loop" in got["parallel refused"][1] and "1 to 64" in got["parallel refused"][2]
    got["async"] = q("ASYNC INSERT INTO done VALUES (100, 'a');\nASYNC BEGIN INSERT INTO done VALUES (101, 'a'); END;\nAWAIT ALL;\nSELECT count(*) AS c FROM done WHERE w = 'a'", {})
    got["async failed"] = _raises_text(lambda: q("SELECT 1;\nASYNC SELECT 1/0;\nAWAIT ALL", {}))
    q("ASYNC INSERT INTO done VALUES (102, 'e')", {})
    got["async at the end"] = q("SELECT count(*) AS c FROM done WHERE w = 'e'")
    checks["ASYNC runs beside the script and AWAIT ALL waits for it; a failure is AWAIT ALL's, at its line; a script's end waits too"] = \
        got["async"] == [{"c": 2}] and "line 2: ASYNC" in got["async failed"] and "Divide by zero" in got["async failed"] and got["async at the end"] == [{"c": 1}]
    twice = "FOR d IN (SELECT value AS v FROM generate_series(1, 5) ORDER BY 1) PARALLEL 3 DO INSERT INTO done VALUES ($d.v, 'j'); END FOR; ASYNC INSERT INTO done VALUES (9, 'j')"
    q(twice, {}, path="/sql?job=harness-parallel")
    q(twice, {}, path="/sql?job=harness-parallel")
    got["twice"] = q("SELECT count(*) AS c FROM done WHERE w = 'j'")
    checks["PARALLEL passes and ASYNC statements run again with their job write once"] = got["twice"] == [{"c": 6}]
    q("CREATE PROCEDURE nap(s DOUBLE) LANGUAGE python AS $$\nimport time\ntime.sleep(s)\n$$")
    q("CALL nap(0.01)", {})
    timed = {}
    for how in ("", " PARALLEL 8"):
        t0 = time.time()
        q(f"FOR d IN (SELECT value AS v FROM generate_series(1, 8)){how} DO CALL nap(0.3); END FOR", {})
        timed[how.strip() or "one at a time"] = round(time.time() - t0, 2)
    info["eight 0.3 s calls, s"] = timed
    checks["eight 0.3 s calls PARALLEL 8 take under 0.6 of the time one at a time does"] = timed["PARALLEL 8"] < 0.6 * timed["one at a time"]
    # ASYNC beside what follows it, AWAIT ALL in a block, handles, and runs pondra.start started.
    t0 = time.time()
    q("ASYNC CALL nap(0.4);\nCALL nap(0.4)", {})
    timed["ASYNC beside a call"] = round(time.time() - t0, 2)
    got["await in a block"], _ = said("BEGIN\n  ASYNC BEGIN CALL nap(0.2); PRINT 'async done'; END;\n  AWAIT ALL;\n  PRINT 'after AWAIT ALL';\nEND")
    got["handles"], _ = said("$a = ASYNC BEGIN CALL nap(0.2); PRINT 'a done'; END;\n$b = ASYNC SELECT 1/0;\nAWAIT $a;\nPRINT 'after AWAIT $a';\n"
                             "BEGIN\n  AWAIT $b;\nEXCEPTION WHEN OTHERS THEN\n  PRINT 'b: ' || $sqlstate;\nEND")
    checks["ASYNC runs beside what follows; AWAIT ALL in a block waits; AWAIT $h waits for its own, raising its error once"] = (
        timed["ASYNC beside a call"] < 0.7 and got["await in a block"] == ["async done", "after AWAIT ALL"]
        and got["handles"] == ["a done", "after AWAIT $a", "b: 22012"])
    q("CREATE PROCEDURE oops() LANGUAGE sql AS $$ SELECT 1/0 $$")
    ran, failed = q("SELECT pondra.start('nap', 0.3) AS id")[0]["id"], q("SELECT pondra.start('oops') AS id")[0]["id"]
    q(f"AWAIT '{ran}'", {})
    got["awaited run"] = q(f"SELECT status FROM pondra.runs WHERE id = '{ran}'")
    got["awaited failure"] = _raises_text(lambda: q(f"AWAIT '{failed}'", {}))
    checks["AWAIT 'id' waits for a run pondra.start started, with its error if it failed"] = (
        got["awaited run"] == [{"status": "ok"}] and "Divide by zero" in got["awaited failure"])
    # VALUES with a subquery in a row (DataFusion worked the rows out before the subquery ran): in a
    # loop, a transaction, over Postgres with a parameter, and as a query.
    q("CREATE TABLE tally (k BIGINT, n BIGINT)")
    q("FOR d IN (SELECT value AS v FROM generate_series(1, 3)) DO INSERT INTO tally VALUES ($d.v, (SELECT count(*) FROM tally)); END FOR", {})
    q("BEGIN; INSERT INTO tally (n, k) VALUES ((SELECT max(n) FROM tally), 4); COMMIT", {})
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=pondra dbname=pondra", autocommit=True) as c:
        c.execute("INSERT INTO tally VALUES (%s, (SELECT count(*) FROM tally))", (5,))
    got["tally"] = q("SELECT k, n FROM tally ORDER BY k")
    got["values"] = q("SELECT * FROM (VALUES ((SELECT count(*) FROM tally), 'rows'), (0, 'none')) ORDER BY column1 DESC")
    checks["VALUES with a subquery: in a loop, a transaction, over Postgres, as a query"] = (
        got["tally"] == [{"k": 1, "n": 0}, {"k": 2, "n": 1}, {"k": 3, "n": 2}, {"k": 4, "n": 2}, {"k": 5, "n": 4}]
        and got["values"] == [{"column1": 5, "column2": "rows"}, {"column1": 0, "column2": "none"}])
    # The ways people write it (the design review): a bare END closes any block, FOR $r, SET $x = and
    # :=, AWAIT alone waits for all; END of another kind where a block ends is refused.
    got["forgiving"] = q("""BEGIN
  DECLARE $t INT := 0;
  FOR $r IN (SELECT value AS v FROM generate_series(1, 4)) DO
    IF $r.v % 2 = 0 THEN SET $t = $t + $r.v; END;
  END;
  ASYNC INSERT INTO tally VALUES (100, 0);
  AWAIT;
  $t := $t * 10;
  SELECT $t AS t, (SELECT count(*) FROM tally WHERE k = 100) AS async;
END""", {})
    got["wrong end"] = _raises_text(lambda: q("BEGIN IF true THEN SELECT 1; END LOOP; END", {}))
    checks["written as people write it: a bare END closes any block, FOR $r, SET $x = and :=, AWAIT alone; END LOOP where an IF ends is refused"] = (
        got["forgiving"] == [{"t": 60, "async": 1}] and "END LOOP where the IF" in got["wrong end"])
    # What deciding costs: a loop that reads only variables.
    t0 = time.time()
    q("DECLARE $i = 0; WHILE $i < 200 DO $i = $i + 1; END WHILE", {})
    info["per pass ms"] = round((time.time() - t0) * 1000 / 200, 3)
    info["got"] = got
    node.kill()
    ok = all(checks.values())
    print(json.dumps({"scripts": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"scripts: blocks, branches, loops, handlers, RETURN, dynamic SQL, PARALLEL and ASYNC, from HTTP, Python and Postgres: all {len(checks)} checks pass"


def tasks():
    """Task graphs (ADR-045 §5) on three nodes: tasks AFTER others run in the same run of their
    graph, with `EXECUTE TASK`'s values (`$day`) and the results before them (`pondra.result`), sent
    from a follower; WHEN false skips a task and what follows it still runs; retries with the same
    job (what a try wrote lands once), refused while a run is under way; a timeout, on_failure and
    nothing after a failure; ALTER TASK SUSPEND and RESUME; refusals (a loop, two schedules, a
    missing task, DROP of a followed one, a schedule too long to count or that never comes); a graph through a leader failover, each write once."""
    lake = new_lake()
    py = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "python")
    nodes = [Node(lake, A.port + i, python=sys.executable, env={"PYTHONPATH": py}).start() for i in range(3)]
    time.sleep(1)
    q = lambda s, port=A.port: call(port, "POST", "/sql", s.encode(), timeout=60)
    def err(s, port=A.port):
        try:
            q(s, port)
            return ""
        except RuntimeError as e:
            return str(e)
    def status(name, port=A.port):
        r = q(f"SELECT last_status AS s FROM pondra.tasks WHERE name = '{name}'", port)
        return r[0].get("s") if r else None
    checks, got = {}, {}
    # A graph: root, then load and skipper, then report.
    q("CREATE TABLE glog (task VARCHAR, v BIGINT, day DATE)")
    q("CREATE TASK root SCHEDULE '1 hour' AS SELECT 2 AS v")
    q("CREATE TASK load AFTER root AS BEGIN DECLARE PARAMETER $day DATE = DATE '2026-01-01'; INSERT INTO glog VALUES ('load', pondra.result('root'), $day); RETURN 20; END")
    q("CREATE TASK skipper AFTER root WHEN pondra.result('root') > 5 AS INSERT INTO glog VALUES ('skipper', 0, $day)")
    q("CREATE TASK report AFTER load, skipper AS BEGIN DECLARE PARAMETER $day DATE = DATE '2026-01-02'; INSERT INTO glog VALUES ('report', pondra.result('load'), $day); END")
    ran = q("EXECUTE TASK root (day => DATE '2026-09-01')", A.port + 2)
    until(lambda: status("report"), "ok", 30)
    got["graph"] = q("SELECT task, v, CAST(day AS VARCHAR) AS day FROM glog ORDER BY task")
    got["statuses"] = {r["name"]: r.get("last_status") for r in q("SELECT name, last_status FROM pondra.tasks WHERE name IN ('root', 'load', 'skipper', 'report')")}
    got["runs"] = q("SELECT routine, status FROM pondra.runs WHERE id LIKE 'task-%' ORDER BY routine")
    at = ran.get("run", "").rsplit("-", 1)[-1] if isinstance(ran, dict) else ""
    checks["a graph from a follower's EXECUTE TASK: AFTER in order, $day and pondra.result passed on, WHEN false skipped and what follows still runs"] = (
        got["graph"] == [{"task": "load", "v": 2, "day": "2026-09-01"}, {"task": "report", "v": 20, "day": "2026-09-01"}]
        and got["statuses"] == {"root": "ok", "load": "ok", "skipper": "skipped", "report": "ok"}
        and got["runs"] == [{"routine": n, "status": s} for n, s in (("load", "ok"), ("report", "ok"), ("root", "ok"), ("skipper", "skipped"))]
        and bool(at) and q(f"SELECT count(*) AS n FROM pondra.runs WHERE id LIKE 'task-%-{at}'")[0]["n"] == 4)
    q("EXECUTE TASK root")
    until(lambda: q("SELECT count(*) AS n FROM glog")[0]["n"], 4, 30)
    got["defaults"] = q("SELECT task, CAST(day AS VARCHAR) AS day FROM glog WHERE day < DATE '2026-09-01' ORDER BY task")
    checks["a run with no values: each task that is one block takes its DECLARE PARAMETER's default"] = got["defaults"] == [{"task": "load", "day": "2026-01-01"}, {"task": "report", "day": "2026-01-02"}]
    # Retries: the same job, so what a try wrote lands once; a run under way refuses EXECUTE TASK.
    q("CREATE TABLE tries (n BIGINT)")
    ready = time.time() + 2.5
    q(f"CREATE TASK flaky SCHEDULE '1 hour' WITH (retries = 4, retry_delay = '1 second') AS BEGIN INSERT INTO tries VALUES (1); IF date_part('epoch', now()) < {ready} THEN RAISE 'not yet'; END IF; END")
    q("EXECUTE TASK flaky")
    got["again"] = err("EXECUTE TASK flaky")
    until(lambda: status("flaky"), "ok", 30)
    run = q("SELECT status, notices FROM pondra.runs WHERE routine = 'flaky'")
    got["flaky"] = run
    checks["retries: failed tries said in the run's notices, then ok, what they wrote once; EXECUTE TASK refused while it runs"] = (
        "is running" in got["again"] and len(run) == 1 and run[0]["status"] == "ok" and "try 1 failed" in (run[0].get("notices") or "")
        and q("SELECT count(*) AS n FROM tries")[0]["n"] == 1)
    # A timeout, on_failure, and nothing after a failure.
    q("CREATE TABLE failures (t VARCHAR, e VARCHAR)")
    q("CREATE PROCEDURE failed(t VARCHAR, e VARCHAR) LANGUAGE sql AS $$ INSERT INTO failures VALUES ($t, $e) $$")
    q("CREATE TASK slow SCHEDULE '1 hour' WITH (timeout = '1 second', on_failure = failed) AS BEGIN DECLARE $i = 0; LOOP $i = $i + 1; END LOOP; END")
    q("CREATE TASK after_slow AFTER slow AS INSERT INTO glog VALUES ('after_slow', 0, NULL)")
    q("EXECUTE TASK slow")
    until(lambda: status("slow"), "failed", 30)
    time.sleep(1.5)
    got["failures"] = q("SELECT t, e FROM failures")
    got["slow"] = q("SELECT status, error FROM pondra.runs WHERE routine = 'slow'")
    checks["a timeout fails the run, on_failure is called with the task and its error, and what follows doesn't run"] = (
        got["failures"] == [{"t": "slow", "e": "timed out after 1 s"}] and got["slow"][0]["status"] == "failed"
        and "timed out" in (got["slow"][0].get("error") or "") and status("after_slow") is None
        and q("SELECT count(*) AS n FROM glog WHERE task = 'after_slow'")[0]["n"] == 0)
    # SUSPEND and RESUME.
    q("CREATE TABLE beats (n BIGINT)")
    q("CREATE TASK beat SCHEDULE '1 second' AS INSERT INTO beats VALUES (1)")
    time.sleep(3)
    q("ALTER TASK beat SUSPEND")
    time.sleep(1.5)
    n1 = q("SELECT count(*) AS n FROM beats")[0]["n"]
    state = q("SELECT state FROM pondra.tasks WHERE name = 'beat'")[0]["state"]
    time.sleep(2.5)
    n2 = q("SELECT count(*) AS n FROM beats")[0]["n"]
    q("ALTER TASK beat RESUME", A.port + 1)
    time.sleep(3)
    n3 = q("SELECT count(*) AS n FROM beats")[0]["n"]
    q("DROP TASK beat")
    got["beats"] = [n1, n2, n3, state]
    checks["ALTER TASK SUSPEND stops its ticks, RESUME starts them again"] = n1 > 0 and n2 == n1 and n3 > n2 and state == "suspended"
    # A body is kept as written: sqlparser read COPY's bare OVERWRITE as a missing option's value.
    q("CREATE TASK snap SCHEDULE '1 day' AS COPY (SELECT * FROM glog) TO 'out/snap' (FORMAT delta, OVERWRITE)")
    kept = q("SELECT statement FROM pondra.tasks WHERE name = 'snap'")
    q("DROP TASK snap")
    checks["a task's statement is kept as written: COPY … (FORMAT delta, OVERWRITE)"] = bool(kept) and "(FORMAT delta, OVERWRITE)" in kept[0].get("statement", "")
    # From the clients: Python's db.task, @db.task (a procedure the task calls) and execute_task's Run;
    # JavaScript's task, executeTask and wait.
    q("CREATE TABLE clog (who VARCHAR, day DATE)")
    nb = os.path.join(tempfile.mkdtemp(prefix="pondra-tasks-"), "tasks.py")
    open(nb, "w").write(f"""import json
from datetime import date
import pondra
db = pondra.connect("http://127.0.0.1:{A.port + 1}")
db.task("croot", "INSERT INTO clog VALUES ('sql', $day)", schedule="1 hour")

@db.task(after="croot", retries=1)
def cnext():
    pondra.sql("INSERT INTO clog VALUES ('python', NULL)")

ran = db.execute_task("croot", day=date(2026, 9, 2))
print(json.dumps(ran.wait(timeout=30)["status"]))
""")
    ran = subprocess.run([sys.executable, nb], capture_output=True, text=True, timeout=120, env={**os.environ, "PYTHONPATH": py})
    until(lambda: status("cnext"), "ok", 30)
    js = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "js", "index.js")
    script = f"""import {{ connect }} from {json.dumps(js)};
const db = connect("http://127.0.0.1:{A.port + 2}");
await db.task("jroot", "INSERT INTO clog VALUES ('js', $day)", {{ schedule: "1 hour", retries: 1, timeout: "10 minutes" }});
await db.task("jnext", "INSERT INTO clog VALUES ('js after', $day)", {{ after: ["jroot"], when: "true" }});
await db.wait(await db.executeTask("jroot", {{ day: "2026-09-03" }}));
console.log("done"); await db.close();"""
    path = os.path.join(tempfile.mkdtemp(prefix="pondra-tasks-"), "tasks.mjs")
    open(path, "w").write(script)
    js_out = subprocess.run(["node", path], capture_output=True, text=True, timeout=120)
    until(lambda: status("jnext"), "ok", 30)
    got["clients"] = {"python": ran.stdout.strip() or ran.stderr[-800:], "js": js_out.stdout.strip() or js_out.stderr[-800:],
                      "rows": q("SELECT who, CAST(day AS VARCHAR) AS day FROM clog ORDER BY who"),
                      "options": q("SELECT name, after, options FROM pondra.tasks WHERE name IN ('cnext', 'jroot') ORDER BY name")}
    checks["from the clients: Python's db.task, @db.task and execute_task(…).wait(); JavaScript's task, executeTask and wait"] = (
        got["clients"]["python"] == '"ok"' and got["clients"]["js"] == "done"
        and got["clients"]["rows"] == [{"who": "js", "day": "2026-09-03"}, {"who": "js after", "day": "2026-09-03"}, {"who": "python"}, {"who": "sql", "day": "2026-09-02"}])
    # Refusals.
    got["refused"] = refused = {
        "itself": err("CREATE TASK me AFTER me AS SELECT 1"),
        "a loop": err("CREATE OR REPLACE TASK root AFTER report AS SELECT 1"),
        "two schedules": err("CREATE TASK both AFTER root, flaky AS SELECT 1"),
        "missing": err("CREATE TASK lost AFTER nothing AS SELECT 1"),
        "followed": err("DROP TASK load"),
        "no task": err("EXECUTE TASK nothing"),
        "an option": err("CREATE TASK opt SCHEDULE '1 hour' WITH (tries = 2) AS SELECT 1"),
        # (taken, 4611686018427387904 minutes wrapped around to 0 s and the leader's loop divided by
        # it: the node stopped, and again each time it started)
        "too long": err("CREATE TASK huge SCHEDULE '4611686018427387904 minutes' AS SELECT 1"),
        "never": err("CREATE TASK feb30 SCHEDULE 'cron 0 0 30 2 *' AS SELECT 1"),
    }
    checks["refused by name: a task after itself, a loop, two schedules, a missing task, DROP of a followed one, EXECUTE of none, an unknown option, "
           "a schedule past a hundred years or a day that never comes (the nodes still up)"] = (
        "follow itself" in refused["itself"] and "follow itself" in refused["a loop"] and "2 different schedules" in refused["two schedules"]
        and "no task nothing" in refused["missing"] and "runs after load" in refused["followed"] and "no task nothing" in refused["no task"]
        and "retries, retry_delay" in refused["an option"] and "a hundred years" in refused["too long"] and "never comes" in refused["never"]
        and (time.sleep(1.5) or all(n.alive() for n in nodes)) and status("root") == "ok")
    # A graph through a leader failover: the task under way runs again on the new leader, with its job.
    q("CREATE TABLE flog (task VARCHAR, v BIGINT)")
    q("CREATE TASK froot SCHEDULE '1 hour' AS SELECT 1")
    q("CREATE TASK fload AFTER froot AS BEGIN INSERT INTO flog VALUES ('fload', 1); WHILE date_part('epoch', now()) < $until DO $i = 1; END WHILE; RETURN 7; END")
    q("CREATE TASK freport AFTER fload AS INSERT INTO flog VALUES ('freport', pondra.result('fload'))")
    q(f"EXECUTE TASK froot (until => {time.time() + 6})", A.port + 1)
    until(lambda: q("SELECT count(*) AS n FROM flog")[0]["n"], 1, 15)
    nodes[0].kill()
    leader = None
    deadline = time.time() + 60
    while leader is None and time.time() < deadline:
        for n in nodes[1:]:
            try:
                if call(n.port, "GET", "/stats", timeout=2)["role"] == "leader":
                    leader = n
            except Exception:
                pass
        time.sleep(0.5)
    port = leader.port if leader else A.port + 1
    until(lambda: status("freport", port), "ok", 60)
    got["failover"] = q("SELECT task, v FROM flog ORDER BY task", port)
    got["failover runs"] = q("SELECT routine, status FROM pondra.runs WHERE routine IN ('froot', 'fload', 'freport') ORDER BY routine", port)
    checks["a graph through a leader failover: the task under way runs again on the new leader, each write once, and what follows gets its result"] = (
        leader is not None and got["failover"] == [{"task": "fload", "v": 1}, {"task": "freport", "v": 7}]
        and [r["status"] for r in got["failover runs"]] == ["ok", "ok", "ok"])
    for n in nodes:
        n.kill()
    ok = all(checks.values())
    print(json.dumps({"tasks": checks, "ok": ok, "got": got}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"tasks: graphs, WHEN, results, values, retries, timeouts, on_failure, SUSPEND, refusals, a failover: all {len(checks)} checks pass"


def variables():
    """SQL variables (round 31): `DECLARE $day DATE = …` declares one (type and default optional),
    `$day = …` changes it, and every `$day` after is its value, bound, from every door (HTTP with a
    session, Postgres, Python's `db.vars`); DuckDB's `SET VARIABLE`, `getvariable` and `RESET
    VARIABLE` are the same. A file's `DECLARE PARAMETER`s are its parameters (`pondra.parameters(…)`,
    ADR-044): a run's given values replace their defaults, cast to their types; a plain `DECLARE` is
    the file's own, and a value given for it is refused; a `.py` file's are its `# %%
    tags=["parameters"]` cell's. Procedures and file runs have variables of their own; `SET` stays
    the settings'."""
    import datetime
    import psycopg
    lake = new_lake()
    here = os.path.dirname(os.path.abspath(__file__))
    pg = A.port + 10
    node = Node(lake, A.port, pg=f"127.0.0.1:{pg}", python="auto", env={"PYTHONPATH": os.path.join(here, "..", "python")}).start()
    s1, s2 = {"x-pondra-session": "harness-vars-one"}, {"x-pondra-session": "harness-vars-two"}
    q = lambda s, h=s1: call(A.port, "POST", "/sql", s.encode(), headers=h)
    checks, info = {}, {}
    q("CREATE TABLE orders (id BIGINT, day DATE, amount DOUBLE)")
    q("INSERT INTO orders VALUES (1, DATE '2026-09-29', 10), (2, DATE '2026-09-30', 20), (3, DATE '2026-09-30', 5)")
    got = {"declared": q("DECLARE $day DATE = DATE '2026-10-01' - INTERVAL '1 day'"), "used": q("SELECT sum(amount) AS total FROM orders WHERE day = $day"),
           "named": q("SELECT $day, $day + 1")}
    got["changed"] = q("$day = $day - 1")
    got["after"] = q("SELECT sum(amount) AS total FROM orders WHERE day = $day")
    got["typed"] = _raises_text(lambda: q("$day = 'not a day'"))
    got["other session"] = _raises_text(lambda: q("SELECT $day", s2))
    got["no session"] = _raises_text(lambda: q("DECLARE $x = 1", {}))
    got["one script"] = q("DECLARE $n BIGINT = 2; $n = $n * 21; SELECT $n AS n", {})
    got["duckdb"] = q("SET VARIABLE region = 'eu'; SELECT getvariable('region') AS r, $region AS s, getvariable('nope') AS none")
    q("RESET VARIABLE region")
    got["reset"] = _raises_text(lambda: q("SELECT $region"))
    q("SET datafusion.execution.batch_size = 4096")  # (a setting, not a variable)
    got["listed"] = q("SELECT name, value, type, declared FROM pondra.variables ORDER BY name")
    q("$day = DATE '2026-09-30'")
    got["listed again"] = q("SELECT name, value, type, declared FROM pondra.variables ORDER BY name")
    checks["DECLARE $day DATE = …: its value, worked out once, in WHERE and SELECT; $day = … changes it"] = \
        got["declared"] == {"variable": "day", "value": "2026-09-30", "type": "Date32"} and got["used"] == [{"total": 25.0}] \
        and got["changed"]["value"] == "2026-09-29" and got["after"] == [{"total": 10.0}]
    checks["a column of a variable is named as written ($day, $day + 1)"] = got["named"] == [{"$day": "2026-09-30", "$day + 1": "2026-10-01"}]
    checks["a declared type holds: a value that isn't one refused by name"] = "$day is DATE" in got["typed"]
    checks["a variable is its session's: another session doesn't have it; with none, a DECLARE says so; a script sent at once has its own"] = \
        "no value for $day" in got["other session"] and "session" in got["no session"] and got["one script"] == [{"n": 42}]
    checks["DuckDB's SET VARIABLE, getvariable (NULL if none) and RESET VARIABLE"] = got["duckdb"] == [{"r": "eu", "s": "eu"}] and "no value for $region" in got["reset"]
    checks["pondra.variables lists them (name, value, type, declared), never a remembered answer; SET is still a setting"] = \
        got["listed"] == [{"name": "day", "value": "2026-09-29", "type": "Date32", "declared": "DATE"}] \
        and got["listed again"] == [{"name": "day", "value": "2026-09-30", "type": "Date32", "declared": "DATE"}]
    # A file's parameters, and runs.
    daily = ("-- The day to load\nDECLARE PARAMETER $day DATE = DATE '2026-09-29';\n-- $region: where the orders come from\nDECLARE PARAMETER $min DOUBLE DEFAULT 0;\n"
             "SELECT count(*) AS n, sum(amount) AS total, $region AS region FROM orders WHERE day = $day AND amount >= $min;\n")
    call(A.port, "PUT", "/files/etl/daily.sql", daily.encode())
    got["parameters"] = q("SELECT * FROM pondra.parameters('etl/daily.sql')")
    call(A.port, "PUT", "/files/etl/sensors.sql", b"DECLARE PARAMETER $d VARCHAR = 's1'; -- the sensor\nDECLARE PARAMETER $cel INT;\n\nSELECT $d AS d, $cel AS cel;\n")
    own = b"DECLARE PARAMETER $day DATE = DATE '2026-09-29';\nDECLARE $since = $day - 1; -- the day before\nDECLARE $n BIGINT;\nSELECT $since AS since, $n AS n;\n"
    call(A.port, "PUT", "/files/etl/own.sql", own)
    got["own parameters"] = q("SELECT name FROM pondra.parameters('etl/own.sql')")
    got["own run"] = q("CALL run('etl/own.sql', day => '2026-09-30')")
    got["own refused"] = _raises_text(lambda: q("CALL run('etl/own.sql', since => '2026-09-01')"))
    got["own given"] = _raises_text(lambda: call(A.port, "POST", "/sql", json.dumps({"sql": own.decode(), "params": {"since": "2026-09-01"}}).encode(), headers={**s2, "content-type": "application/json"}))
    params_py = (b"import pondra\n\n# %% tags=[\"parameters\"]\n# the day to load\nday = \"2026-09-29\"\nlimit: int = 2  # how many\n\n"
                 b"# %%\nprint('got', day, limit)\n")
    call(A.port, "PUT", "/files/etl/params.py", params_py)
    got["py parameters"] = q("SELECT * FROM pondra.parameters('etl/params.py')")
    got["described after"] = q("SELECT name, description FROM pondra.parameters('etl/sensors.sql')")
    got["run given"] = q("CALL run('etl/daily.sql', region => 'eu', day => '2026-09-30', min => 6)")
    got["run defaults"] = q("CALL run('etl/daily.sql', region => 'us')")
    got["run missing"] = _raises_text(lambda: q("CALL run('etl/daily.sql')"))
    got["session after runs"] = q("SELECT name, value FROM pondra.variables ORDER BY name")
    checks["a file's parameters: its DECLAREs (type, default) and the $names it uses unset (required), the comment above each its description, in order"] = got["parameters"] == [
        {"name": "day", "type": "DATE", "default": "DATE '2026-09-29'", "required": False, "description": "The day to load"},
        {"name": "min", "type": "DOUBLE", "default": "0", "required": False},
        {"name": "region", "required": True, "description": "where the orders come from"}]
    checks["a comment after a DECLARE on its line describes it, and not the DECLARE after it"] = \
        got["described after"] == [{"name": "d", "description": "the sensor"}, {"name": "cel"}]
    checks["a plain DECLARE is the file's own: not a parameter, NULL with no default, and a value given for it refused (a run's, a request's)"] = \
        got["own parameters"] == [{"name": "day"}] and got["own run"] == [{"since": "2026-09-29"}] \
        and "has no parameter since (it takes $day)" in got["own refused"] and "declares as its own variable" in got["own given"]
    checks["a .py file's parameters are its # %% tags=[\"parameters\"] cell's (types from annotations and literals, comments as descriptions)"] = got["py parameters"] == [
        {"name": "day", "type": "VARCHAR", "default": '"2026-09-29"', "required": False, "description": "the day to load"},
        {"name": "limit", "type": "BIGINT", "default": "2", "required": False, "description": "how many"}]
    checks["a run's values replace the defaults, cast to their types; a required one missing is named; the run's variables stay its own"] = \
        got["run given"] == [{"n": 1, "total": 20.0, "region": "eu"}] and got["run defaults"] == [{"n": 1, "total": 10.0, "region": "us"}] \
        and "no value for $region" in got["run missing"] and got["session after runs"] == [{"name": "day", "value": "2026-09-30"}]
    # Procedures.
    q("CREATE PROCEDURE twice(n BIGINT) LANGUAGE sql AS $$ DECLARE $m = $n * 2; $m = $m + 1; SELECT $m AS m, $1 AS first $$")
    got["procedure"] = q("CALL twice(21)")
    got["procedure refused"] = _raises_text(lambda: q("CREATE PROCEDURE broken() LANGUAGE sql AS $$ SELECT $nowhere $$"))
    checks["a procedure declares variables of its own; one using a $name nothing gives it is refused when made"] = \
        got["procedure"] == [{"m": 43, "first": 21}] and "no value for $nowhere" in got["procedure refused"] and "m" not in [r["name"] for r in q("SELECT name FROM pondra.variables")]
    # Postgres: each connection its own.
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=pondra dbname=pondra", autocommit=True) as c:
        cur = c.execute("DECLARE $day DATE = DATE '2026-09-29'")
        tag = cur.statusmessage
        simple = c.execute("SELECT count(*) FROM orders WHERE day = $day").fetchall()
        c.execute("$day = $day + 1")
        extended = c.execute("SELECT count(*) FROM orders WHERE day = $day AND amount > %s", (6,)).fetchall()
    checks["over Postgres: DECLARE (its tag), $day = …, and $day beside the protocol's own parameters"] = tag == "DECLARE" and simple == [(1,)] and extended == [(1,)]
    # Python: db.vars, and a file run's Python and a session's DO block.
    db = _client(A.port)
    db.sql("DECLARE $day DATE = DATE '2026-09-30'")
    first = db.vars.day
    db.vars.day = datetime.date(2026, 9, 29)
    db.vars.limit = 3
    listed = dict(db.vars)
    del db.vars.limit
    total = db.sql("SELECT sum(amount) AS t FROM orders WHERE day = $day").rows()
    call(A.port, "PUT", "/files/etl/load.py", b"import pondra\nprint('given', pondra.vars.day)\npondra.vars.seen = 41\nprint(pondra.sql('SELECT $seen + 1 AS x').rows())\n")
    db.run("etl/load.py", day="2026-10-01")
    ran = list(db.notices)
    db.run("etl/params.py", limit=5)
    params_ran = list(db.notices)
    try:
        db.run("etl/params.py", nope=1)
        params_refused = ""
    except Exception as e:
        params_refused = str(e)
    info["params.py"] = {"ran": params_ran, "refused": params_refused}
    checks["a .py file's run: its parameters cell, then the values given over its defaults, then the rest; a name it doesn't take refused"] = \
        params_ran == ["got 2026-09-29 5"] and "has no parameter nope (it takes day, limit)" in params_refused
    db.sql("DO LANGUAGE python $$\nimport pondra\nprint('do', pondra.vars.day)\n$$")
    did = list(db.notices)
    info["python"] = {"first": str(first), "listed": {k: str(v) for k, v in listed.items()}, "total": total, "ran": ran, "did": did, "after": sorted(db.vars)}
    checks["Python's db.vars reads, sets and forgets $day; a file run's Python sees its given values as pondra.vars; a session's DO block sees the session's"] = \
        first == datetime.date(2026, 9, 30) and listed == {"day": datetime.date(2026, 9, 29), "limit": 3} and total == [{"t": 10.0}] \
        and ran == ["given 2026-10-01", "[{'x': 42}]"] and did == ["do 2026-09-29"] and sorted(db.vars) == ["day"]
    js = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "js", "index.js")
    script = f"""import {{ connect }} from {json.dumps(js)};
const db = connect("http://127.0.0.1:{A.port}");
await db.sql("DECLARE $day DATE = DATE '2026-09-29'"); await db.setVariable("top", 2);
const all = await db.vars(), top = await db.getVariable("top"), rows = await db.sql("SELECT count(*) AS n, $top * 10 AS t FROM orders WHERE day = $day");
await db.resetVariable("top");
console.log(JSON.stringify([all, top, rows, await db.vars(), (await db.parameters("etl/daily.sql")).map(p => p.name)])); await db.close();"""
    path = os.path.join(tempfile.mkdtemp(prefix="pondra-vars-"), "vars.mjs")
    open(path, "w").write(script)
    js_out = subprocess.run(["node", path], capture_output=True, text=True, timeout=60)
    got["javascript"] = js_out.stdout.strip() or js_out.stderr[-1500:]
    checks["JavaScript: db.vars(), getVariable, setVariable, resetVariable, parameters"] = \
        got["javascript"] == json.dumps([{"day": "2026-09-29", "top": 2}, 2, [{"n": 1, "t": 20}], {"day": "2026-09-29"}, ["day", "min", "region"]], separators=(",", ":"))
    got["shapes"] = q("DECLARE $b BYTEA = X'DEADBEEF'; DECLARE $ids = [3, 1, NULL]; DECLARE $s = named_struct('a', 1, 'b', 'x'); "
                      "SELECT encode($b, 'hex') AS hex, array_has($ids, 3) AS has, cardinality($ids) AS n, $s['b'] AS b")
    got["a map"] = _raises_text(lambda: q("DECLARE $m = MAP {'a': 1}"))
    checks["a variable holds bytes as they are (not their hex's text), a list or a struct; a map is refused by name"] = \
        got["shapes"] == [{"hex": "deadbeef", "has": True, "n": 3, "b": "x"}] and "be passed as a value yet" in got["a map"]
    info["got"] = got
    node.kill()
    ok = all(checks.values())
    print(json.dumps({"variables": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"variables: DECLARE $day, $day = …, from HTTP, Postgres and Python; a file's parameters; runs and procedures of their own: all {len(checks)} checks pass"

def use_path():
    """USE and a session's search path (round 34, `path.rs`): `USE crm` makes crm the session's
    schema, `USE dev` a database (an attached lake, its public), `USE dev.sales` both; `USE DATABASE`
    and `USE SCHEMA` when a name is both; `SET search_path TO crm, public` and `SET SCHEMA 'crm'` are
    the same setting. A one-part name is looked for there and a new object goes to its first schema;
    the names are written in where SQL comes in, so views, tasks, the result cache and spread queries
    see full names. Over HTTP, Postgres, the Python client and the shell (one session until it quits);
    refused by name without a session; a spread query from a follower's session on three nodes."""
    import psycopg
    lake = new_lake()
    other = f"{lake}-other"  # (a database made beside this lake: CREATE DATABASE, attached)
    LAKES.append(other)
    db_name = lake.rstrip("/").rsplit("/", 1)[-1].lower()  # (current_database(): the lake's name, its folder's)
    node = Node(lake, A.port, pg=f"127.0.0.1:{A.port + 10}").start()
    q = lambda s, h=None: call(A.port, "POST", "/sql", s.encode(), headers=h or {})
    def http(body, session=None):
        c = http_client.HTTPConnection("127.0.0.1", A.port, timeout=60)
        c.request("POST", "/sql", body.encode(), {"x-pondra-session": session} if session else {})
        r = c.getresponse()
        data = r.read()
        return r.status, r.getheader("x-pondra-sqlstate"), (json.loads(data) if data[:1] in (b"{", b"[") else data.decode())
    checks, info = {}, {}
    # crm.t has two rows, public.t five; public's are none of them a = 1, so a lookup shows which one it read.
    q("CREATE SCHEMA crm")
    q("CREATE TABLE crm.t (a INT)")
    q("INSERT INTO crm.t VALUES (1), (2)")
    q("CREATE TABLE t (a INT)")
    q("INSERT INTO t VALUES (11), (12), (13), (14), (15)")
    # USE crm, the names it gives, SHOW, RESET.
    h1 = {"x-pondra-session": "use-one-1"}
    q("USE crm", h1)
    info["crm"] = q("SELECT count(*) AS n FROM t", h1)
    info["names"] = q("SELECT current_schema() AS s, current_database() AS d", h1)
    info["shown"] = q("SHOW search_path", h1)
    q("RESET search_path", h1)
    info["reset"] = q("SELECT count(*) AS n FROM t", h1)
    checks["USE crm: a one-part name is crm's (2 rows, not public's 5); current_schema() and current_database() say so; SHOW search_path shows it; RESET gives public back"] = \
        info["crm"] == [{"n": 2}] and info["names"] == [{"s": "crm", "d": db_name}] and info["shown"] == [{"search_path": "crm"}] and info["reset"] == [{"n": 5}]
    # The result cache is keyed by the text the engine runs: the same text, under USE crm and not, in turns and at once.
    a, b = {"x-pondra-session": "use-cache-a"}, {"x-pondra-session": "use-cache-b"}
    q("USE crm", a)
    count = lambda h: q("SELECT count(*) AS n FROM t", h)[0]["n"]
    info["turns"] = [count(h) for _ in range(3) for h in (a, b)]
    at_once = {}
    def many(key, h):
        at_once[key] = [count(h) for _ in range(3)]
    threads = [threading.Thread(target=many, args=(k, h)) for k, h in (("a", a), ("b", b))]
    [t.start() for t in threads]
    [t.join() for t in threads]
    info["at once"] = at_once
    checks["the result cache isn't fooled: the same text under USE crm (2) and without (5), in turns and in two sessions at once"] = \
        info["turns"] == [2, 5] * 3 and at_once == {"a": [2, 2, 2], "b": [5, 5, 5]}
    # Writes and DDL go to the session's schema.
    w = {"x-pondra-session": "use-write-1"}
    q("USE crm", w)
    q("INSERT INTO t VALUES (9)", w)
    q("UPDATE t SET a = 10 WHERE a = 9", w)
    q("CREATE TABLE u (b INT)", w)
    q("CREATE VIEW v AS SELECT count(*) AS n FROM t", w)
    q("CREATE SEQUENCE s", w)
    info["nextval"] = q("SELECT nextval('s') AS v", w)
    info["crm rows"] = q("SELECT a FROM crm.t ORDER BY a")
    info["crm u"] = q("SELECT count(*) AS n FROM crm.u")
    info["crm v"] = q("SELECT n FROM crm.v")
    info["public rows"] = q("SELECT count(*) AS n FROM public.t")
    info["next crm"] = q("SELECT nextval('crm.s') AS v")
    checks["writes and DDL under USE crm land in crm: INSERT, UPDATE, CREATE TABLE, VIEW, SEQUENCE; public's five rows are untouched"] = \
        info["nextval"] == [{"v": 1}] and info["crm rows"] == [{"a": 1}, {"a": 2}, {"a": 10}] and info["crm u"] == [{"n": 0}] \
        and info["crm v"] == [{"n": 3}] and info["public rows"] == [{"n": 5}] and info["next crm"] == [{"v": 2}]
    # Spark SQL's text and SHOW COLUMNS are placed as any statement is.
    info["spark_sql under USE crm"] = q("SELECT * FROM spark_sql('SELECT count(*) AS n FROM t')", w)
    info["columns under USE crm"] = [r.get("column_name") for r in q("SHOW COLUMNS FROM u", w)]
    checks["under USE crm, spark_sql('…')'s text reads crm.t (3, not 5) and SHOW COLUMNS FROM u shows crm.u's"] = \
        info["spark_sql under USE crm"] == [{"n": 3}] and info["columns under USE crm"] == ["b"]
    # A view's current_schema() is its reader's, as Postgres works it out when the view is read; a
    # materialized view's is the one it was made under (its rows are made then). The result cache
    # keeps the readers apart.
    q("CREATE VIEW cs AS SELECT current_schema() AS s, current_database() AS d")  # (made in public, no session)
    q("CREATE MATERIALIZED VIEW csm AS SELECT a, current_schema() AS s FROM t", w)
    info["cs, no path"] = q("SELECT s, d FROM cs")
    info["cs, USE crm"] = q("SELECT s, d FROM public.cs", w)
    info["cs, in turns"] = [q("SELECT s FROM public.cs", h)[0]["s"] for _ in range(2) for h in (None, w)]
    info["csm"] = q("SELECT DISTINCT s FROM crm.csm")
    info["cs kept"] = "current_schema()" in json.dumps(q("SHOW CREATE VIEW cs"))
    checks["a view's current_schema() and current_database() are its reader's (public, then crm), in turns too; a materialized view's are as it was made (crm); SHOW CREATE VIEW keeps current_schema()"] = \
        info["cs, no path"] == [{"s": "public", "d": db_name}] and info["cs, USE crm"] == [{"s": "crm", "d": db_name}] \
        and info["cs, in turns"] == ["public", "crm"] * 2 and info["csm"] == [{"s": "crm"}] and info["cs kept"]
    # A view keeps the names it was made with, whatever path reads it.
    p = {"x-pondra-session": "use-path-read"}
    q("SET search_path TO public", p)
    q("CREATE VIEW pv AS SELECT count(*) AS n FROM t")  # (made in public, no session)
    info["view crm, no path"] = q("SELECT n FROM crm.v")
    info["view crm, public's path"] = q("SELECT n FROM crm.v", p)
    info["view public, under USE crm"] = q("SELECT n FROM public.pv", w)
    checks["a view keeps its names: crm's read with no path or public's path (3), public's read under USE crm (5)"] = \
        info["view crm, no path"] == [{"n": 3}] and info["view crm, public's path"] == [{"n": 3}] and info["view public, under USE crm"] == [{"n": 5}]
    # Names that are not a schema's: a CTE, a temporary table, the information schema (pg_class: the Postgres check).
    s = {"x-pondra-session": "use-skip-1"}
    q("USE crm", s)
    q("CREATE TEMP TABLE tmp AS SELECT 7 AS a", s)
    info["cte"] = q("WITH t AS (SELECT 42 AS a) SELECT a FROM t", s)
    info["temp"] = q("SELECT a FROM tmp", s)
    info["catalog"] = q("SELECT count(*) AS n FROM information_schema.tables", s)
    checks["under USE crm a CTE named t, a temporary table and information_schema.tables are the query's own, not crm's"] = \
        info["cte"] == [{"a": 42}] and info["temp"] == [{"a": 7}] and info["catalog"][0]["n"] > 0
    # SET search_path: crm first, then public, new objects in crm.
    q("CREATE TABLE only_pub (x INT)")
    q("INSERT INTO only_pub VALUES (7)")
    sp = {"x-pondra-session": "use-search-path"}
    q("SET search_path TO crm, public", sp)
    info["path count"] = q("SELECT count(*) AS n FROM t", sp)
    info["path public"] = q("SELECT x FROM only_pub", sp)
    q("CREATE TABLE made_here (x INT)", sp)
    info["made here"] = q("SELECT count(*) AS n FROM crm.made_here")
    info["not in public"] = _raises(lambda: q("SELECT count(*) AS n FROM public.made_here"))
    checks["SET search_path TO crm, public: crm's table first (3 rows), a table only in public found, a new table made in crm"] = \
        info["path count"] == [{"n": 3}] and info["path public"] == [{"x": 7}] and info["made here"] == [{"n": 0}] and info["not in public"]
    # A task made under USE crm is crm's, and writes into crm.
    k = {"x-pondra-session": "use-task-1"}
    q("CREATE TABLE crm.log (x INT)")
    q("USE crm", k)
    q("CREATE TASK tk SCHEDULE '1 second' AS INSERT INTO log VALUES (1)", k)
    info["task wrote"] = until(lambda: q("SELECT count(*) AS n FROM crm.log")[0]["n"] > 0, True, 20)
    info["tasks"] = [r["name"] for r in q("SELECT name FROM pondra.tasks")]
    checks["a task made under USE crm is crm.tk, and writes into crm.log within 20 s"] = info["task wrote"] is True and "crm.tk" in info["tasks"] and "tk" not in info["tasks"]
    # Another database: USE other, USE other.public, USE DATABASE other.
    q(f"CREATE DATABASE other LOCATION '{other}'")
    q("CREATE TABLE other.public.ot (x INT)")
    q("INSERT INTO other.public.ot VALUES (1), (2), (3)")
    o1 = {"x-pondra-session": "use-db-one"}
    q("USE other", o1)
    info["other first"] = q("SELECT count(*) AS n FROM ot", o1)
    q("INSERT INTO ot VALUES (4)", o1)
    info["other after"] = q("SELECT count(*) AS n FROM other.public.ot")
    info["not here"] = _raises(lambda: q("SELECT count(*) AS n FROM ot"))
    o2 = {"x-pondra-session": "use-db-two"}
    q("USE other.public", o2)
    info["other.public"] = q("SELECT count(*) AS n FROM ot", o2)
    q("INSERT INTO ot VALUES (5)", o2)
    o3 = {"x-pondra-session": "use-db-three"}
    q("USE DATABASE other", o3)
    info["DATABASE other"] = q("SELECT count(*) AS n FROM ot", o3)
    checks["USE other, USE other.public, USE DATABASE other: ot is other's (3, then 4 and 5 once written); this lake has no ot"] = \
        info["other first"] == [{"n": 3}] and info["other after"] == [{"n": 4}] and info["not here"] and info["other.public"] == [{"n": 4}] \
        and info["DATABASE other"] == [{"n": 5}] and q("SELECT count(*) AS n FROM other.public.ot") == [{"n": 5}]
    # Refused by name: a name that is both, unknown ones, no session, pondra sql.
    q("CREATE SCHEMA other")  # (now `other` is a database and a schema of this lake: USE other must say which)
    info["both"] = http("USE other", "use-both-1")
    info["nope"] = http("USE nope", "use-nope-1")
    info["nope db"] = http("USE nope.public", "use-nope-1")
    info["no session"] = http("USE crm")
    cli = subprocess.run([BIN, "sql", "--dir", lake, "USE crm"], capture_output=True, text=True, timeout=120)
    info["cli"] = [cli.returncode, (cli.stdout + cli.stderr)[-300:]]
    checks["refused by name: an unknown schema (3F000) or database (3D000), a name that is both (USE DATABASE or USE SCHEMA), no session, pondra sql"] = \
        info["nope"][1] == "3F000" and info["nope db"][1] == "3D000" and "USE DATABASE" in str(info["both"][2]) and "USE SCHEMA" in str(info["both"][2]) \
        and info["no session"][0] != 200 and "session" in str(info["no session"][2]) and cli.returncode != 0 and "session" in cli.stdout + cli.stderr
    # The Postgres port: one connection, its own session.
    q("CREATE TABLE crm.kt (id BIGINT PRIMARY KEY, v VARCHAR)")
    q("INSERT INTO crm.kt VALUES (1, 'crm')")
    q("CREATE TABLE kt (id BIGINT PRIMARY KEY, v VARCHAR)")
    q("INSERT INTO kt VALUES (2, 'public')")
    with psycopg.connect(f"host=127.0.0.1 port={A.port + 10} user=u dbname=lake", autocommit=True) as c:
        c.execute("USE crm")
        info["pg crm"] = c.execute("SELECT count(*) FROM t").fetchall()
        info["pg key"] = c.execute("SELECT v FROM kt WHERE id = 1").fetchall()  # (a key lookup: crm's row)
        info["pg key public"] = c.execute("SELECT v FROM kt WHERE id = 2").fetchall()  # (public's row: not on the path)
        c.execute("SET search_path TO public")
        info["pg public"] = c.execute("SELECT count(*) FROM t").fetchall()
        c.execute("SET search_path TO crm")
        info["pg schema"] = c.execute("SELECT current_schema()").fetchall()
        info["pg visible"] = c.execute("SELECT relname FROM pg_class c WHERE pg_table_is_visible(c.oid) AND relname IN ('t', 'only_pub')").fetchall()
        info["pg lookup"] = c.execute("SELECT a FROM t WHERE a = 1").fetchall()
        c.execute("CREATE VIEW cs_pg AS SELECT current_schema() AS s")  # (crm.cs_pg, its current_schema() kept)
        info["pg view"] = c.execute("SELECT s FROM cs_pg").fetchall()
    info["pg view, no path"] = q("SELECT s FROM crm.cs_pg")
    checks["a view made over Postgres keeps its current_schema(): crm for its connection, public for a reader with no path"] = \
        info["pg view"] == [("crm",)] and info["pg view, no path"] == [{"s": "public"}]
    checks["over Postgres: USE crm (3), a key lookup from crm, SET search_path to public (5), current_schema(), only crm's t visible in pg_class"] = \
        info["pg crm"] == [(3,)] and info["pg key"] == [("crm",)] and info["pg key public"] == [] and info["pg public"] == [(5,)] \
        and info["pg schema"] == [("crm",)] and info["pg visible"] == [("t",)] and info["pg lookup"] == [(1,)]
    # The Python client: USE is its connection's.
    con, others = _client(A.port), _client(A.port)
    con.sql("USE crm")
    info["python crm"] = con.sql("SELECT count(*) AS n FROM t").rows()
    info["python other"] = others.sql("SELECT count(*) AS n FROM t").rows()
    con.close()
    others.close()
    checks["the Python client: USE is its connection's (3 rows); another connection still reads public (5)"] = \
        info["python crm"] == [{"n": 3}] and info["python other"] == [{"n": 5}]
    node.kill()
    # The shell: one session until it quits.
    shell = subprocess.run([BIN, lake], input="USE crm;\nSELECT count(*) AS n FROM t;\n", capture_output=True, text=True, timeout=180)
    info["shell"] = shell.stdout[-400:]
    checks["the shell keeps its session from line to line: USE crm on one line, crm's count (3, not 5) on the next"] = "| 3 " in shell.stdout and "| 5 " not in shell.stdout
    # A spread query from a follower's session: the same answer as crm.t on one node.
    lake3 = new_lake()
    trio = [Node(lake3, A.port + i).start() for i in range(3)]
    time.sleep(1)
    sql(A.port, "CREATE SCHEMA crm")
    sql(A.port, "CREATE TABLE crm.t AS SELECT value AS id FROM generate_series(1, 30000)")
    f = {"x-pondra-session": "use-spread"}
    until(lambda: _try(lambda: call(A.port + 1, "POST", "/sql", b"USE crm", headers=f)) is not None, True, 15)
    spread = until(lambda: _try(lambda: call(A.port + 1, "POST", "/sql?spread=1", b"SELECT count(*) AS n FROM t", headers=f)), [{"n": 30000}], 15)
    one = sql(A.port, "SELECT count(*) AS n FROM crm.t")
    info["spread"], info["one node"] = spread, one
    checks["under USE crm on a follower, a query spread over three nodes == crm.t on one node (30000 rows)"] = spread == one == [{"n": 30000}]
    # A view saying current_schema(), read under the session's path: the other nodes would read it with
    # none, so it runs on the follower alone (every row crm's, not some public's).
    sql(A.port, "CREATE VIEW crm.cs3 AS SELECT id, current_schema() AS s FROM crm.t")
    info["spread view"] = until(lambda: _try(lambda: call(A.port + 1, "POST", "/sql?spread=1", b"SELECT s, count(*) AS n FROM crm.cs3 GROUP BY s", headers=f)), [{"s": "crm", "n": 30000}], 15)
    checks["under USE crm on a follower, a view's current_schema() asked to spread is crm's on every row (30000)"] = info["spread view"] == [{"s": "crm", "n": 30000}]
    [n.kill() for n in trio]
    ok = all(checks.values())
    print(json.dumps({"use": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"use: USE and search_path over HTTP, Postgres, Python and the shell, refused by name, spread on three nodes: all {len(checks)} checks pass"


def cursors():
    """Cursors on the Postgres port (cursors.rs) and cancelling a running statement (pg.rs), as Postgres
    has them: psycopg's named cursor and SQLAlchemy's stream_results read 25,000 rows a part, in order;
    DECLARE, MOVE, FETCH and CLOSE from psycopg with their tags, and Describe answers a FETCH with its
    cursor's columns; WITH HOLD outlives its transaction, a cursor without it ends with it; SCROLL,
    BINARY and backward moves are refused by name; psycopg's cancel() and psql's Ctrl-C answer 57014 at
    once and stop the work (the node's CPU goes quiet, not only the error comes back); a cancel with a
    key no connection holds does nothing; a cancelled statement fails its transaction."""
    import psycopg, socket, struct, threading
    import sqlalchemy as sa
    lake = new_lake()
    pg = A.port + 50  # (this section's Postgres port: inside the range its node port is in)
    node = Node(lake, A.port, pg=f"127.0.0.1:{pg}", env={"PONDRA_HISTORY_RATE": "1000"}).start()  # (every statement a row of pondra.history)
    url = f"host=127.0.0.1 port={pg} user=u dbname=lake"
    checks, info = {}, {}

    def portal_parts(query, max_rows):
        """The extended protocol by hand: a portal executed with max_rows answers that many rows and
        PortalSuspended, and the rest on the next Execute. Returns the messages' types and the rows' values."""
        s = socket.create_connection(("127.0.0.1", pg))
        def recv(n):
            buf = b""
            while len(buf) < n:
                chunk = s.recv(n - len(buf))
                if not chunk:
                    raise ConnectionError("the node closed the connection")
                buf += chunk
            return buf
        def read_one():
            head = recv(5)
            return head[:1].decode(), recv(struct.unpack("!I", head[1:])[0] - 4)
        def send(kind, body):
            s.sendall(kind + struct.pack("!I", len(body) + 4) + body)
        def until(stops):
            got = []
            while True:
                t, b = read_one()
                got.append((t, b))
                if t in stops:
                    return got
        body = struct.pack("!I", 196608) + b"user\0u\0database\0lake\0\0"  # (startup: protocol 3.0)
        s.sendall(struct.pack("!I", len(body) + 4) + body)
        until("Z")
        send(b"P", b"\0" + query.encode() + b"\0" + struct.pack("!H", 0))
        send(b"B", b"\0\0" + struct.pack("!HHH", 0, 0, 0))
        got = []
        for _ in range(3):  # (each Execute answers a part; Flush (H) keeps the portal between them)
            send(b"E", b"\0" + struct.pack("!I", max_rows))
            send(b"H", b"")
            got += until("sCE")
        send(b"S", b"")
        got += until("Z")
        s.close()
        values = []
        for t, b in got:
            if t == "D":
                n, pos, row = struct.unpack("!H", b[:2])[0], 2, []
                for _ in range(n):
                    size = struct.unpack("!i", b[pos:pos + 4])[0]
                    pos += 4
                    row.append(b[pos:pos + size].decode())
                    pos += max(size, 0)
                values.append(row[0])
        return [t for t, _ in got], values

    try:
        sql(A.port, "CREATE TABLE big (id BIGINT, v DOUBLE)")
        sql(A.port, "INSERT INTO big SELECT value, CAST(value AS DOUBLE) / 2 FROM range(1, 25001)")
        # 1.6 billion rows, filtered: it runs until cancelled. (Without the filter DataFusion answers count(*) from the
        # ranges' statistics at once, and nothing is left to cancel.)
        LONG = "SELECT count(*) AS n FROM range(1, 40000) a CROSS JOIN range(1, 40000) b WHERE a.value * b.value % 1000003 = 7"

        def cpu():
            """The node's CPU seconds so far, all its threads (/proc/<pid>/stat: utime and stime)."""
            fields = open(f"/proc/{node.p.pid}/stat").read().rsplit(")", 1)[1].split()
            return (int(fields[11]) + int(fields[12])) / os.sysconf("SC_CLK_TCK")

        def first_error(c, *stmts):
            """Runs `stmts` in one transaction, rolled back at the end: the SQLSTATE of the first that fails,
            or None. Each check starts from nothing, so a cursor one check declares is gone for the next."""
            try:
                for s in stmts:
                    c.execute(s)
            except psycopg.Error as e:
                return e.sqlstate
            finally:
                c.rollback()
            return None

        def timed(c, stmt, out):
            """Runs `stmt` on `c` (a thread's job) and says how it ended in `out`."""
            try:
                out["rows"] = c.execute(stmt).fetchone()[0]
            except psycopg.Error as e:
                out["sqlstate"], out["message"] = e.sqlstate, str(e)

        # A named cursor (psycopg's server-side cursor) and SQLAlchemy's stream_results read the answer a part at a time.
        with psycopg.connect(url) as c:
            with c.cursor(name="big_read") as cur:
                cur.itersize = 1000
                cur.execute("SELECT id FROM big ORDER BY id")
                ids = [row[0] for row in cur]
        checks["a named cursor (psycopg's) reads 25,000 rows, 1,000 a part, in order"] = ids == list(range(1, 25001))
        eng = sa.create_engine(f"postgresql+psycopg2://u@127.0.0.1:{pg}/lake")  # (psycopg2: SQLAlchemy 2.0.54's psycopg 3 dialect fails to connect with psycopg 3.3 on main too)
        with eng.connect() as conn:
            res = conn.execution_options(stream_results=True).execute(sa.text("SELECT id FROM big ORDER BY id"))
            parts = [len(p) for p in res.partitions(1000)]
        eng.dispose()
        checks["SQLAlchemy's stream_results reads it in 25 parts of 1,000"] = parts == [1000] * 25

        # By hand: the statements, their tags, and what Describe says a FETCH returns.
        with psycopg.connect(url) as c:
            cur = c.cursor()
            cur.execute("DECLARE m CURSOR FOR SELECT id FROM big ORDER BY id")
            declared = (cur.statusmessage, cur.description)
            cur.execute("MOVE 5 FROM m")
            moved = cur.statusmessage
            cur.execute("FETCH FORWARD 10 FROM m")
            ten, ten_tag = [r[0] for r in cur.fetchall()], cur.statusmessage
            cur.execute("FETCH NEXT FROM m")
            nxt = cur.fetchone()[0]
            cur.execute("FETCH 2 IN m")
            two = [r[0] for r in cur.fetchall()]
            cur.execute("FETCH ALL FROM m")
            rest = (len(cur.fetchall()), cur.statusmessage)
            cur.execute("FETCH NEXT FROM m")
            last = (cur.statusmessage, cur.fetchall())
            cur.execute("CLOSE m")
            closed = cur.statusmessage
            checks["DECLARE, MOVE, FETCH and CLOSE: their tags (DECLARE CURSOR, MOVE 5, FETCH 10, CLOSE CURSOR)"] = declared == ("DECLARE CURSOR", None) and moved == "MOVE 5" and ten_tag == "FETCH 10" and closed == "CLOSE CURSOR"
            checks["FORWARD n, NEXT, IN and ALL go on where the last left off, and FETCH 0 at the end"] = ten == list(range(6, 16)) and nxt == 16 and two == [17, 18] \
                and rest == (24982, "FETCH 24982") and last == ("FETCH 0", [])
            cur.execute("DECLARE d CURSOR FOR SELECT id, v FROM big ORDER BY id")
            cur.execute("MOVE 1 FROM d")
            no_columns = cur.description is None
            cur.execute("FETCH 1 FROM d")
            columns, first = [(x.name, x.type_code) for x in cur.description], cur.fetchall()
            checks["Describe: a FETCH gives its cursor's columns (int8, float8); DECLARE and MOVE give none"] = no_columns and columns == [("id", 20), ("v", 701)] and first == [(2, 1.0)]
            c.rollback()

        # SHOW under the extended protocol: Describe names its one column, as Postgres does (pgjdbc and
        # prepared psycopg statements fail on a row whose column has no description).
        with psycopg.connect(url, autocommit=True) as c:
            shown = c.execute("SHOW TRANSACTION ISOLATION LEVEL", prepare=True)
            named = (shown.description[0].name, len(shown.fetchall()))
            search = c.execute("SHOW search_path", prepare=True)
            search_named = search.description[0].name
        checks["SHOW under the extended protocol (prepared): its column is named as Postgres names it (transaction_isolation, search_path)"] = named == ("transaction_isolation", 1) and search_named == "search_path"

        # Errors, each as Postgres words them.
        with psycopg.connect(url) as c:
            errors = {
                "SCROLL": first_error(c, "DECLARE s SCROLL CURSOR FOR SELECT 1"),
                "BINARY": first_error(c, "DECLARE b BINARY CURSOR FOR SELECT 1"),
                "PRIOR": first_error(c, "DECLARE m CURSOR FOR SELECT 1", "FETCH PRIOR FROM m"),
                "BACKWARD ALL": first_error(c, "DECLARE m CURSOR FOR SELECT 1", "FETCH BACKWARD ALL FROM m"),
                "MOVE -1": first_error(c, "DECLARE m CURSOR FOR SELECT 1", "MOVE -1 FROM m"),
                "taken": first_error(c, "DECLARE m CURSOR FOR SELECT 1", "DECLARE m CURSOR FOR SELECT 2"),
                "unknown": first_error(c, "FETCH 1 FROM nope"),
                "after CLOSE": first_error(c, "DECLARE m CURSOR FOR SELECT 1", "CLOSE m", "FETCH 1 FROM m"),
                "CLOSE unknown": first_error(c, "CLOSE nope"),
                "not a query": first_error(c, "DECLARE m CURSOR FOR INSERT INTO big VALUES (0, 0)"),
                "the query's own": first_error(c, "DECLARE m CURSOR FOR SELECT nope FROM big"),
            }
        info["errors"] = errors
        want = {"SCROLL": "0A000", "BINARY": "0A000", "PRIOR": "55000", "BACKWARD ALL": "55000", "MOVE -1": "55000", "taken": "42P03", "unknown": "34000",
                "after CLOSE": "34000", "CLOSE unknown": "34000", "not a query": "42601", "the query's own": "42703"}
        checks["refused by name or by Postgres's code: SCROLL and BINARY 0A000, backward moves 55000, a taken name 42P03, an unknown one 34000, a query that isn't one 42601"] = errors == want

        # Outside a transaction a cursor without HOLD is 25P01; WITH HOLD lives on until CLOSE.
        with psycopg.connect(url, autocommit=True) as a:
            outside = first_error(a, "DECLARE m CURSOR FOR SELECT 1")
            a.execute("DECLARE hh CURSOR WITH HOLD FOR SELECT id FROM big ORDER BY id")
            alone = a.execute("FETCH 2 FROM hh").fetchall()
            a.execute("CLOSE hh")
        checks["DECLARE outside a transaction: 25P01, except WITH HOLD, which lives until CLOSE"] = outside == "25P01" and alone == [(1,), (2,)]

        # WITH HOLD outlives its COMMIT, a cursor without HOLD doesn't, and a cursor belongs to its connection.
        with psycopg.connect(url) as c:
            cur = c.cursor()
            cur.execute("DECLARE h CURSOR WITH HOLD FOR SELECT id FROM big ORDER BY id")
            cur.execute("DECLARE n CURSOR FOR SELECT id FROM big ORDER BY id")
            c.commit()
            ended = first_error(c, "FETCH 1 FROM n")
            cur.execute("FETCH 3 FROM h")
            three = [r[0] for r in cur.fetchall()]
            c.commit()
            cur.execute("FETCH 1 FROM h")
            fourth = cur.fetchone()[0]
            c.commit()
            with psycopg.connect(url, autocommit=True) as other:
                elsewhere = first_error(other, "FETCH 1 FROM h")
            checks["WITH HOLD: the cursor goes on after COMMIT; one without HOLD ended with its transaction (34000)"] = ended == "34000" and three == [1, 2, 3] and fourth == 4
            checks["a cursor belongs to its connection: another connection's FETCH is 34000"] = elsewhere == "34000"
            cur.execute("CLOSE h")
            c.commit()
            checks["CLOSE ends a WITH HOLD cursor"] = first_error(c, "FETCH 1 FROM h") == "34000"
            cur.execute("DECLARE r CURSOR FOR SELECT 1")
            c.rollback()
            checks["ROLLBACK ends a cursor without HOLD"] = first_error(c, "FETCH 1 FROM r") == "34000"

        # Cancelling: psycopg's cancel() (the extended protocol) and psql's Ctrl-C (the simple one).
        with psycopg.connect(url, autocommit=True) as ca:
            out = {}
            t = threading.Thread(target=timed, args=(ca, LONG, out))
            t.start()
            time.sleep(0.5)
            busy0 = cpu()
            time.sleep(0.5)
            busy = cpu() - busy0  # (the statement is at work)
            sent = time.time()
            ca.cancel()
            t.join(60)
            answered = time.time() - sent
            # The work stops at its operator's next batch, so the node is watched until a half second of it is quiet
            # (a fixed wait could catch the tail of a batch); the time it took and the trace go in the report.
            trace, rest_s = [], None
            for _ in range(20):
                c0 = cpu()
                time.sleep(0.5)
                trace.append(round(cpu() - c0, 2))
                if trace[-1] < 0.1:  # (under a fifth of a core)
                    rest_s = time.time() - sent
                    break
            info["cancel"] = {"answered_s": round(answered, 2), "rest_s": rest_s and round(rest_s, 2), "busy_cpu_s": round(busy, 2),
                              "trace_cpu_per_half_s": trace, "said": out.get("message", "")[:120]}
            checks["psycopg's cancel(): 57014 with Postgres's words, answered at once"] = out.get("sqlstate") == "57014" and answered < 3 and "canceling statement due to user request" in out.get("message", "")
            checks["…and its work stops: the node is busy while it runs, and at rest (under a fifth of a core) within 10 s of the request"] = busy > 0.3 and rest_s is not None and rest_s < 10
            checks["…and the connection carries on"] = first_error(ca, "SELECT 1") is None
        r = subprocess.run(["timeout", "-s", "INT", "1", "psql", "-h", "127.0.0.1", "-p", str(pg), "-U", "u", "-d", "lake", "-X", "-c", LONG],
                           capture_output=True, text=True, timeout=120)
        info["psql"] = r.stderr[-200:]
        checks["psql's Ctrl-C (SIGINT, the simple query protocol) cancels the statement: 57014 in Postgres's words"] = "canceling statement due to user request" in r.stderr

        # A comment before a statement (dbt puts one before every statement): the same answers as without it,
        # sent verbatim by psycopg (the extended protocol) and by psql (the simple one).
        def answers(stmts):
            got = []
            with psycopg.connect(url, autocommit=True) as conn:
                for s in stmts:
                    try:
                        cur = conn.execute(s)
                        got.append([cur.statusmessage, cur.fetchall() if cur.description else []])
                    except psycopg.Error as e:
                        got.append(["error", e.sqlstate])
            return got
        words = ["BEGIN", "DECLARE cc CURSOR FOR SELECT 1 AS one", "FETCH 1 FROM cc", "SHOW transaction_isolation", "COMMIT"]
        plain = answers(words)
        commented = answers(["/* c */ BEGIN", "/* c */ DECLARE cc CURSOR FOR SELECT 1 AS one", "-- c\nFETCH 1 FROM cc", "/* c */ SHOW transaction_isolation", "-- c\nCOMMIT"])
        info["comments"] = {"plain": plain, "commented": commented}
        checks["a comment before BEGIN, DECLARE, FETCH, SHOW and COMMIT answers as it does without it (psycopg, verbatim)"] = \
            commented == plain and plain[2][1] == [(1,)] and plain[3][1] == [("read committed",)]

        def psql_run(*stmts):
            args = ["psql", "-h", "127.0.0.1", "-p", str(pg), "-U", "u", "-d", "lake", "-X", "-A"]
            for s in stmts:
                args += ["-c", s]
            return subprocess.run(args, capture_output=True, text=True, timeout=60)
        commented_words = ["/* c */ " + words[0], "/* c */ " + words[1], "-- c\n" + words[2], "/* c */ " + words[3], "-- c\n" + words[4]]
        plain_psql = psql_run(*words)
        commented_psql = psql_run(*commented_words)
        info["comments_psql"] = {"plain": plain_psql.stdout[-300:], "commented": commented_psql.stdout[-300:], "stderr": commented_psql.stderr[-300:]}
        checks["a comment before those statements answers as it does without it, over psql"] = \
            plain_psql.returncode == 0 and commented_psql.returncode == 0 and not commented_psql.stderr.strip() and commented_psql.stdout == plain_psql.stdout

        # Whether a commented BEGIN really opens a transaction: its rows wait for COMMIT, and a ROLLBACK
        # behind a comment takes them back. (A BEGIN answered and not kept would autocommit each INSERT.)
        sql(A.port, "CREATE TABLE cmt (n INT)")
        with psycopg.connect(url, autocommit=True) as w, psycopg.connect(url, autocommit=True) as other:
            w.execute("/* c */ BEGIN")
            w.execute("INSERT INTO cmt VALUES (1)")
            inside = w.execute("SELECT count(*) FROM cmt").fetchone()[0]  # (its own write, in the transaction)
            seen_before = other.execute("SELECT count(*) FROM cmt").fetchone()[0]
            w.execute("-- c\nROLLBACK")
            after_rollback = other.execute("SELECT count(*) FROM cmt").fetchone()[0]
            w.execute("/* c */ BEGIN")
            w.execute("INSERT INTO cmt VALUES (2)")
            w.execute("-- c\nCOMMIT")
            committed = other.execute("SELECT count(*) FROM cmt").fetchone()[0]
        info["comment_transactions"] = {"inside": inside, "seen_before": seen_before, "after_rollback": after_rollback, "committed": committed}
        checks["a commented BEGIN opens a transaction: its write is seen inside it only, a commented ROLLBACK takes it back, a commented COMMIT keeps the next"] = \
            (inside, seen_before, after_rollback, committed) == (1, 0, 0, 1)

        # A cancel request with another connection's key, or a pid no connection has, does nothing.
        with psycopg.connect(url, autocommit=True) as cb:
            out = {}
            t = threading.Thread(target=timed, args=(cb, LONG, out))
            t.start()
            time.sleep(0.5)
            for who, key in ((cb.info.backend_pid, 4242), (999999, 4242)):
                with socket.create_connection(("127.0.0.1", pg)) as s:
                    s.sendall(struct.pack("!IIII", 16, 80877102, who, key))  # (a CancelRequest: its length, code, pid and key)
            time.sleep(1.0)
            still_running = t.is_alive()
            cb.cancel()
            t.join(60)
            checks["a cancel with a wrong key, or for a pid no connection has, stops nothing; the real key still does"] = still_running and out.get("sqlstate") == "57014"

        # A cancelled statement fails its transaction, as an error would: 25P02 until it ends.
        with psycopg.connect(url) as cx:
            out = {}
            t = threading.Thread(target=timed, args=(cx, LONG, out))
            t.start()
            time.sleep(0.5)
            cx.cancel()
            t.join(60)
            checks["a cancelled statement fails its transaction: the next statement is 25P02"] = out.get("sqlstate") == "57014" and first_error(cx, "SELECT 1") == "25P02"
        # A portal executed with max_rows = 2: PortalSuspended after each part, the rest on the next Execute.
        types, values = portal_parts("SELECT id FROM big ORDER BY id LIMIT 5", 2)
        checks["max_rows: a portal executed with max_rows = 2 gets PortalSuspended after each part, then the rest"] = types.count("s") == 2 and values == ["1", "2", "3", "4", "5"] and "C" in types
        info["max_rows_types"] = "".join(types)

        # Inside a transaction DECLARE reads the transaction's own writes, and nobody else's until COMMIT.
        sql(A.port, "CREATE TABLE own (id BIGINT)")
        sql(A.port, "INSERT INTO own VALUES (1)")
        with psycopg.connect(url) as c:
            cur = c.cursor()
            cur.execute("INSERT INTO own VALUES (2), (3)")
            cur.execute("DECLARE w CURSOR FOR SELECT count(*) AS n FROM own")
            own_writes = cur.execute("FETCH 1 FROM w").fetchone()[0]
            others = sql(A.port, "SELECT count(*) AS n FROM own")[0]["n"]
            c.rollback()
        checks["inside a transaction, DECLARE reads its own writes (3 rows); another connection sees the committed 1"] = own_writes == 3 and others == 1

        # The cursor memory budget (PONDRA_CURSORS_MB, 1 MB here, on a second node of the same lake): a DECLARE whose
        # answer would pass it is refused by name (53200), a small one works, a cursor already held is never evicted,
        # and CLOSE gives its memory back.
        node2 = Node(lake, A.port + 1, pg=f"127.0.0.1:{pg + 1}", env={"PONDRA_CURSORS_MB": "1"}).start()
        try:
            until(lambda: sql(A.port + 1, "SELECT count(*) AS n FROM big"), [{"n": 25000}], 20)
            url2 = f"host=127.0.0.1 port={pg + 1} user=u dbname=lake"

            def refusal(c, stmt):
                """The SQLSTATE and message of a statement that is refused, or (None, None) when it runs."""
                try:
                    c.execute(stmt)
                    return None, None
                except psycopg.Error as e:
                    return e.sqlstate, str(e)

            with psycopg.connect(url2, autocommit=True) as a, psycopg.connect(url2, autocommit=True) as b:
                big_code, big_msg = refusal(b, "DECLARE bigc CURSOR WITH HOLD FOR SELECT value AS id, CAST(value AS VARCHAR) AS s FROM range(1, 300001)")
                b.execute("DECLARE sm CURSOR WITH HOLD FOR SELECT 1 AS one")
                small = b.execute("FETCH 1 FROM sm").fetchone()
                b.execute("CLOSE sm")
                a.execute("DECLARE m1 CURSOR WITH HOLD FOR SELECT value FROM range(1, 80001)")
                second_code, second_msg = refusal(b, "DECLARE m2 CURSOR WITH HOLD FOR SELECT value FROM range(1, 80001)")
                kept = a.execute("FETCH 1 FROM m1").fetchone()  # (the cursor held is still there: nothing evicted)
                a.execute("CLOSE m1")
                after_close = refusal(b, "DECLARE m2 CURSOR WITH HOLD FOR SELECT value FROM range(1, 80001)")
            info["budget"] = {"big": big_msg, "second": second_msg, "after_close": after_close}
            checks["the cursor budget (PONDRA_CURSORS_MB): a DECLARE whose answer would pass it is refused by name, saying what is held and needed (53200); a small one works"] = \
                big_code == "53200" and all(x in (big_msg or "") for x in ("PONDRA_CURSORS_MB", "hold", "needs", "CLOSE", "WHERE")) and small == (1,)
            checks["…a cursor already held is never evicted (the next FETCH is its row), and CLOSE gives its memory back (the next DECLARE runs)"] = \
                second_code == "53200" and kept == (1,) and after_close == (None, None)
        finally:
            node2.kill()

        # DECLARE is one row of pondra.history, as every statement a door runs is.
        with psycopg.connect(url, autocommit=True) as a:
            a.execute("DECLARE hist_probe CURSOR WITH HOLD FOR SELECT 1 AS hist_probe_col")
            a.execute("CLOSE hist_probe")
        rows = []
        for _ in range(50):
            rows = [r for r in sql(A.port, "SELECT * FROM pondra.history WHERE statement LIKE '%hist_probe%'") if r["statement"].upper().startswith("DECLARE")]
            if rows:
                break
            time.sleep(0.2)
        checks["DECLARE goes through audit::statement: one row of pondra.history"] = len(rows) == 1

        # Grants: a user's DECLARE is checked against what it may read, as a query is (this makes the node
        # require a sign-in, so it comes last).
        sql(A.port, "CREATE USER ann PASSWORD 'ann-password-1'; GRANT SELECT ON own TO ann")  # (one request: the node is open until its first user)
        with psycopg.connect(f"host=127.0.0.1 port={pg} user=ann password=ann-password-1 dbname=lake") as c:
            allowed = first_error(c, "DECLARE g CURSOR FOR SELECT id FROM own", "FETCH 1 FROM g")
            refused = first_error(c, "DECLARE g CURSOR FOR SELECT id FROM big")
        checks["DECLARE is checked against the caller's grants: a table it may read works, one it may not is 42501"] = allowed is None and refused == "42501"
        info["grants"] = {"allowed": allowed, "refused": refused}
    finally:
        node.kill()
    ok = all(checks.values())
    print(json.dumps({"cursors": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)


def prepared():
    """Prepared statements on the Postgres port keep what they found (pg.rs, `Prepared`): their
    parameters' types and their columns, worked out once, as Postgres settles them when a statement is
    prepared. psycopg's prepared statements (libpq binds, describes and executes one each time it runs)
    answer as the statements sent whole, in text and binary, NULLs and key lookups among them; a query
    whose table gains a column is refused once with Postgres's 0A000, then answered with it (and a key
    looked up whose row predates the column has it NULL, at every door); a FETCH is
    described by its cursor each time; and a prepared query with a parameter takes about what the
    statement sent whole takes (planned once a run, not three times)."""
    import psycopg, statistics
    lake = new_lake()
    pg = A.port + 50
    node = Node(lake, A.port, pg=f"127.0.0.1:{pg}").start()
    url = f"host=127.0.0.1 port={pg} user=u dbname=lake"
    checks, info = {}, {}
    try:
        sql(A.port, "CREATE TABLE t (id BIGINT, v TEXT)")
        sql(A.port, "INSERT INTO t SELECT value, chr(97 + CAST(value % 5 AS INT)) FROM range(1, 1001)")
        sql(A.port, "CREATE TABLE k (id BIGINT PRIMARY KEY, name TEXT, score DOUBLE)")
        sql(A.port, "INSERT INTO k VALUES (1, 'ann', 1.5), (2, 'bo', 2.5), (3, NULL, NULL)")
        queries = [
            ("SELECT id, v FROM t WHERE id = %s", [(3,), (500,), (2000,)]),
            ("SELECT count(*) AS n FROM t WHERE v = %s", [("b",), ("e",), ("z",)]),
            ("SELECT id FROM t WHERE id > %s ORDER BY id LIMIT 3", [(None,), (997,), (10,)]),
            ("SELECT * FROM k WHERE id = %s", [(2,), (3,), (9,)]),
            ("SELECT id, v FROM t WHERE id < 0", [None, None, None]),
            ("SELECT %s::int + 1 AS x, %s::text AS s", [(41, "a"), (None, None), (-1, "é")]),
        ]

        def answer(cur, q, args):
            cur.execute(q, args, **({} if isinstance(cur, psycopg.ClientCursor) else {"prepare": True}))
            return [(d.name, d.type_code) for d in cur.description], cur.fetchall()

        with psycopg.connect(url, autocommit=True) as c:
            for binary in (False, True):
                whole, kept = {}, {}
                for q, runs in queries:
                    for i, args in enumerate(runs * 2):  # (each value twice: the second runs from what was kept)
                        whole[(q, i)] = answer(psycopg.ClientCursor(c), q, args)
                        kept[(q, i)] = answer(c.cursor(binary=binary), q, args)
                differ = [k for k in whole if whole[k] != kept[k]]
                info[f"differ ({'binary' if binary else 'text'})"] = differ[:3]
                checks[f"prepared statements answer as the statements sent whole, {'in binary' if binary else 'in text'}: columns and rows, NULLs, a key lookup, no rows"] = not differ

            for i in range(20):
                c.execute("INSERT INTO t VALUES (%s, %s)", (5000 + i, "p"), prepare=True)
            inserted = c.execute("SELECT count(*), min(id), max(id) FROM t WHERE v = 'p'").fetchone()
            checks["a prepared INSERT writes each run's values"] = inserted == (20, 5000, 5019)

            # A table altered under a prepared query: Postgres refuses the next run (0A000), and so does the node,
            # once; then the statement is described afresh.
            q = "SELECT * FROM k WHERE id = %s"
            before = [c.execute(q, (1,), prepare=True).fetchall() for _ in range(3)]
            sql(A.port, "ALTER TABLE k ADD COLUMN level BIGINT")
            try:
                c.execute(q, (1,), prepare=True)
                refused = None
            except psycopg.Error as e:
                refused = e.sqlstate
            after = c.execute(q, (1,), prepare=True)
            after = ([d.name for d in after.description], after.fetchall())
            info["altered"] = {"before": before, "refused": refused, "after": after}
            checks["a prepared query whose table gains a column: refused once (0A000, as Postgres), then answered with it"] = \
                before == [[(1, "ann", 1.5)]] * 3 and refused == "0A000" and after == (["id", "name", "score", "level"], [(1, "ann", 1.5, None)])

            # A key's row written before the column was added (in the log) lacks it: every lookup fills it with NULL.
            with c.transaction():
                in_txn = c.execute("SELECT * FROM k WHERE id = 1").fetchall()
            looked = {
                "HTTP": sql(A.port, "SELECT * FROM k WHERE id = 1"),
                "GET /lookup": call(A.port, "GET", "/lookup/k/1"),
                "Postgres": c.execute("SELECT * FROM k WHERE id = 1").fetchall(),
                "Postgres, in a transaction": in_txn,
            }
            info["looked up after ADD COLUMN"] = looked
            checks["a key looked up after ADD COLUMN, its row from before it: the new column NULL (HTTP, GET /lookup, Postgres, in a transaction)"] = \
                looked == {"HTTP": [{"id": 1, "name": "ann", "score": 1.5}], "GET /lookup": [{"id": 1, "name": "ann", "score": 1.5}],
                           "Postgres": [(1, "ann", 1.5, None)], "Postgres, in a transaction": [(1, "ann", 1.5, None)]}

        with psycopg.connect(url) as c:
            q = "SELECT * FROM k WHERE id = %s"
            c.execute(q, (2,), prepare=True)
            c.execute(q, (2,), prepare=True)
            c.commit()
            sql(A.port, "ALTER TABLE k ADD COLUMN extra TEXT")
            states = []
            for stmt in (q, "SELECT 1"):
                try:
                    c.execute(stmt, (2,) if stmt == q else None, prepare=True)
                    states.append(None)
                except psycopg.Error as e:
                    states.append(e.sqlstate)
            c.rollback()
            checks["…and in a transaction the refusal fails it (25P02 after), as any error does"] = states == ["0A000", "25P02"]

            # A FETCH's columns are its cursor's, which a DECLARE may change: described each time, never kept.
            fetched = []
            for cols in ("id", "id, v"):
                c.execute(f"DECLARE m CURSOR FOR SELECT {cols} FROM t ORDER BY id")
                cur = c.execute("FETCH 1 FROM m", prepare=True)
                fetched.append(([d.name for d in cur.description], cur.fetchall()))
                c.execute("CLOSE m")
            c.rollback()
            checks["a prepared FETCH is described by its cursor each time (another DECLARE, other columns)"] = fetched == [(["id"], [(1,)]), (["id", "v"], [(1, "b")])]

        # What it costs: a prepared query with a parameter against the statement sent whole, taking turns.
        with psycopg.connect(url, autocommit=True) as c:
            whole, kept, q = [], [], "SELECT count(*) FROM t WHERE id = %s"
            cur = psycopg.ClientCursor(c)
            for i in range(300):
                t0 = time.perf_counter(); cur.execute(q, (i,)); cur.fetchall(); whole.append(time.perf_counter() - t0)
                t0 = time.perf_counter(); c.execute(q, (i,), prepare=True).fetchall(); kept.append(time.perf_counter() - t0)
            ms = lambda ts: round(statistics.median(ts[20:]) * 1000, 3)
            info["ms (whole, prepared)"] = (ms(whole), ms(kept))
            checks["a prepared query with a parameter takes about what it takes sent whole (median within 25%): planned once a run"] = ms(kept) <= ms(whole) * 1.25
    finally:
        node.kill()
    ok = all(checks.values())
    print(json.dumps({"prepared": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)


def returning():
    """RETURNING on INSERT, UPDATE and DELETE, as Postgres answers it: the rows each statement wrote, with the
    items asked for, through every door that takes SQL (the Postgres port with psycopg's plain, prepared and
    binary cursors, Django's form, SQLAlchemy's many-rows INSERT and its ORM; HTTP, MCP and Flight SQL). On a
    keyed table, an append table with an identity column and a UNIQUE table (ON CONFLICT), in transactions that
    roll back or commit, through a job (sent again: refused, applied once) and from a follower. Refusals are
    Postgres's: a column that isn't there (42703), a temporary table (0A000), a user without SELECT on the table (42501);
    and a job sent twice is refused by name (55000) rather than answered with no rows, its key's 23505 too."""
    import psycopg
    import adbc_driver_flightsql.dbapi as adbc
    import urllib.request
    from sqlalchemy import BigInteger, Identity, String, create_engine
    from sqlalchemy.orm import DeclarativeBase, Mapped, Session, mapped_column

    lake = new_lake()
    pg, fl = A.port + 50, A.port + 60
    url = f"host=127.0.0.1 port={pg} user=u dbname=lake"
    checks, info = {}, {}
    leader = follower = c = t = None

    def check(name, fn):
        """A check's value is its bool. An exception fails it and is kept in info; the rest still run."""
        try:
            checks[name] = bool(fn())
        except Exception as e:
            checks[name] = False
            info[f"error: {name}"] = f"{type(e).__name__}: {str(e)[:600]}"

    def sqlstate_of(fn):
        """The SQLSTATE a statement fails with, or None when it goes through."""
        try:
            fn()
        except psycopg.Error as e:
            return e.sqlstate
        return None

    def err(text, path="/sql"):
        """(status, x-pondra-sqlstate, the body's start) of a POST; (200, None, '') when it went through."""
        conn = http.client.HTTPConnection("127.0.0.1", A.port, timeout=30)
        conn.request("POST", path, text.encode(), {})
        r = conn.getresponse()
        data = r.read().decode()
        conn.close()
        return (r.status, r.getheader("x-pondra-sqlstate"), data[:500]) if r.status != 200 else (200, None, "")

    def one_id(name):
        """The id of the one row named so in table a (None unless there is exactly one)."""
        rows = c.execute("SELECT id FROM a WHERE name = %s", (name,)).fetchall()
        return rows[0][0] if len(rows) == 1 else None

    def count(name):
        return c.execute("SELECT count(*) FROM a WHERE name = %s", (name,)).fetchone()[0]

    def mcp_write(text):
        body = json.dumps({"jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {"name": "write", "arguments": {"sql": text}}}).encode()
        req = urllib.request.Request(f"http://127.0.0.1:{A.port}/mcp", data=body, headers={"content-type": "application/json"})
        res = json.loads(urllib.request.urlopen(req, timeout=30).read())["result"]
        return res["isError"], res["content"][0]["text"]

    try:
        leader = Node(lake, A.port, pg=f"127.0.0.1:{A.port + 50}", flight=f"127.0.0.1:{A.port + 60}").start()
        follower = Node(lake, A.port + 1, pg=f"127.0.0.1:{A.port + 51}").start()
        deadline = time.time() + 60
        while len(call(A.port, "GET", "/stats")["nodes"]) < 2:
            if time.time() > deadline:
                raise RuntimeError("the follower never joined the leader")
            time.sleep(0.1)

        sql(A.port, "CREATE TABLE a (id BIGINT GENERATED BY DEFAULT AS IDENTITY, name TEXT, n INT DEFAULT 7)")
        sql(A.port, "CREATE TABLE k (id BIGINT PRIMARY KEY, name TEXT)")
        sql(A.port, "CREATE TABLE u (id BIGINT, email TEXT UNIQUE, hits INT)")
        sql(A.port, "CREATE TABLE j (name TEXT, n INT)")
        sql(A.port, "INSERT INTO j VALUES ('x', 1)")
        sql(A.port, "CREATE TABLE orm_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT)")
        c = psycopg.connect(url, autocommit=True)

        # Postgres's own statement shapes on the Postgres port (psycopg, autocommit).
        def plain_insert():
            cur = c.execute("INSERT INTO a (name) VALUES ('x'), ('y') RETURNING id, name, n")
            rows = cur.fetchall()
            table = c.execute("SELECT id, name FROM a WHERE name IN ('x', 'y')").fetchall()
            info["INSERT of x and y, RETURNING"] = {"rows": rows, "status": cur.statusmessage, "rowcount": cur.rowcount}
            return (len({r[0] for r in rows}) == 2 and [r[2] for r in rows] == [7, 7]
                    and cur.statusmessage == "INSERT 0 2" and cur.rowcount == 2
                    and sorted((r[0], r[1]) for r in rows) == sorted(table))
        check("Postgres: INSERT of two rows answers both, with distinct ids, n 7, INSERT 0 2, rowcount 2, and the table's own rows", plain_insert)

        def prepared_insert():
            ids = [c.execute("INSERT INTO a (name) VALUES (%s) RETURNING id", (f"p{i}",), prepare=True).fetchone()[0] for i in range(6)]
            table = dict(c.execute("SELECT name, id FROM a WHERE name IN ('p0', 'p1', 'p2', 'p3', 'p4', 'p5')").fetchall())
            info["prepared INSERTs' ids"] = ids
            return len(set(ids)) == 6 and ids == [table[f"p{i}"] for i in range(6)]
        check("a prepared INSERT ... RETURNING id, six runs: six distinct ids, each the table's row for its name", prepared_insert)

        def binary_insert():
            with c.cursor(binary=True) as cur:
                cur.execute("INSERT INTO a (name) VALUES (%s) RETURNING id", ("pb",), prepare=True)
                got = cur.fetchone()[0]
            info["binary cursor's id"] = got
            return isinstance(got, int) and got == one_id("pb")
        check("the same prepared INSERT on a binary cursor gives an int id, the table's row for its name", binary_insert)

        def http_return_star():
            rows = sql(A.port, "INSERT INTO a (name) VALUES ('h') RETURNING *")
            info["HTTP INSERT ... RETURNING *"] = rows
            return (isinstance(rows, list) and len(rows) == 1 and rows[0].get("name") == "h"
                    and rows[0].get("n") == 7 and rows[0].get("id") == one_id("h"))
        check("HTTP: INSERT ... RETURNING * gives one row: its id, name h, n 7", http_return_star)

        # Item forms, each on a new row (the alias on UPDATE: Pondra's INSERT takes no alias yet).
        def item_column():
            rows = c.execute("INSERT INTO a (name) VALUES ('i1') RETURNING a.id").fetchall()
            return rows == [(one_id("i1"),)] and rows[0][0] is not None
        check("RETURNING a.id gives the new row's id", item_column)

        def item_quoted_alias():
            cur = c.execute("INSERT INTO a (name) VALUES ('i2') RETURNING \"a\".\"id\" AS x")
            names = [d.name for d in cur.description]
            rows = cur.fetchall()
            return names == ["x"] and rows == [(one_id("i2"),)]
        check("RETURNING \"a\".\"id\" AS x names the column x and gives the row's id", item_quoted_alias)

        def item_star():
            cur = c.execute("INSERT INTO a (name) VALUES ('i3') RETURNING a.*")
            names = [d.name for d in cur.description]
            rows = cur.fetchall()
            table = c.execute("SELECT id, name, n FROM a WHERE name = 'i3'").fetchall()
            return names == ["id", "name", "n"] and rows == table and rows[0][2] == 7
        check("RETURNING a.* gives the columns id, name, n, and the row as the table holds it", item_star)

        def item_expressions():
            cur = c.execute("INSERT INTO a (name) VALUES ('i4') RETURNING upper(name) AS u, id + 1 AS next")
            names = [d.name for d in cur.description]
            rows = cur.fetchall()
            return names == ["u", "next"] and rows == [("I4", one_id("i4") + 1)]
        check("RETURNING upper(name) AS u, id + 1 AS next: expressions over the new row", item_expressions)

        def item_update_alias():
            rows = c.execute("UPDATE a AS t SET n = n + 0 WHERE t.name = 'x' RETURNING t.id, t.name").fetchall()
            cur = c.execute("UPDATE a AS t SET n = n + 0 WHERE t.name = 'x' RETURNING t.*")
            star = ([d.name for d in cur.description], cur.fetchall())
            info["UPDATE a AS t … RETURNING t.*"] = star
            return rows == [(one_id("x"), "x")] and star == (["id", "name", "n"], [(one_id("x"), "x", 7)])
        check("UPDATE a AS t ... RETURNING t.id, t.name and t.* (an alias on UPDATE) give the 'x' row", item_update_alias)

        # SQLAlchemy's many-rows INSERT, as text: ids must come back in the VALUES' order.
        many = ("INSERT INTO a (name) SELECT p0::VARCHAR FROM (VALUES ('s1', 0), ('s2', 1), ('s3', 2)) AS imp_sen(p0, sen_counter) "
                "ORDER BY sen_counter RETURNING a.id, a.id AS id__1")

        def many_rows():
            rows = psycopg.ClientCursor(c).execute(many).fetchall()
            table = dict(c.execute("SELECT id, name FROM a WHERE name IN ('s1', 's2', 's3')").fetchall())
            info["many-rows INSERT: (id, id__1) in the order returned, with the table's name"] = [(r[0], r[1], table.get(r[0])) for r in rows]
            return (len(rows) == 3 and all(r[0] == r[1] for r in rows)
                    and sorted(r[0] for r in rows) == sorted(table) and sorted(table.values()) == ["s1", "s2", "s3"])
        check("SQLAlchemy's many-rows INSERT ... SELECT ... RETURNING a.id, a.id AS id__1: three rows, both columns equal, the ids of s1, s2, s3", many_rows)

        def many_rows_order():
            names = [n for (n,) in c.execute("SELECT name FROM a WHERE name IN ('s1', 's2', 's3') ORDER BY id").fetchall()]
            info["names sorted by id"] = names
            return names == ["s1", "s2", "s3"]
        check("the many-rows INSERT hands ids out in the VALUES' order: the names sorted by id are s1, s2, s3", many_rows_order)

        # A keyed table (PRIMARY KEY): duplicates refused, the row kept.
        def keyed_insert():
            rows = c.execute("INSERT INTO k VALUES (1, 'a'), (2, 'b') RETURNING id, name").fetchall()
            return sorted(rows) == [(1, "a"), (2, "b")]
        check("keyed table: INSERT of two rows RETURNING id, name gives both rows", keyed_insert)

        def keyed_duplicate():
            e = sqlstate_of(lambda: c.execute("INSERT INTO k VALUES (1, 'again') RETURNING id"))
            info["keyed duplicate: sqlstate"] = e
            return e == "23505"
        check("keyed table: a duplicate key with RETURNING is refused with 23505", keyed_duplicate)

        check("keyed table: after the refused duplicate, id 1 still says a",
              lambda: c.execute("SELECT name FROM k WHERE id = 1").fetchall() == [("a",)])

        # UPDATE and DELETE with RETURNING, with their command tags.
        def keyed_update():
            cur = c.execute("UPDATE k SET name = 'B' WHERE id = 2 RETURNING id, name")
            rows = cur.fetchall()
            info["UPDATE k, RETURNING"] = {"rows": rows, "status": cur.statusmessage}
            return rows == [(2, "B")] and cur.statusmessage == "UPDATE 1"
        check("UPDATE of a keyed row RETURNING id, name gives the new row, tag UPDATE 1", keyed_update)

        def append_update():
            cur = c.execute("UPDATE a SET n = n + 1 WHERE name = 'x' RETURNING name, n")
            rows = cur.fetchall()
            info["UPDATE a, RETURNING"] = {"rows": rows, "status": cur.statusmessage}
            return rows == [("x", 8)] and cur.statusmessage == "UPDATE 1"
        check("UPDATE of an append row RETURNING name, n gives x at n 8, tag UPDATE 1", append_update)

        def update_nothing():
            cur = c.execute("UPDATE a SET n = n + 1 WHERE name = 'nobody' RETURNING name, n")
            rows = cur.fetchall()
            return rows == [] and cur.statusmessage == "UPDATE 0"
        check("an UPDATE matching no row RETURNING gives no rows, tag UPDATE 0", update_nothing)

        def append_delete():
            cur = c.execute("DELETE FROM a WHERE name = 'y' RETURNING name, n")
            rows = cur.fetchall()
            info["DELETE a, RETURNING"] = {"rows": rows, "status": cur.statusmessage}
            return rows == [("y", 7)] and cur.statusmessage == "DELETE 1" and count("y") == 0
        check("DELETE of an append row RETURNING name, n gives y at n 7, tag DELETE 1, and the row is gone", append_delete)

        def keyed_delete():
            cur = c.execute("DELETE FROM k WHERE id = 1 RETURNING *")
            rows = cur.fetchall()
            info["DELETE k, RETURNING *"] = {"rows": rows, "status": cur.statusmessage}
            return rows == [(1, "a")] and cur.statusmessage == "DELETE 1"
        check("DELETE of a keyed row RETURNING * gives the row, tag DELETE 1", keyed_delete)

        # UNIQUE constraints and ON CONFLICT.
        check("UNIQUE: the first INSERT ... RETURNING id gives its id",
              lambda: c.execute("INSERT INTO u VALUES (1, 'a@x', 0) RETURNING id").fetchall() == [(1,)])

        def unique_violation():
            e = sqlstate_of(lambda: c.execute("INSERT INTO u VALUES (2, 'a@x', 0) RETURNING id"))
            info["second 'a@x': sqlstate"] = e
            return e == "23505" and c.execute("SELECT count(*) FROM u").fetchone()[0] == 1
        check("UNIQUE: a second row with the same email is refused with 23505, and the table holds one row", unique_violation)

        def on_conflict_update():
            rows = c.execute("INSERT INTO u VALUES (3, 'a@x', 0) ON CONFLICT (email) DO UPDATE SET hits = u.hits + 1 RETURNING email, hits").fetchall()
            return rows == [("a@x", 1)]
        check("ON CONFLICT (email) DO UPDATE ... RETURNING email, hits gives the updated row (hits 1)", on_conflict_update)

        def on_conflict_nothing():
            cur = c.execute("INSERT INTO u VALUES (4, 'a@x', 0) ON CONFLICT (email) DO NOTHING RETURNING id")
            rows = cur.fetchall()
            info["DO NOTHING: tag"] = cur.statusmessage
            return rows == []
        check("ON CONFLICT (email) DO NOTHING RETURNING id gives no rows", on_conflict_nothing)

        check("keyed ON CONFLICT (id) DO UPDATE ... RETURNING id, name gives the updated row (2, bb)",
              lambda: c.execute("INSERT INTO k VALUES (2, 'bb') ON CONFLICT (id) DO UPDATE SET name = excluded.name RETURNING id, name").fetchall() == [(2, "bb")])

        # Transactions (psycopg without autocommit).
        t = psycopg.connect(url)  # not autocommit: a transaction starts at its first statement
        try:
            def rolled_back():
                got = t.execute("INSERT INTO a (name) VALUES ('t1') RETURNING id").fetchall()
                t.rollback()
                info["t1: returned, then rolled back"] = got
                return count("t1") == 0
            check("a transaction that rolls back: its INSERT ... RETURNING leaves no row", rolled_back)

            def committed():
                got = t.execute("INSERT INTO a (name) VALUES ('t1') RETURNING id").fetchall()
                t.commit()
                rows = c.execute("SELECT id FROM a WHERE name = 't1'").fetchall()
                info["t1: returned, then committed; the table"] = {"returned": got, "table": rows}
                return len(rows) == 1 and got == rows
            check("a transaction that commits: exactly one t1 row, and it is the id RETURNING gave", committed)

            def update_committed():
                got = t.execute("UPDATE k SET name = 'tx' WHERE id = 2 RETURNING name").fetchall()
                t.commit()
                table = c.execute("SELECT name FROM k WHERE id = 2").fetchall()
                info["UPDATE in a transaction: returned; k id 2 after the commit"] = {"returned": got, "table": table}
                return got == [("tx",)] and table == [("tx",)]
            check("an UPDATE ... RETURNING in a transaction gives 'tx', and the commit makes it the table's", update_committed)
        finally:
            t.close()

        # Refusals, by Postgres's code.
        def unknown_column():
            e = sqlstate_of(lambda: c.execute("INSERT INTO a (name) VALUES ('bad') RETURNING nope"))
            info["RETURNING nope: sqlstate"] = e
            return e == "42703"
        check("RETURNING an item that isn't a column is refused with 42703", unknown_column)
        check("...and no 'bad' row is left behind", lambda: count("bad") == 0)

        def temp_table():
            try:
                c.execute("CREATE TEMP TABLE tt (id INT)")
                info["CREATE TEMP TABLE"] = "ok"
            except psycopg.Error as e:
                info["CREATE TEMP TABLE"] = f"{e.sqlstate}: {str(e)[:300]}"
            e = sqlstate_of(lambda: c.execute("INSERT INTO tt VALUES (1) RETURNING id"))
            info["INSERT into the temp table: sqlstate"] = e
            return e == "0A000"
        check("a temporary table: INSERT ... RETURNING is refused with 0A000", temp_table)

        def from_temp():
            # (an append table's UPDATE runs as a transaction of its own, in the caller's session: its temporary tables are read)
            c.execute("CREATE TEMP TABLE src (name TEXT, v INT)")
            c.execute("INSERT INTO src VALUES ('p0', 70), ('p1', 71)")
            got = sorted(c.execute("UPDATE a SET n = src.v FROM src WHERE a.name = src.name RETURNING a.name, a.n").fetchall())
            info["UPDATE a … FROM a temporary table, RETURNING"] = got
            return got == [("p0", 70), ("p1", 71)] and sorted(c.execute("SELECT name, n FROM a WHERE name IN ('p0', 'p1')").fetchall()) == got
        check("UPDATE … FROM the session's temporary table … RETURNING: the rows it changed, as the table now has them", from_temp)

        # Other clients' forms.
        def django_form():
            cur = c.cursor()
            cur.execute('INSERT INTO "a" ("name") VALUES (%s) RETURNING "a"."id"', ("dj",))
            got = cur.fetchall()
            info["Django-form INSERT"] = got
            return got == [(one_id("dj"),)]
        check("Django's form: INSERT ... RETURNING \"a\".\"id\" on a plain cursor gives the table's row for dj", django_form)

        def orm():
            class Base(DeclarativeBase):
                pass

            class Item(Base):
                __tablename__ = "orm_items"
                id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
                name: Mapped[str] = mapped_column(String)

            engine = create_engine(f"postgresql+psycopg://u@127.0.0.1:{pg}/lake")
            try:
                with Session(engine) as s:
                    items = [Item(name=n) for n in ("o1", "o2", "o3")]
                    s.add_all(items)
                    s.flush()  # the ids come back from RETURNING here
                    flushed = [it.id for it in items]
                    s.commit()
                    after = [it.id for it in items]
            finally:
                engine.dispose()
            table = dict(c.execute("SELECT name, id FROM orm_items WHERE name IN ('o1', 'o2', 'o3')").fetchall())
            info["ORM ids after flush, after commit, and the table"] = {"flushed": flushed, "after": after, "table": table}
            return flushed == [table.get("o1"), table.get("o2"), table.get("o3")] and None not in flushed and after == flushed
        check("SQLAlchemy ORM: three Items get their ids from RETURNING at flush, the table's ids, and commit keeps them", orm)

        def mcp():
            is_error, text = mcp_write("INSERT INTO a (name) VALUES ('m') RETURNING id")
            info["MCP write's text"] = text
            return not is_error and str(one_id("m")) in text
        check("MCP: the write tool's INSERT ... RETURNING id answers without error, with the id the table holds", mcp)

        def flight():
            conn = adbc.connect(f"grpc://127.0.0.1:{fl}")
            try:
                cur = conn.cursor()
                try:
                    cur.execute("INSERT INTO a (name) VALUES ('f') RETURNING id, name")
                    got = [tuple(r) for r in cur.fetchall()]
                finally:
                    cur.close()
                conn.commit()  # ADBC's DBAPI connection is not autocommit (PEP 249): without this, close rolls the INSERT back
            finally:
                conn.close()
            info["Flight SQL INSERT ... RETURNING"] = got
            return got == [(one_id("f"), "f")]
        check("Flight SQL (ADBC): INSERT ... RETURNING id, name gives the row", flight)

        # A job sent twice: applied once, the second send refused.
        job_sql = "UPDATE j SET n = n + 100 WHERE name = 'x' RETURNING name, n"

        def job_first():
            first = call(A.port, "POST", "/sql?job=ret-j1", job_sql.encode())
            info["job ret-j1, first send"] = first
            return first == [{"name": "x", "n": 101}]
        check("a job's first send of UPDATE ... RETURNING name, n answers ('x', 101)", job_first)

        def job_again():
            again = err(job_sql, path="/sql?job=ret-j1")
            info["job ret-j1, the same job sent again"] = again
            return again[0] != 200 and again[1] == "55000"
        check("the same job sent again is refused: HTTP status not 200, x-pondra-sqlstate 55000", job_again)

        def job_once():
            n = [r["n"] for r in sql(A.port, "SELECT n FROM j")]
            info["j.n after both sends"] = n
            return n == [101]
        check("after both sends, j's n is 101 (the job applied once)", job_once)

        def job_keys():
            # (sent again, the row it wrote would refuse it, 23505: the job is asked first, as a keyed table's INSERT asks it)
            out = {}
            for table, text in (("u", "INSERT INTO u VALUES (5, 'job@x', 0) RETURNING id"), ("k", "INSERT INTO k VALUES (50, 'jk') RETURNING id")):
                first = call(A.port, "POST", f"/sql?job=ret-{table}1", text.encode())
                again = err(text, path=f"/sql?job=ret-{table}1")
                rows = sql(A.port, f"SELECT count(*) AS n FROM {table} WHERE id IN (5, 50)")
                out[table] = (first, again[:2], rows)
            info["a job's INSERT … RETURNING into a UNIQUE and a keyed table, sent twice"] = out
            once = lambda first, again, rows, id: first == [{"id": id}] and again[1] == "55000" and rows == [{"n": 1}]
            return once(*out["u"], 5) and once(*out["k"], 50)
        check("a job's INSERT … RETURNING into a UNIQUE table and a keyed one, sent again: refused 55000, not 23505; one row each", job_keys)

        # A follower: its writes answered as the leader holds them.
        def follower_insert():
            got = sql(A.port + 1, "INSERT INTO a (name) VALUES ('fw') RETURNING id")
            info["follower, HTTP: INSERT ... RETURNING id"] = got
            leader_id, deadline = None, time.time() + 5
            while leader_id is None and time.time() < deadline:
                rows = sql(A.port, "SELECT id FROM a WHERE name = 'fw'")
                leader_id = rows[0]["id"] if rows else None
                if leader_id is None:
                    time.sleep(0.1)
            info["the leader's row for fw"] = leader_id
            return isinstance(got, list) and len(got) == 1 and leader_id is not None and got[0].get("id") == leader_id
        check("follower, HTTP: INSERT ... RETURNING id gives the id the leader holds for fw", follower_insert)

        def follower_update():
            got = sql(A.port + 1, "UPDATE j SET n = n + 1 WHERE name = 'x' RETURNING n")
            info["follower, HTTP: UPDATE j ... RETURNING n"] = got
            return got == [{"n": 102}]
        check("follower, HTTP: UPDATE ... RETURNING n gives 102", follower_update)

        def follower_pg():
            f = psycopg.connect(f"host=127.0.0.1 port={A.port + 51} user=u dbname=lake", autocommit=True)
            try:
                got = f.execute("INSERT INTO u VALUES (9, 'f@x', 0) RETURNING id").fetchall()
            finally:
                f.close()
            info["follower's Postgres port: INSERT into u RETURNING id"] = got
            return got == [(9,)]
        check("follower's Postgres port: INSERT into u ... RETURNING id gives (9,)", follower_pg)

        # Last, since once there is a user everyone signs in: RETURNING reads the rows it wrote, so it needs SELECT, as Postgres asks.
        def grants():
            import base64
            basic = lambda u, p: {"Authorization": "Basic " + base64.b64encode(f"{u}:{p}".encode()).decode()}
            boss, ann = basic("boss", "boss-password-1"), basic("ann", "ann-password-1")

            def send(text, who):
                conn = http.client.HTTPConnection("127.0.0.1", A.port, timeout=30)
                conn.request("POST", "/sql", text.encode(), who)
                r = conn.getresponse()
                body = r.read()
                conn.close()
                return (r.status, r.getheader("x-pondra-sqlstate"), json.loads(body) if r.status == 200 and body[:1] == b"[" else body[:300])
            sql(A.port, "CREATE USER boss PASSWORD 'boss-password-1' SUPERUSER")
            for text in ("CREATE USER ann PASSWORD 'ann-password-1'", "GRANT INSERT ON a TO ann"):
                send(text, boss)
            seen = {"plain": send("INSERT INTO a (name) VALUES ('g1')", ann)[:2],
                    "returning": send("INSERT INTO a (name) VALUES ('g2') RETURNING id", ann)[:2],
                    "g2 written": send("SELECT count(*) AS n FROM a WHERE name = 'g2'", boss)[2]}
            send("GRANT SELECT ON a TO ann", boss)
            seen["granted SELECT"] = send("INSERT INTO a (name) VALUES ('g3') RETURNING id", ann)
            seen["g3's id"] = send("SELECT id FROM a WHERE name = 'g3'", boss)[2]
            info["a user granted INSERT, then SELECT"] = seen
            return (seen["plain"] == (200, None) and seen["returning"] == (403, "42501") and seen["g2 written"] == [{"n": 0}]
                    and seen["granted SELECT"][0] == 200 and seen["granted SELECT"][2] == seen["g3's id"])
        check("a user granted INSERT but not SELECT: RETURNING refused 42501 and nothing written; granted SELECT, answered", grants)
    finally:
        if c is not None:
            c.close()
        for n in (follower, leader):
            if n is not None:
                n.kill()
    ok = all(checks.values())
    print(json.dumps({"returning": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)


def doors():
    """The doors matrix (ADR-036 §7): one list of features, each through every door — SQL over HTTP
    (a session), the Python client, the Postgres port (psycopg), Flight SQL (ADBC), the JavaScript
    client, MCP, the command line (the shell, `pondra <lake>`, one process per feature) and the console
    (its run in headless Chromium, one tab per feature). Each cell is right, or refused by name where the
    door can't (a USE needs a session, which Flight SQL has none of; a transaction is a session's on
    Postgres, HTTP, MCP, and a transaction id's on Flight SQL). The table is printed; every cell must be
    one of the two. Needs playwright, and installs its Chromium when it isn't there."""
    import re, psycopg, adbc_driver_flightsql.dbapi as adbc
    from playwright.sync_api import sync_playwright
    sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "python"))
    import pondra
    lake = new_lake()
    pgp, fp = A.port + 2000, A.port + 30
    node = Node(lake, A.port, pg=f"127.0.0.1:{pgp}", flight=f"127.0.0.1:{fp}", tier_secs=0.5).start()
    q = lambda s: sql(A.port, s)
    q("CREATE TABLE d_items (id BIGINT PRIMARY KEY, qty BIGINT CHECK (qty >= 0))")
    q("CREATE TABLE d_log (door VARCHAR, n BIGINT)")
    q("INSERT INTO d_items SELECT value AS id, 100 AS qty FROM range(1, 101)")
    q("CREATE PROCEDURE d_bump(k BIGINT) LANGUAGE sql AS $$ UPDATE d_items SET qty = qty + 1000 WHERE id = $k $$")
    q("CREATE SCHEMA d_crm")  # (USE a schema: its one-part names are d_crm's)
    q("CREATE TABLE d_crm.d_only (x BIGINT)")
    q("INSERT INTO d_crm.d_only VALUES (1), (2), (3)")
    q("CREATE MACRO d_twice(x) AS x * 2")
    record = {"repository": "https://github.com/acme/sales", "branch": "main", "commit": "0" * 40, "files": {}}  # (a Git folder: its record, and a file not committed)
    for path, body in (("d_git/.pondra-git.json", json.dumps(record)), ("d_git/a.sql", "SELECT 1;\n")):
        c = http.client.HTTPConnection("127.0.0.1", A.port, timeout=60)
        c.request("PUT", f"/files/{path}", body.encode())
        assert c.getresponse().status == 200, path
    backups = tempfile.mkdtemp(prefix="pondra-doors-backups-")  # (a backup goes in a place of its own: ADR-070)
    atexit.register(shutil.rmtree, backups, True)
    q(f"BACKUP DATABASE TO '{backups}/read'")
    q(f"ATTACH '{backups}/read' AS d_bk")
    def backed(place):
        return any(f.endswith(".json.zst") for f in os.listdir(os.path.join(place, "_backups")))
    DOORS = ["http", "python", "postgres", "flight", "javascript", "mcp", "cli", "console"]
    shell_dir = tempfile.mkdtemp(prefix="pondra-doors-cwd-")  # (the shell attaches the lakes beside its folder: an empty one)
    def features(i):
        k = 10 * i + 1  # (each door its own keys)
        return {
            "query": ([f"SELECT count(*) AS n FROM d_items WHERE id <= 100"], lambda r: r[-1] == [[100]]),
            "insert": ([f"INSERT INTO d_log VALUES ('door{i}', {i})"], lambda r: q(f"SELECT n FROM d_log WHERE door = 'door{i}'") == [{"n": i}]),
            "INSERT … RETURNING": ([f"INSERT INTO d_log VALUES ('ret{i}', {100 + i}) RETURNING door, n"], lambda r: r[-1] == [[f"ret{i}", 100 + i]]),
            "key lookup": ([f"SELECT qty FROM d_items WHERE id = {k}"], lambda r: r[-1] == [[100]]),
            "one-key update": ([f"UPDATE d_items SET qty = qty + 5 WHERE id = {k + 1}"], lambda r: q(f"SELECT qty FROM d_items WHERE id = {k + 1}") == [{"qty": 105}]),
            "update by a filter": ([f"UPDATE d_items SET qty = qty + 1 WHERE id BETWEEN {k + 2} AND {k + 3}"], lambda r: q(f"SELECT sum(qty) AS s FROM d_items WHERE id BETWEEN {k + 2} AND {k + 3}") == [{"s": 202}]),
            "a CHECK refused, 23514": (["INSERT INTO d_items VALUES (999, -1)"], lambda r: r == "23514"),
            "no table, 42P01": (["SELECT * FROM d_nope"], lambda r: r == "42P01"),
            "an INSERT into no table, 42P01": (["INSERT INTO d_nope VALUES (1)"], lambda r: r == "42P01"),
            "procedure": ([f"CALL d_bump({k + 4})"], lambda r: q(f"SELECT qty FROM d_items WHERE id = {k + 4}") == [{"qty": 1100}]),
            "transaction": (["BEGIN", f"UPDATE d_items SET qty = qty - 7 WHERE id = {k + 5}", f"UPDATE d_items SET qty = qty + 7 WHERE id = {k + 6}", f"SELECT qty FROM d_items WHERE id = {k + 5}", "COMMIT"],
                            lambda r: r[3] == [[93]] and q(f"SELECT count(DISTINCT _version) AS v, sum(qty) AS s FROM d_items WHERE id IN ({k + 5}, {k + 6})") == [{"v": 1, "s": 200}]),
            "USE a schema": (["USE d_crm", "SELECT count(*) AS n FROM d_only"], lambda r: r[-1] == [[3]]),
            "a macro": (["SELECT d_twice(21) AS n"], lambda r: r[-1] == [[42]]),
            "a Git folder's status": (["SELECT path, change FROM pondra.git_status('d_git')"], lambda r: r[-1] == [["a.sql", "added"]]),
            "a backup": ([f"BACKUP DATABASE TO '{backups}/door{i}'"], lambda r: backed(f"{backups}/door{i}")),
            "a write to a backup refused, 25006": ([f"INSERT INTO d_bk.d_log VALUES ('door{i}', {i})"], lambda r: r == "25006"),
        }
    def rows_of(x):
        return [list(r.values()) if isinstance(r, dict) else list(r) for r in x] if isinstance(x, list) else x
    # Each door runs a feature's statements in one session: their answers, or the error's SQLSTATE.
    def via_http(stmts):
        sid, out = "d-" + uuid.uuid4().hex[:10], []
        for st in stmts:
            c = http.client.HTTPConnection("127.0.0.1", A.port, timeout=60)
            c.request("POST", "/sql", st.encode(), {"x-pondra-session": sid})
            r = c.getresponse(); body = r.read()
            if r.status != 200:
                return r.getheader("x-pondra-sqlstate")
            out.append(rows_of(json.loads(body)) if body[:1] == b"[" else None)
        return out
    def via_python(stmts):
        con, out = pondra.connect(f"http://127.0.0.1:{A.port}"), []
        try:
            for st in stmts:
                r = con.sql(st)
                out.append(rows_of(r.rows()) if hasattr(r, "rows") else None)
        except pondra.PondraError as e:
            return e.sqlstate
        finally:
            con.close()
        return out
    def via_postgres(stmts):
        out = []
        try:
            with psycopg.connect(f"host=127.0.0.1 port={pgp} user=u dbname=lake", autocommit=True) as c:
                for st in stmts:
                    cur = c.execute(st)
                    out.append([list(r) for r in cur.fetchall()] if cur.description else None)
        except psycopg.Error as e:
            return e.sqlstate
        return out
    def via_flight(stmts):
        out = []
        txn = stmts[0].strip().upper() == "BEGIN"  # (a transaction is Flight SQL's own: ADBC's autocommit off, then commit)
        try:
            with adbc.connect(f"grpc://127.0.0.1:{fp}", autocommit=not txn) as c:
                cur = c.cursor()
                for st in stmts:
                    if txn and st.strip().upper() in ("BEGIN", "COMMIT"):
                        if st.strip().upper() == "COMMIT":
                            c.commit()
                        out.append(None)
                        continue
                    cur.execute(st)
                    try:
                        out.append([list(r) for r in cur.fetchall()])
                    except Exception:
                        out.append(None)
        except Exception as e:
            meta = {(k.decode() if isinstance(k, bytes) else k): (v.decode() if isinstance(v, bytes) else v) for k, v in (getattr(e, "details", None) or [])}  # (ADBC: the status's metadata)
            return meta.get("x-pondra-sqlstate") or "refused: " + str(e).splitlines()[0][:160]
        return out
    def via_mcp(stmts):
        out, mcp = [], f"http://127.0.0.1:{A.port}/mcp"
        # One session, as an MCP client keeps one (Mcp-Session-Id from initialize): BEGIN … COMMIT is its transaction.
        init = json.dumps({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2025-06-18"}}).encode()
        sid = urllib.request.urlopen(urllib.request.Request(mcp, data=init, headers={"content-type": "application/json"}), timeout=60).headers["mcp-session-id"]
        try:
            for st in stmts:
                tool = "query" if st.split()[0].upper() in ("SELECT",) else "write"
                body = json.dumps({"jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {"name": tool, "arguments": {"sql": st}}}).encode()
                r = json.loads(urllib.request.urlopen(urllib.request.Request(mcp, data=body, headers={"content-type": "application/json", "mcp-session-id": sid}), timeout=60).read())["result"]
                text = r["content"][0]["text"]
                if r["isError"]:
                    m = re.search(r"\b(\d{2}[0-9A-Z]\d{2})\b", text)
                    return m.group(1) if m and m.group(1) in ("23514", "42P01", "40001", "25P02", "25006") else "refused: " + text[:160]
                got = json.loads(text)
                out.append(rows_of(got["rows"]) if isinstance(got, dict) and "rows" in got else None)
        finally:
            urllib.request.urlopen(urllib.request.Request(mcp, method="DELETE", headers={"mcp-session-id": sid}), timeout=60).read()  # (the session ends, its transaction with it)
        return out
    js_lib = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "js", "index.js")
    def via_javascript(stmts):
        script = f"""import {{ connect }} from {json.dumps(js_lib)};
const db = connect("http://127.0.0.1:{A.port}"); const out = [];
try {{ for (const s of {json.dumps(stmts)}) {{ const r = await db.sql(s); out.push(Array.isArray(r) ? r.map(x => Object.values(x)) : null); }} console.log(JSON.stringify(out)); }}
catch (e) {{ console.log(JSON.stringify(e.sqlstate || ("refused: " + e.message.slice(0, 160)))); }}
finally {{ await db.close?.(); }}"""
        path = os.path.join(tempfile.mkdtemp(prefix="pondra-doors-"), "d.mjs")
        open(path, "w").write(script)
        r = subprocess.run(["node", path], capture_output=True, text=True, timeout=60)
        return json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else "refused: " + r.stderr[-160:]
    def answers_of(text):
        """The shell's standard output as one answer per statement: None for a JSON line (what it did), a
        table's rows as lists. A table is three borders around its header and rows: the third ends it
        (an empty one too)."""
        out, table = [], None
        for line in text.splitlines():
            if line.startswith("+"):
                if table is None:
                    table = {"borders": 0, "rows": []}
                table["borders"] += 1
                if table["borders"] == 3:
                    out.append(table["rows"])
                    table = None
            elif table is not None and table["borders"] == 2 and line.startswith("|"):
                cells = [c.strip() for c in line.strip().strip("|").split("|")]
                table["rows"].append([int(c) if re.fullmatch(r"-?\d+", c) else c for c in cells])
            elif line.strip() and table is None:
                out.append(None)
        return out
    # The shell prints its errors without a SQLSTATE (the header `x-pondra-sqlstate` carries it), so the
    # codes this matrix checks are named by the words of their messages.
    shell_words = [("violates check constraint", "23514"), ("not found", "42P01"), ("no table", "42P01"), ("is a backup, so it is read-only", "25006")]
    def via_cli(stmts):
        # The shell on the lake, one process for the feature's statements: one session (`shell.rs`). It has no
        # `--url`, so it starts a node on the lake, which joins this one as a follower; its own address is an
        # ephemeral port it picks. Its answers are on standard output, its errors on standard error.
        p = subprocess.run([BIN, lake], input="".join(s.strip().rstrip(";") + ";\n" for s in stmts), capture_output=True, text=True, timeout=240, cwd=shell_dir)
        errors = [e[len("Error: "):] for e in p.stderr.splitlines() if e.startswith("Error: ")]
        if errors:
            return next((code for word, code in shell_words if word in errors[0]), None) or "refused: " + errors[0][:160]
        return answers_of(p.stdout) if p.returncode == 0 else "refused: " + p.stderr[-160:]
    # The console's own run (`pondra.api.run`: core.js's `run`, as its Run button calls it), in the session a
    # SQL file's first tab has. The page keeps only an error's text, so the page's fetch is wrapped (through
    # the console's public `pondra.configure`) to read the SQLSTATE the node sends in its header.
    console_run = """async stmts => {
        const sid = pondra.session + '-1', out = [];
        for (const s of stmts) {
            window.__sqlstate = null;
            try { const r = await pondra.api.run(s, undefined, undefined, undefined, sid); out.push(r.kind === 'rows' ? r.rows : null); }
            catch (e) { return { sqlstate: window.__sqlstate, message: e.message }; }
        }
        return { answers: out };
    }"""
    console_wrap = """() => pondra.configure({ fetch: async (url, init) => { const r = await fetch(url, init); window.__sqlstate = r.headers.get('x-pondra-sqlstate'); return r; } })"""
    def via_console(stmts):
        page = browser.new_page()  # (a tab of its own per feature; one browser for all of them)
        try:
            page.goto(f"http://127.0.0.1:{A.port}/")
            page.wait_for_function("() => window.pondra && window.pondra.api")
            page.evaluate(console_wrap)
            got = page.evaluate(console_run, stmts)
        finally:
            page.close()
        if "answers" in got:
            return got["answers"]
        return got["sqlstate"] or "refused: " + got["message"][:160]
    pw = sync_playwright().start()
    try:
        browser = pw.chromium.launch()
    except Exception as e:  # (CI's harness runners have no Chromium: only the console's job installs it)
        if "Executable doesn't exist" not in str(e):
            raise
        subprocess.run([sys.executable, "-m", "playwright", "install", "--with-deps", "chromium"], check=True, stdout=subprocess.DEVNULL)
        browser = pw.chromium.launch()
    via = {"http": via_http, "python": via_python, "postgres": via_postgres, "flight": via_flight, "javascript": via_javascript, "mcp": via_mcp, "cli": via_cli, "console": via_console}
    matrix, checks = {}, {}
    no_session = {"USE a schema": {"flight"}}  # (USE needs a session: Flight SQL has none, so it's refused by name there)
    for i, door in enumerate(DOORS):
        for name, (stmts, right) in features(i + 1).items():
            try:
                got = via[door](stmts)
            except Exception as e:
                got = "error: " + str(e)[:160]
            ok = False
            try:
                ok = bool(right(got))
            except Exception:
                pass
            refused = isinstance(got, str) and ("session" in got or got.startswith("refused") or got == "0A000")
            cell = "ok" if ok else ("refused" if refused and door in no_session.get(name, ()) else "WRONG")
            matrix.setdefault(name, {})[door] = cell if cell != "WRONG" else f"WRONG: {str(got)[:120]}"
    browser.close()
    pw.stop()
    shutil.rmtree(shell_dir, ignore_errors=True)
    for name, row in matrix.items():
        checks[f"{name}: " + ", ".join(f"{d} {'ok' if v == 'ok' else v}" for d, v in row.items())] = all(v in ("ok", "refused") for v in row.values())
    node.kill()
    ok = all(checks.values())
    width = max(len(n) for n in matrix)
    print(f"{'':{width}}  " + "  ".join(f"{d:10}" for d in DOORS), file=sys.stderr)
    for n, row in matrix.items():
        print(f"{n:{width}}  " + "  ".join(f"{(row[d] if len(row[d]) < 10 else 'WRONG'):10}" for d in DOORS), file=sys.stderr)
    print(json.dumps({"doors": checks, "ok": ok, "matrix": matrix}, indent=1))
    if not ok:
        sys.exit(1)

def friendly():
    """SQL as DuckDB's users write it (round 34, `friendly.rs`), each form's answer equal to DuckDB's
    over the same rows: PIVOT and UNPIVOT (DuckDB's statements and the standard's), COLUMNS(…),
    `* RENAME`, ORDER BY ALL, FETCH FIRST, list comprehensions and lambdas, a struct's field,
    max_by and arg_min, string_split, json_extract, DuckDB's ASOF JOIN … ON, a select's alias in
    its WHERE, SUMMARIZE; a DOUBLE meeting a DECIMAL (a DOUBLE, as DuckDB and Postgres make it: it
    was a DECIMAL(30, 15), which failed past 10^15) and an INSERT's VALUES of both; samples that
    sample (TABLESAMPLE was ignored); refusals by name; the
    same answers spread over three nodes; and what `random_sql.py` found (`- -3` written again as
    a comment, a DISTINCT over a CASE refused, two IN lists of a column taken as sets of values,
    columns of one name on both sides of a join mixed up); `IN` and `EXISTS` subqueries in a SELECT
    list, a CASE and an aggregate, NULLs and all."""
    import datetime, decimal, duckdb, pyarrow as pa
    lake = new_lake()
    import psycopg
    nodes = [Node(lake, A.port + i, tier_secs=1, **({"pg": f"127.0.0.1:{A.port + 10}"} if i == 0 else {})).start() for i in range(3)]
    time.sleep(1)
    duck = duckdb.connect()
    t0 = datetime.datetime(2026, 1, 1)
    def row(i):
        n = "NULL" if i % 5 == 0 else str(i / 2)
        l = "[]" if i % 10 == 0 else f"[{i % 5}, {i % 3}]"
        j = json.dumps({"a": {"b": i}, "s": f"v{i % 3}"}).replace("'", "''")
        return f"({i}, {i % 7}, '{'abc'[i % 3]}', {i * 1.25 + 0.5}, {n}, {l}, TIMESTAMP '{t0 + datetime.timedelta(minutes=i)}', '{j}')"
    setup = ["CREATE TABLE t (id INTEGER, k INTEGER, g VARCHAR, x DOUBLE, n DOUBLE, l INTEGER[], ts TIMESTAMP, j VARCHAR)",
             "INSERT INTO t VALUES " + ", ".join(row(i) for i in range(2000)),
             "CREATE TABLE q (k INTEGER, ts TIMESTAMP, p DOUBLE)",
             "INSERT INTO q VALUES " + ", ".join(f"({k}, TIMESTAMP '{t0 + datetime.timedelta(minutes=37 * i + k)}', {i + k / 10})" for i in range(60) for k in range(6)),
             # (doubles past 10^15 beside decimals: DataFusion made both a DECIMAL(30, 15), and failed)
             "CREATE TABLE big (x DOUBLE, r REAL, d DECIMAL(38, 2))",
             "INSERT INTO big VALUES (1e20, 1.5, 12.34), (0.7, 0.25, 0.5), (1e-20, NULL, 99999999999999999999.99), (-3e18, -2.5, -1.25), (NULL, 3, NULL)"]
    for s_ in setup:
        sql(A.port, s_)
        duck.execute(s_)
    time.sleep(3)  # (tiered to files: a spread query slices them)

    def norm(v):
        if isinstance(v, bool) or v is None or isinstance(v, str):
            return v
        if isinstance(v, (int, float, decimal.Decimal)):
            return round(float(v), 6)
        if isinstance(v, (list, tuple)):
            return tuple(norm(x) for x in v)
        if isinstance(v, dict):
            return tuple(sorted((k, norm(x)) for k, x in v.items()))
        if isinstance(v, (datetime.datetime, datetime.date)):
            return v.isoformat()
        return str(v)

    def ours(q, port=A.port, spread=None):
        path = "/sql?format=arrow" + ("" if spread is None else f"&spread={spread}")
        t = pa.ipc.open_stream(call(port, "POST", path, q.encode(), timeout=120)).read_all()
        return t.column_names, [tuple(norm(v) for v in r.values()) for r in t.to_pylist()]

    def theirs(q):
        r = duck.execute(q)
        return [d[0] for d in r.description], [tuple(norm(v) for v in x) for x in r.fetchall()]

    same = {  # name: (query, its columns' names compared too, its order compared too)
        "PIVOT t ON g USING sum(x) GROUP BY k": ("PIVOT (SELECT k, g, x FROM t) ON g USING sum(x) GROUP BY k", True, False),
        "PIVOT with aggregates named": ("PIVOT (SELECT k % 3 AS m, g, x FROM t) ON g USING sum(x) AS s, count(*) AS n", True, False),
        "PIVOT … ON g IN (…)": ("PIVOT (SELECT k, g, x FROM t) ON g IN ('a', 'b') USING max(x) GROUP BY k", True, False),
        "the standard's PIVOT": ("SELECT * FROM (SELECT k, g, x FROM t) PIVOT (sum(x) FOR g IN ('a' AS first, 'b'))", True, False),
        "UNPIVOT … INTO NAME … VALUE …": ("UNPIVOT (SELECT id, x, n FROM t) ON x, n INTO NAME col VALUE val", True, False),
        "the standard's UNPIVOT, INCLUDE NULLS": ("SELECT * FROM (SELECT id, x, n FROM t) UNPIVOT INCLUDE NULLS (val FOR col IN (x, n))", True, False),
        "UNPIVOT … ON COLUMNS(…)": ("UNPIVOT (SELECT id, x, n FROM t) ON COLUMNS('^(x|n)$') INTO NAME col VALUE val", True, False),
        "COLUMNS('regex')": ("SELECT COLUMNS('^(id|x)$') FROM t", True, False),
        "min(COLUMNS(*))": ("SELECT min(COLUMNS(*)) FROM (SELECT id, x, n FROM t)", True, False),
        "COLUMNS([…]) in a WHERE": ("SELECT id FROM t WHERE COLUMNS(['id', 'x']) > 1000", False, False),
        "* EXCLUDE … RENAME …": ("SELECT * EXCLUDE (l, j) RENAME (g AS grp) FROM t", True, False),
        "ORDER BY ALL": ("SELECT g, k, id FROM t ORDER BY ALL", True, True),
        "ORDER BY ALL DESC over *": ("SELECT * FROM (SELECT g, id FROM t) ORDER BY ALL DESC", True, True),
        "OFFSET … FETCH NEXT … ROWS ONLY": ("SELECT id FROM t ORDER BY id DESC OFFSET 3 ROWS FETCH NEXT 5 ROWS ONLY", True, True),
        "a list comprehension": ("SELECT id, [y * 2 FOR y IN l IF y > 0] AS d FROM t", True, False),
        "lambdas (x -> …, and AND in their bodies)": ("SELECT id, list_transform(l, y -> y + 1) AS a, list_filter(l, y -> y > 0 AND y < 4) AS b FROM t", True, False),
        "LAMBDA y: …": ("SELECT id, list_transform(l, LAMBDA y: y * 10) AS a FROM t", True, False),
        "a struct's field": ("SELECT ({'a': id, 'b': g}).a AS a FROM t", True, False),
        "max_by, arg_min, min_by (named as written)": ("SELECT g, max_by(id, x), arg_min(id, x), min_by(k, x) FROM t GROUP BY g", True, False),
        "max_by over NULLs": ("SELECT k, max_by(id, n) AS a, arg_max(id, n) AS b FROM t GROUP BY k", True, False),
        "string_split": ("SELECT string_split(g || ',' || k, ',') AS s FROM t", True, False),
        "json_extract, json_extract_string": ("SELECT id, json_extract(j, '$.a.b') AS b, json_extract_string(j, '$.s') AS s FROM t", True, False),
        "DuckDB's ASOF JOIN … ON": ("SELECT t.id, q.p FROM t ASOF JOIN q ON t.k = q.k AND t.ts >= q.ts", True, False),
        "ASOF LEFT JOIN … ON": ("SELECT t.id, q.p FROM t ASOF LEFT JOIN q ON t.k = q.k AND t.ts >= q.ts", True, False),
        "a select's alias in its WHERE": ("SELECT x * 2 AS dbl FROM t WHERE dbl > 4000", True, False),
        "… but a column of that name wins": ("SELECT id + 100 AS x FROM t WHERE x > 20", True, False),
        "WITH RECURSIVE, its step naming a column it gives again (its probe asked itself, and the node died)": ("WITH RECURSIVE nodes AS (SELECT 1 AS id UNION ALL SELECT id + 1 AS id FROM nodes WHERE id < 10) SELECT * FROM nodes", True, False),
        "WITH RECURSIVE, an alias in its step's WHERE": ("WITH RECURSIVE r(n) AS (SELECT 1 UNION ALL SELECT n + 1 AS m FROM r WHERE m < 6) SELECT * FROM r", True, False),
        "a select's alias in its WHERE, inside a CTE": ("WITH d AS (SELECT x * 2 AS dbl FROM t WHERE dbl > 4000), e AS (SELECT dbl + 1 AS u FROM d WHERE u > 4500) SELECT * FROM e", True, False),
        "ORDER BY ALL inside a CTE": ("WITH a AS (SELECT g, k, id FROM t ORDER BY ALL LIMIT 5) SELECT * FROM a", True, False),
        "a minus before a minus, in a text written again (it read back as a comment)": ("SELECT id, - -k AS m, - - -x AS b FROM t WHERE m > 3 AND g IS DISTINCT FROM 'b'", True, False),
        "DISTINCT over a CASE whose WHEN shows its THEN isn't NULL (random_sql.py)": ("SELECT DISTINCT CASE WHEN k < 3 AND n = 2.5 THEN n ELSE 0 END AS c FROM t", True, False),
        "x IN (a column, …) AND x IN (…): not the lists' intersection (random_sql.py)": ("SELECT id FROM t WHERE g IN (g, 'z') AND g IN ('a', 'b')", True, False),
        "x IN (…) AND x NOT IN (NULL): no row (random_sql.py)": ("SELECT count(*) AS c FROM t WHERE g IN ('a', 'b') AND g NOT IN (NULL)", True, False),
        "columns of one name on both sides of a LEFT JOIN, filtered on its padded side (random_sql.py)": ("SELECT (t.ts - q.ts) AS d, t.k FROM t LEFT JOIN q ON t.id = q.k WHERE q.k IS DISTINCT FROM 3", True, False),
        "a DOUBLE past 10^15 compared with decimals (=, >, <, BETWEEN, IN)": ("SELECT x, x = 0.7 AS e, x > 0.5 AS g, x < 1e30 AS l, x BETWEEN 0.5 AND 2.5 AS b, x IN (0.7, 2.5) AS i FROM big", True, False),
        "…in arithmetic, a REAL's and a DECIMAL column's too": ("SELECT x * 1.5 AS a, x + 0.25 AS b, r * 2.5 AS c, d * x AS e, d + 0.01 AS f FROM big", True, False),
        "…as CASE's branches, COALESCE, GREATEST and LEAST": ("SELECT CASE WHEN x > 1 THEN x ELSE 0.5 END AS c, coalesce(x, 0.5) AS o, greatest(x, 0.5) AS g, least(x, 2.5) AS l FROM big", True, False),
        "…in a UNION and as a join's key": ("SELECT x FROM big UNION ALL SELECT 0.25 UNION ALL SELECT big.x FROM big JOIN (VALUES (0.7)) v(e) ON big.x = v.e", True, False),
        # (IN and EXISTS outside a WHERE couldn't be planned: `optimize::SubqueriesMarked`)
        "x IN (SELECT …) in a SELECT list, NULLs among its values": ("SELECT id, x IN (SELECT n FROM t WHERE id < 30) AS i FROM t WHERE id < 40", True, False),
        "x NOT IN (SELECT …) in a SELECT list, NULLs among its values": ("SELECT id, x NOT IN (SELECT n FROM t WHERE id < 30) AS i FROM t WHERE id < 40", True, False),
        "a NULL x IN (SELECT …), and a NULL x IN no rows": ("SELECT id, n IN (SELECT k FROM t WHERE id < 50) AS i, n IN (SELECT k FROM t WHERE id < 0) AS e FROM t WHERE id < 25", True, False),
        "x IN (SELECT …) with no NULL among its values": ("SELECT id, k IN (SELECT k FROM t WHERE g = 'a' AND k < 3) AS i FROM t WHERE id < 50", True, False),
        "x IN (SELECT …) correlated, NULLs on both sides": ("SELECT id, n IN (SELECT t2.n FROM t t2 WHERE t2.k = t.k AND t2.id < 40) AS i FROM t WHERE id < 60", True, False),
        "EXISTS and NOT EXISTS correlated, in a SELECT list": ("SELECT id, EXISTS (SELECT 1 FROM q WHERE q.k = t.k AND q.p > t.x) AS e, NOT EXISTS (SELECT 1 FROM q WHERE q.k = t.k + 3) AS n FROM t WHERE id < 100", True, False),
        "IN (SELECT …) in a CASE": ("SELECT id, CASE WHEN g IN (SELECT g FROM t WHERE k = 3 AND id < 10) THEN 'in' ELSE 'out' END AS c FROM t WHERE id < 30", True, False),
        "IN and EXISTS in an aggregate's FILTER and argument": ("SELECT k, count(*) FILTER (WHERE x IN (SELECT n FROM t WHERE id < 100)) AS c, sum(CASE WHEN EXISTS (SELECT 1 FROM q WHERE q.k = t.k AND q.p > 50) THEN 1 ELSE 0 END) AS s FROM t GROUP BY k", True, False),
    }
    checks, failed = {}, {}
    for name, (q, names, ordered) in same.items():
        try:
            (cn, got), (dn, want) = ours(q), theirs(q)
            ok = (got == want if ordered else sorted(got, key=repr) == sorted(want, key=repr)) and (not names or cn == dn) and len(want) > 0
        except Exception as e:
            ok, cn, got, dn, want = False, str(e)[:400], [], [], []
        checks[f"{name} == DuckDB's"] = ok
        if not ok:
            failed[name] = {"ours": [cn, got[:4]], "duckdb": [dn, want[:4]]}
    # SUMMARIZE: the exact columns (approximate ones and the mean's and spread's text aside)
    cn, got = ours("SUMMARIZE t")
    dn, want = theirs("SUMMARIZE t")
    pick = lambda names, rows: sorted((r[0], r[1], r[names.index("count")], r[names.index("null_percentage")]) + ((r[2], r[3]) if r[0] in ("id", "k", "g") else ()) for r in rows)
    checks["SUMMARIZE: each column's name, type, count, NULLs and (whole and text columns) min and max == DuckDB's"] = cn == dn and pick(cn, got) == pick(dn, want)
    if not checks[list(checks)[-1]]:
        failed["SUMMARIZE"] = {"ours": [cn, pick(cn, got)], "duckdb": [dn, pick(dn, want)]}
    count = lambda q: sql(A.port, q)[0]["n"]
    ids = {r["id"] for r in sql(A.port, "SELECT id FROM t USING SAMPLE 7 ROWS")}
    share = [count("SELECT count(*) AS n FROM t USING SAMPLE 10%"), count("SELECT count(*) AS n FROM (SELECT * FROM t TABLESAMPLE SYSTEM (10)) s"),
             count("SELECT count(*) AS n FROM (SELECT * FROM t TABLESAMPLE (5 ROWS)) s")]
    checks["USING SAMPLE n ROWS / n%, TABLESAMPLE (n) / (n ROWS): samples of those sizes (TABLESAMPLE was ignored)"] = len(ids) == 7 and ids <= set(range(2000)) and 100 < share[0] < 320 and 100 < share[1] < 320 and share[2] == 5
    refused = [_raises_text(lambda q=q: sql(A.port, q)) for q in ("SELECT id FROM t FETCH FIRST 10 PERCENT ROWS ONLY", "SELECT max_by(id, x) OVER () FROM t", "SELECT json_extract(j, g) FROM t")]
    checks["refused by name: FETCH … PERCENT, max_by(…) OVER, a JSON path that isn't a literal"] = "PERCENT" in refused[0] and "first_value" in refused[1] and "literal" in refused[2]
    spread = ["PIVOT (SELECT k, g, x FROM t) ON g USING sum(x) GROUP BY k", "SELECT min(COLUMNS(*)) FROM (SELECT id, x, n FROM t)",
              "SELECT id, [y * 2 FOR y IN l IF y > 0] AS d FROM t", "SELECT g, max_by(id, x), arg_min(id, x) FROM t GROUP BY g",
              "SELECT t.id, q.p FROM t ASOF JOIN q ON t.k = q.k AND t.ts >= q.ts", "UNPIVOT (SELECT id, x, n FROM t) ON x, n INTO NAME col VALUE val",
              "SELECT id, x IN (SELECT n FROM t WHERE id < 300) AS i, EXISTS (SELECT 1 FROM q WHERE q.k = t.k AND q.p > t.x) AS e FROM t"]
    apart = {q: (sorted(ours(q, spread=1)[1], key=repr), sorted(ours(q, spread=0)[1], key=repr)) for q in spread}
    checks["spread over three nodes == one node"] = all(a == b for a, b in apart.values())
    with psycopg.connect(f"host=127.0.0.1 port={A.port + 10} user=u dbname=lake", autocommit=True) as pg:  # (described, then run)
        door = [sorted(norm(tuple(r)) for r in pg.execute(q, (0,)).fetchall()) for q in (
            "SELECT id, list_filter(l, y -> y > 0 AND y < 4) AS b FROM t WHERE id >= %s", "SELECT g, max_by(id, x) FROM t WHERE k >= %s GROUP BY g")]
    want = [sorted(theirs(q)[1]) for q in ("SELECT id, list_filter(l, y -> y > 0 AND y < 4) AS b FROM t", "SELECT g, max_by(id, x) FROM t GROUP BY g")]
    checks["over Postgres (a lambda, max_by) == DuckDB's"] = door == want
    sql(A.port, "CREATE VIEW best AS SELECT g, max_by(id, x) AS best, [y + 1 FOR y IN list(k)] AS ks FROM t GROUP BY g")
    call(A.port, "POST", "/views/plus", b"SELECT id, list_transform(l, y -> y + 1) AS a FROM t")
    sql(A.port, "INSERT INTO t VALUES (5000, 1, 'a', 9999.5, NULL, [7, 8], TIMESTAMP '2026-02-01 00:00:00', '{}')")
    duck.execute("INSERT INTO t VALUES (5000, 1, 'a', 9999.5, NULL, [7, 8], TIMESTAMP '2026-02-01 00:00:00', '{}')")
    view = sorted((r["g"], r["best"]) for r in sql(A.port, "SELECT g, best FROM best"))
    plus = {r["id"]: r.get("a") for r in sql(A.port, "SELECT id, a FROM plus WHERE id IN (5000, 1)")}
    checks["a stored view and a materialized view over them, read after a write"] = view == sorted(duck.execute("SELECT g, max_by(id, x) FROM t GROUP BY g").fetchall()) and plus == {5000: [8, 9], 1: [2, 2]}
    for n in nodes:
        n.kill()
    ok = all(checks.values())
    print(json.dumps({"friendly": checks, "ok": ok}, indent=1))
    if not ok:
        print(json.dumps(failed, indent=1, default=str)[:20000])
        sys.exit(1)
    return f"SQL as DuckDB's users write it: {len(same) + 1} forms answer as DuckDB does, samples sample, refusals by name, spread == one node"


def attached():
    """An attached lake read while its own leader changes rows, tiers and purges them: every read is
    its table as of one commit (`Catalog::settle`, `Pruned::scan`). A reader's catalog entries are
    the newest state while its log's end moves every 250 ms; reads that mixed the two lost a changed
    row (336 of 607 reads on main 2801b4d), or kept both versions of a table's first changed row."""
    other, lake = new_lake(), new_lake()
    a = Node(other, A.port, tier_secs=0.5, env={"PONDRA_PURGE_ROWS": "1"}).start()  # (tiering and purging all the while)
    b = Node(lake, A.port + 1).start()
    firsts = [f"f{i}" for i in range(6)]  # (each changed once, while it is read)
    for t in ["t"] + firsts:
        sql(a.port, f"CREATE TABLE {t} (id BIGINT, amount DOUBLE)")
        sql(a.port, f"INSERT INTO {t} VALUES (1, 1.5), (2, 3.0), (3, 4.5)")
    sql(b.port, f"ATTACH '{other}' AS other")
    until(lambda: _try(lambda: sql(b.port, "SELECT count(*) AS n FROM other.t")), [{"n": 3}], 15)
    reads, wrong, stop = {}, [], threading.Event()
    def read(tables):
        while not stop.is_set():
            for t in tables:
                r = _try(lambda: sql(b.port, f"SELECT id, _version AS v FROM other.{t} ORDER BY id"))
                reads[t] = reads.get(t, 0) + 1
                if not isinstance(r, list) or [x["id"] for x in r] != [1, 2, 3]:
                    wrong.append((t, r))
    readers = [threading.Thread(target=read, args=(ts,)) for ts in (["t"], firsts)]
    [r.start() for r in readers]
    try:
        for i in range(80):
            sql(a.port, "UPDATE t SET amount = amount + 1 WHERE id = 1")
            if i % 12 == 6 and i // 12 < len(firsts):
                sql(a.port, f"UPDATE {firsts[i // 12]} SET amount = amount + 1 WHERE id = 1")
            time.sleep(0.05)
    finally:
        stop.set()
        [r.join() for r in readers]
    [n.kill() for n in (a, b)]
    checks = {
        f"every read of a table of an attached lake while its leader updates, tiers and purges it holds each row once ({reads.get('t', 0)} reads)": reads.get("t", 0) > 50 and not any(t == "t" for t, _ in wrong),
        "…and of tables read while their first UPDATE lands": all(reads.get(t, 0) > 3 for t in firsts) and not any(t in firsts for t, _ in wrong),
    }
    for name, good in checks.items():
        print(f"attached: {name}: {'OK' if good else 'FAIL'}")
    if not all(checks.values()):
        print(f"attached: {len(wrong)} wrong, {wrong[:5]}")
        sys.exit(1)
    return "an attached lake read while its leader changes, tiers and purges rows: every read as of one commit"


def dialects():
    """What people from other databases type on their first days (round 34, L6): the statements of
    `tools/dialects_check.py`, spelled as Postgres, DuckDB, Snowflake, Spark, MySQL, BigQuery and SQL
    Server users spell them, each dialect's in a session of its own. Each runs or is refused with a
    SQLSTATE, none takes the node down, and each dialect runs at least as many as it did when its
    floor was set (FLOOR: raise it as spellings are added, never lower it). And what they found: a
    table with columns named created_at, version and row_id, keyed or not, takes UPDATE, UPDATE …
    FROM, DELETE, INSERT … ON CONFLICT and MERGE, its own columns kept apart from the system ones
    (`change::select_as` named both `__o_created_at`, and every change of such a table failed)."""
    import dialects_check
    FLOOR = {"postgres": 41, "duckdb": 31, "snowflake": 13, "spark": 10, "mysql": 19, "bigquery": 12, "sqlserver": 6}
    XX000 = 24  # (refusals that are internal errors: lower it as they get codes, never raise it)
    lake = new_lake()
    node = Node(lake, A.port).start()
    q = lambda s: sql(A.port, s)
    checks, info = {}, {}
    # Columns named as the system's are: an append table and a keyed one, three rows each, then every kind of change.
    cols = "created_at TIMESTAMP, version INT, row_id INT, v INT"
    q(f"CREATE TABLE ap (id INT, {cols})")
    q(f"CREATE TABLE kv (id INT PRIMARY KEY, {cols})")
    for t in ("ap", "kv"):
        q(f"INSERT INTO {t} VALUES (1, TIMESTAMP '2026-01-01 00:00:00', 10, 100, 1), (2, TIMESTAMP '2026-01-02 00:00:00', 20, 200, 2), (3, TIMESTAMP '2026-01-03 00:00:00', 30, 300, 3)")
    ids = {t: q(f"SELECT id, _row_id FROM {t} ORDER BY id") for t in ("ap", "kv")}
    errors = {}
    for t in ("ap", "kv"):
        for s_ in (f"UPDATE {t} SET v = v + 10 WHERE id = 1",
                   f"UPDATE {t} SET v = s.v FROM (VALUES (2, 22)) AS s(id, v) WHERE {t}.id = s.id",
                   f"DELETE FROM {t} WHERE id = 3",
                   f"INSERT INTO {t} VALUES (4, TIMESTAMP '2026-01-04 00:00:00', 40, 400, 4)" + (" ON CONFLICT (id) DO UPDATE SET v = EXCLUDED.v" if t == "kv" else ""),
                   f"MERGE INTO {t} USING (VALUES (4, 44), (5, 5)) AS s(id, v) ON {t}.id = s.id WHEN MATCHED THEN UPDATE SET v = s.v "
                   f"WHEN NOT MATCHED THEN INSERT VALUES (s.id, TIMESTAMP '2026-01-05 00:00:00', 50, 500, s.v)"):
            try:
                q(s_)
            except Exception as e:
                errors.setdefault(t, []).append(f"{s_[:40]}: {str(e)[:160]}")
    if "kv" not in errors:
        try:
            q("INSERT INTO kv VALUES (5, TIMESTAMP '2026-01-05 00:00:00', 50, 500, 55) ON CONFLICT (id) DO UPDATE SET v = EXCLUDED.v")
        except Exception as e:
            errors.setdefault("kv", []).append(str(e)[:160])
    info["errors"] = errors
    want = lambda last: [{"id": 1, "created_at": "2026-01-01T00:00:00", "version": 10, "row_id": 100, "v": 11},
                         {"id": 2, "created_at": "2026-01-02T00:00:00", "version": 20, "row_id": 200, "v": 22},
                         {"id": 4, "created_at": "2026-01-04T00:00:00", "version": 40, "row_id": 400, "v": 44},
                         {"id": 5, "created_at": "2026-01-05T00:00:00", "version": 50, "row_id": 500, "v": last}]
    got = {t: q(f"SELECT id, created_at, version, row_id, v FROM {t} ORDER BY id") for t in ("ap", "kv")}
    info["rows"] = got
    kept = {t: q(f"SELECT id, _row_id FROM {t} WHERE id IN (1, 2) ORDER BY id") == ids[t][:2] for t in ("ap", "kv")}
    info["row ids kept"] = kept
    checks["a table with columns named created_at, version and row_id takes UPDATE, UPDATE … FROM, DELETE, INSERT, MERGE (and ON CONFLICT, keyed): its own columns as written, changed rows keeping their _row_id"] = \
        not errors and got["ap"] == want(5) and got["kv"] == want(55) and all(kept.values())
    # The newcomers' statements, each dialect in its own session.
    rows, downs = dialects_check.answer(node, A.port)
    ran = {d: sum(r["ok"] for r in rows if r["dialect"] == d) for d in FLOOR}
    info["ran"], info["downs"] = ran, downs
    uncoded = [r["sql"][:80] for r in rows if not r["ok"] and not r["sqlstate"]]
    info["refused without a SQLSTATE"] = uncoded
    checks["no newcomer's statement takes the node down"] = downs == 0
    checks["each refusal carries a SQLSTATE"] = not uncoded
    checks["each dialect runs at least its floor of the newcomers' statements"] = all(ran[d] >= FLOOR[d] for d in FLOOR)
    missed = [f"{r['sql'][:70]}: {r['sqlstate']} {r['message'][:120]}" for r in rows if r["expect"] and not dialects_check.met(r)]
    info["missed their refusal"] = missed
    checks["what a SET asks for is done, or refused by name with its SQLSTATE and the way out (SET ROLE, TRANSACTION, NAMES, DateStyle, @x, …)"] = not missed
    internal = [r["sql"][:80] for r in rows if not r["ok"] and r["sqlstate"] == "XX000"]
    info["refused as XX000 (internal)"] = internal
    checks[f"at most {XX000} refusals are XX000 (an internal error) rather than a code that names what went wrong"] = len(internal) <= XX000
    node.kill()
    ok = all(checks.values())
    print(json.dumps({"dialects": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"dialects: {sum(ran.values())} of {len(rows)} newcomers' statements run, the rest refused with a SQLSTATE; columns named as system ones change: all {len(checks)} checks pass"


def publishing():
    """What can't be published as Delta or Iceberg is refused by name, never written wrong or
    skipped quietly: asked for, a column the format has no type for, a materialized view finished
    as it is read (its files hold partial rows) and a history view are refused, and so is sharing
    one, or adding such a column to a published table; under the node's --publish they are made,
    left out of that format, and the statement says so; and nothing of theirs is written as Delta or
    Iceberg (a finished view's partial rows were, before)."""
    import urllib.request
    lake = new_lake()
    node = Node(lake, A.port, tier_secs=0.5, publish="delta,iceberg").start()
    q = lambda s: sql(A.port, s)
    err = lambda s: _raises_text(lambda: q(s))
    said = lambda s: json.loads(urllib.request.urlopen(urllib.request.Request(f"http://127.0.0.1:{A.port}/sql", s.encode()), timeout=60).headers.get("x-pondra-notices") or "[]")
    iceberg = lambda t: _try(lambda: call(A.port, "GET", f"/v1/namespaces/default/tables/{t}")) is not None
    checks = {}
    try:
        q("CREATE TABLE ev (id BIGINT, g VARCHAR, amount DOUBLE, ts TIMESTAMP)")
        e = err("CREATE TABLE spans (id BIGINT, d INTERVAL) WITH (publish = 'delta')")
        checks["a column Delta has no type for, asked for: refused by name"] = "can't be published as delta" in e and "no type for d" in e
        heard = said("CREATE TABLE spans (id BIGINT, d INTERVAL)")
        checks["…under --publish: made, left out of both formats, and said"] = len(heard) == 1 and "spans isn't published as" in heard[0] and "no type for d" in heard[0]
        e = err("ALTER TABLE ev ADD COLUMN d INTERVAL")
        checks["a column added to a published table that the format can't carry: refused"] = "ev can't be published as delta" in e
        heard = said("CREATE MATERIALIZED VIEW avgs AS SELECT g, avg(amount) AS a FROM ev GROUP BY g")
        checks["a view finished as it is read, under --publish: left out, and said"] = len(heard) == 1 and "partial rows" in heard[0]
        e = err("ALTER TABLE avgs SET (publish = 'iceberg')")
        checks["…and refused when asked for"] = "can't be published as iceberg" in e and "partial rows" in e
        heard = said("CREATE MATERIALIZED VIEW hist WITH (history = 'id', sequence_by = 'ts') AS SELECT id, amount, ts FROM ev")
        checks["a history view, under --publish: left out, and said"] = len(heard) == 1 and "__start_at" in heard[0]
        q("CREATE SHARE out_s")
        e = err("ALTER SHARE out_s ADD TABLE avgs")
        checks["sharing one (a share hands out a Delta log): refused by name"] = "avgs can't be shared" in e and "partial rows" in e
        q("INSERT INTO ev VALUES (1, 'a', 2.0, '2026-01-01 00:00:00'), (2, 'a', 4.0, '2026-01-01 00:00:01'), (3, 'b', 6.0, '2026-01-01 00:00:02')")
        q("INSERT INTO spans VALUES (1, INTERVAL '2 days')")
        q("CHECKPOINT")
        until(lambda: iceberg("ev"), True, 30)
        checks["a plain table: published as --publish says"] = iceberg("ev")
        checks["…the others never: no Iceberg or Delta of them"] = not any(iceberg(t) for t in ("spans", "avgs", "hist")) and (A.s3 or not any(
            os.path.exists(os.path.join(lake, "data", t, d)) for t in ("spans", "avgs", "hist") for d in ("_delta_log", "metadata")))
        checks["…and read as before"] = q("SELECT g, a FROM avgs ORDER BY g") == [{"g": "a", "a": 3.0}, {"g": "b", "a": 6.0}] and q("SELECT count(*) AS n FROM spans") == [{"n": 1}]
    finally:
        node.kill()
    for name, good in checks.items():
        print(f"publishing: {name}: {'OK' if good else 'FAIL'}")
    if not all(checks.values()):
        sys.exit(1)
    return "what can't be published is refused by name, left out of --publish with a notice, and never written"


def backpressure():
    """Writes wait while more than `--backlog` rows wait in the log to be tiered, and only while
    tiering can run (invariant 283): its round takes the lake's lock, and a view that runs its query
    again holds that lock while its rows commit, so a commit held back behind tiering stopped every
    write for good (Nexmark's twenty views, now and then). 8,000 rows written fast, 500 a write,
    wait for tiering (never half of them in the log at once; all of them without the wait); then
    150 writes under two such views each answer in time, and the views == their queries."""
    lake = new_lake()
    node = Node(lake, A.port, tier_secs=2, backlog=1000).start()
    q = lambda s: sql(A.port, s)
    rows = lambda i, n: "".join(json.dumps({"k": i * n + j, "v": (i * 7919 + j * 31) % 10007}) + "\n" for j in range(n)).encode()
    checks = {}
    try:
        q("CREATE TABLE ev (k BIGINT, v BIGINT)")
        most = 0
        for i in range(16):
            call(A.port, "POST", f"/append/ev?producer=bp&seq={i + 1}", rows(i, 500), timeout=60)
            most = max(most, call(A.port, "GET", "/stats")["untiered_rows"])
        checks[f"writes wait for tiering: never half of 8,000 rows in the log at once (at most {most})"] = most < 4000
        views = {"top": ("SELECT k, v FROM ev ORDER BY v DESC, k LIMIT 5", "v DESC, k"), "mid": ("SELECT k % 7 AS g, median(v) AS m FROM ev GROUP BY k % 7", "g")}
        for name, (query, _) in views.items():
            q(f"CREATE MATERIALIZED VIEW {name} AS {query}")
        slowest, stuck = 0.0, None
        for i in range(150):
            t = time.time()
            try:
                call(A.port, "POST", f"/append/ev?producer=bp2&seq={i + 1}", rows(100 + i, 100), timeout=30)
            except Exception as e:
                stuck = f"write {i + 1}: {e!r}"[:200]
                break
            slowest = max(slowest, time.time() - t)
        checks[f"…while views run their queries again: 150 writes, each in time (slowest {slowest:.1f} s{'; ' + stuck if stuck else ''})"] = stuck is None
        checks["…and the views == their queries"] = stuck is None and all(_bykey_same(q, name, query, by) for name, (query, by) in views.items())
    finally:
        node.kill()
    for name, good in checks.items():
        print(f"backpressure: {name}: {'OK' if good else 'FAIL'}")
    if not all(checks.values()):
        sys.exit(1)
    return "writes wait for tiering only while it can run"


def unique_doors():
    """UNIQUE through every loading door (`constraints.rs`, `constraints::queue`): an append (JSON and
    Arrow), Flight DoPut, COPY FROM STDIN, Kafka (INVALID_RECORD) and INSERT … VALUES refuse a value twice (23505) and a batch
    whole, on one node and on three; a retried batch (its producer and seq) is a duplicate and never a
    23505, not even one the plain path committed before the table got its UNIQUE; a producer's
    pipelined batches commit in the order they were cut, through a refused batch that is sent again
    (invariant 29), on the leader and on a follower; an identity column and a DEFAULT on a UNIQUE table
    fill as they do on one without (an append and COPY); three nodes appending at once keep every id
    once; a table without UNIQUE takes its appends as before (`plain_ms`: 2,000 one-row appends)."""
    import pyarrow as pa, pyarrow.flight as fl, psycopg, concurrent.futures as cf
    from collections import Counter
    lake = new_lake()
    P, fport, pgport = A.port, A.port + 30, A.port + 10
    checks, info = {}, {}

    def post(port, path, body, ctype=None):
        """One POST: {status, code (x-pondra-sqlstate), text, ack (the JSON of a 200)}."""
        c = http.client.HTTPConnection("127.0.0.1", port, timeout=120)
        c.request("POST", path, body, {"content-type": ctype} if ctype else {})
        r = c.getresponse()
        data = r.read()
        c.close()
        if r.status == 200:
            return {"status": 200, "code": None, "text": "", "ack": json.loads(data)}
        return {"status": r.status, "code": r.getheader("x-pondra-sqlstate"), "text": data.decode()[:400], "ack": None}

    ndjson = lambda rows: "".join(json.dumps(r) + "\n" for r in rows).encode()
    arrow = "application/vnd.apache.arrow.stream"

    def ipc(rows):
        t = pa.table({"id": pa.array([i for i, _ in rows], pa.int64()), "name": pa.array([n for _, n in rows], pa.string())})
        sink = pa.BufferOutputStream()
        w = pa.ipc.new_stream(sink, t.schema)
        w.write_table(t)
        w.close()
        return sink.getvalue().to_pybytes()

    schema = pa.schema([("id", pa.int64()), ("name", pa.string())])

    def fput(client, path, batches):
        """A DoPut of `batches` (lists of (id, name)): (the acks read, the error text or None)."""
        w, r = client.do_put(fl.FlightDescriptor.for_path(*path), schema)
        acks, err = [], None
        try:
            for batch in batches:
                w.write_batch(pa.record_batch([pa.array([i for i, _ in batch], pa.int64()), pa.array([n for _, n in batch], pa.string())], schema=schema))
            w.done_writing()
            while (buf := r.read()) is not None:
                acks.append(json.loads(buf.to_pybytes()))
        except (fl.FlightError, pa.ArrowException) as e:  # (a refusal comes as either, by its status)
            err = str(e)
        try:  # (a refusal can surface when the writer closes, not on a read: keep the first error seen)
            w.close()
        except (fl.FlightError, pa.ArrowException) as e:
            err = err or str(e)
        return acks, err

    ids_of = lambda t, port: [r["id"] for r in sql(port, f"SELECT id FROM {t} ORDER BY id")]

    def settle(f, want, secs=15):
        """What `f` says once it is `want`, or after `secs`: a follower reads what its commit stream has brought."""
        end, got = time.time() + secs, f()
        while got != want and time.time() < end:
            time.sleep(0.1)
            got = f()
        return got

    def one_node():
        node = Node(lake, P, flight=f"127.0.0.1:{fport}", pg=f"127.0.0.1:{pgport}", kafka=f"127.0.0.1:{P + 20}").start()
        try:
            flight = fl.FlightClient(f"grpc://127.0.0.1:{fport}")
            sql(P, "CREATE TABLE u (id INT, name TEXT, UNIQUE (id))")
            ok = post(P, "/append/u", ndjson([{"id": i, "name": "j"} for i in (1, 2, 3)]))
            dup = post(P, "/append/u", ndjson([{"id": 2, "name": "x"}, {"id": 4, "name": "x"}]))
            twice = post(P, "/append/u", ndjson([{"id": 5, "name": "x"}, {"id": 5, "name": "y"}]))
            info["json"] = [ok["status"], dup["code"], dup["text"][:200], twice["code"], ids_of("u", P)]
            checks["HTTP append (JSON): new ids go in; an id already there refuses the whole batch (23505, naming the id); an id twice refuses it too"] = \
                ok["status"] == 200 and dup["code"] == "23505" and "(2)" in dup["text"] and twice["code"] == "23505" and ids_of("u", P) == [1, 2, 3]
            a_ok = post(P, "/append/u", ipc([(10, "a"), (11, "b")]), arrow)
            a_dup = post(P, "/append/u", ipc([(12, "c"), (10, "d")]), arrow)
            a_twice = post(P, "/append/u", ipc([(13, "e"), (13, "f")]), arrow)
            info["arrow"] = [a_ok["status"], a_dup["code"], a_twice["code"]]
            checks["HTTP append (Arrow): new ids go in; a value already there, or a value twice, refuses the batch (23505) and 12 and 13 stay out"] = \
                a_ok["status"] == 200 and a_dup["code"] == "23505" and a_twice["code"] == "23505" and not {12, 13} & set(ids_of("u", P))
            _, f_err = fput(flight, ["u"], [[(20, "f"), (21, "f")]])
            _, f_dup = fput(flight, ["u"], [[(22, "g")], [(20, "g")]])
            info["flight"] = [f_err, f_dup]
            checks["Flight DoPut: new ids go in; a value already there refuses its batch (23505), and the batch before it, acked by then, stays in"] = \
                f_err is None and f_dup is not None and "duplicate key" in f_dup and ids_of("u", P).count(20) == 1 and 22 in ids_of("u", P)
            a1, e1 = fput(flight, ["u", "fp", "1"], [[(30, "p")], [(31, "p")]])
            a2, e2 = fput(flight, ["u", "fp", "1"], [[(30, "p")], [(31, "p")]])
            info["flight_retry"] = [a1, e1, a2, e2]
            checks["Flight DoPut with a producer and seq: the same batches sent again are duplicates (their acks say so), not 23505; the rows are once"] = \
                e1 is None and e2 is None and [a.get("duplicate") for a in a2] == [True, True] and ids_of("u", P).count(30) == 1 and ids_of("u", P).count(31) == 1
            h1 = post(P, "/append/u?producer=hp&seq=1", ndjson([{"id": 50, "name": "h"}]))
            h2 = post(P, "/append/u?producer=hp&seq=1", ndjson([{"id": 50, "name": "h"}]))
            checks["HTTP append with a producer and seq: the retry is a duplicate (its ack says so), not 23505, and the row is once"] = \
                h1["status"] == 200 and h2["status"] == 200 and h2["ack"]["duplicate"] is True and ids_of("u", P).count(50) == 1
            with psycopg.connect(f"host=127.0.0.1 port={pgport} user=u dbname=lake", autocommit=True) as conn:
                cur = conn.cursor()
                try:  # (a door that refuses the table by name, as the plain build does, is a failed check, not an abort)
                    with cur.copy("COPY u FROM STDIN") as cp:
                        cp.write("60\tc\n")
                except psycopg.Error as e:
                    info["copy_first"] = e.sqlstate
                try:
                    with cur.copy("COPY u FROM STDIN") as cp:
                        cp.write("60\tc again\n")
                    copy_dup = None
                except psycopg.Error as e:
                    copy_dup = e.sqlstate
            ins = post(P, "/sql", b"INSERT INTO u VALUES (62, 'x'), (62, 'y')")
            info["copy_insert"] = [copy_dup, ins["code"]]
            checks["COPY FROM STDIN refuses a value already there (23505); INSERT … VALUES refuses a value twice (23505); the rows of the refused batches stay out"] = \
                copy_dup == "23505" and ins["code"] == "23505" and 60 in ids_of("u", P) and 62 not in ids_of("u", P)
            # Kafka: an idempotent producer's batch is a checked append too; a value already there is a bad
            # record (INVALID_RECORD, which librdkafka doesn't send again), never a timeout it retries for ever
            import confluent_kafka as ck

            def produce(values):
                errs = []
                kp = ck.Producer({"bootstrap.servers": f"127.0.0.1:{P + 20}", "enable.idempotence": True, "linger.ms": 50, "message.timeout.ms": 20000})
                for v in values:
                    kp.produce("u", value=json.dumps(v), on_delivery=lambda e, m: errs.append(e and e.name()))
                kp.flush(30)
                return errs

            k_ok, k_dup, k_after = produce([{"id": 90, "name": "k"}, {"id": 91, "name": "k"}]), produce([{"id": 90, "name": "again"}]), produce([{"id": 92, "name": "k"}])
            info["kafka"] = [k_ok, k_dup, k_after]
            checks["Kafka (an idempotent producer): new ids go in; an id already there is refused as INVALID_RECORD, not retried; the next producer's new id goes in; each id once"] = \
                k_ok == [None, None] and k_dup == ["INVALID_RECORD"] and k_after == [None] and [ids_of("u", P).count(i) for i in (90, 91, 92)] == [1, 1, 1]
            # invariant 29: pipelined batches, one refused (23505), the ones after it sent again
            pipe = [[(70, "b1"), (71, "b1")], [(72, "b2"), (73, "b2")], [(1, "dup")], [(74, "b4"), (75, "b4")], [(76, "b5"), (77, "b5")]]
            # the stream answers the batches it has, then stops at the refused one (seq 3): its two after it
            # (seq 4, 5) are never taken, so the producer sends seq 3 again (fixed) and those two with it
            p1_acks, p1 = fput(flight, ["u", "pipe", "1"], pipe)
            p2_acks, p2 = fput(flight, ["u", "pipe", "3"], [[(78, "b3"), (79, "b3")], [(74, "b4"), (75, "b4")], [(76, "b5"), (77, "b5")]])
            order = [r["id"] for r in sql(P, "SELECT id FROM u WHERE id BETWEEN 70 AND 79 ORDER BY _row_id")]
            info["pipelined"] = [len(p1_acks), p1, len(p2_acks), p2, order]
            checks["a pipelined Flight stream commits in the order its batches were cut, through a refused batch (23505) that is sent again with the ones after it: the two acked before it, then the resend's three, none a duplicate"] = \
                p1 is not None and "duplicate key" in p1 and len(p1_acks) == 2 and p2 is None and len(p2_acks) == 3 and \
                not any(a.get("duplicate") for a in p2_acks) and order == [70, 71, 72, 73, 78, 79, 74, 75, 76, 77]
            # a batch the plain path committed before the table had its UNIQUE: sent again, a duplicate
            sql(P, "CREATE TABLE pre (id INT, name TEXT)")
            e_first = post(P, "/append/pre?producer=early&seq=1", ndjson([{"id": 1, "name": "e"}, {"id": 2, "name": "e"}]))
            sql(P, "ALTER TABLE pre ADD CONSTRAINT pre_id UNIQUE (id)")
            e_again = post(P, "/append/pre?producer=early&seq=1", ndjson([{"id": 1, "name": "e"}, {"id": 2, "name": "e"}]))
            e_new = post(P, "/append/pre?producer=early&seq=2", ndjson([{"id": 2, "name": "again"}]))
            info["before_unique"] = [e_first["status"], e_again["ack"] and e_again["ack"]["duplicate"], e_new["code"], ids_of("pre", P)]
            checks["a batch the plain path committed before the table got its UNIQUE, sent again through the checked door, is a duplicate (not 23505); a new seq with a value there is refused"] = \
                e_first["status"] == 200 and e_again["status"] == 200 and e_again["ack"]["duplicate"] is True and e_new["code"] == "23505" and ids_of("pre", P) == [1, 2]
            # an identity column and a DEFAULT on a table with a UNIQUE, loaded as one without it is (the
            # same appends and COPY on both): the identity's values are filled and unique, the DEFAULT applies
            with psycopg.connect(f"host=127.0.0.1 port={pgport} user=u dbname=lake", autocommit=True) as conn:
                cur = conn.cursor()
                for t, unique in (("idu", ", UNIQUE (code)"), ("idp", "")):
                    sql(P, f"CREATE TABLE {t} (id BIGINT GENERATED BY DEFAULT AS IDENTITY, code INT, name TEXT DEFAULT 'none'{unique})")
                    post(P, f"/append/{t}", ndjson([{"code": 1}, {"code": 2, "name": "given"}]))
                    try:
                        with cur.copy(f"COPY {t} (code) FROM STDIN") as cp:
                            cp.write("7\n8\n")
                    except psycopg.Error as e:  # (refused by name on a build without the checked path: the rows stay out)
                        info.setdefault("identity_copy_errors", {})[t] = e.sqlstate
                    post(P, f"/append/{t}", ndjson([{"code": 9}]))
                rows = {t: [(r["code"], r["name"]) for r in sql(P, f"SELECT code, name FROM {t} ORDER BY code")] for t in ("idu", "idp")}
                ids = {t: [r["id"] for r in sql(P, f"SELECT id FROM {t}")] for t in ("idu", "idp")}
                dup_append = post(P, "/append/idu", ndjson([{"code": 2}]))
                try:
                    with cur.copy("COPY idu (code) FROM STDIN") as cp:
                        cp.write("8\n")
                    dup_copy = None
                except psycopg.Error as e:
                    dup_copy = e.sqlstate
            info["identity"] = [rows, ids, dup_append["code"], dup_copy]
            want = [(1, "none"), (2, "given"), (7, "none"), (8, "none"), (9, "none")]
            checks["an identity column and a DEFAULT on a table with UNIQUE are filled as on a table without it, through an append and COPY: ids unique and given, the DEFAULT in place; a code already there refused (23505) by either door"] = \
                rows["idu"] == rows["idp"] == want and all(i is not None for t in ids for i in ids[t]) and len(set(ids["idu"])) == 5 and \
                len(set(ids["idp"])) == 5 and dup_append["code"] == "23505" and dup_copy == "23505"
            # a table without UNIQUE: the plain path, timed
            sql(P, "CREATE TABLE plain (id INT, name TEXT)")
            t0 = time.perf_counter()
            plain_ok = all(post(P, "/append/plain", ndjson([{"id": i, "name": "p"}]))["status"] == 200 for i in range(2000))
            info["plain_ms"] = round((time.perf_counter() - t0) * 1000)
            checks["a table without UNIQUE takes 2,000 one-row appends as before"] = plain_ok and len(ids_of("plain", P)) == 2000
        finally:
            node.kill()

    def three_nodes():
        lake3 = new_lake()
        ports = [P + 1 + i for i in range(3)]
        nodes = [Node(lake3, p, flight=f"127.0.0.1:{fport + 1 + i}").start() for i, p in enumerate(ports)]
        try:
            while len(call(ports[0], "GET", "/stats").get("nodes", ())) < 3:
                time.sleep(0.1)
            sql(ports[0], "CREATE TABLE u3 (id INT, name TEXT, UNIQUE (id))")
            shared = list(range(600))  # every node draws 3 of each batch's 10 ids from here: a third collide

            def run_node(n):
                rng, seq, out = random.Random(n), 1, []
                for k in range(200):
                    own = [100000 + (n * 200 + k) * 10 + j for j in range(7)]
                    batch = own + rng.sample(shared, 3)
                    rng.shuffle(batch)
                    r = post(ports[n], f"/append/u3?producer=n{n}&seq={seq}", ndjson([{"id": i, "name": f"n{n}"} for i in batch]))
                    if r["status"] == 200:
                        seq += 1  # (a refused batch leaves its seq for the next: the producer's last seq is what committed)
                    out.append((batch, r["status"], r["code"], seq - 1 if r["status"] == 200 else None))
                return out

            with cf.ThreadPoolExecutor(3) as ex:
                results = list(ex.map(run_node, range(3)))
            flat = [b for node in results for b in node]
            went = [b for b in flat if b[1] == 200]
            refused = [b for b in flat if b[1] != 200]
            present = [r["id"] for r in sql(ports[0], "SELECT id FROM u3")]
            ok_ids = {i for b, _, _, _ in went for i in b}
            own_refused = {i for b, _, _, _ in refused for i in b if i >= 100000}
            # (a follower reads what its commit stream has brought: a few ms behind the leader's acks)
            counts = [settle(lambda p=p: sql(p, "SELECT count(*) AS n FROM u3")[0]["n"], len(present)) for p in ports]
            info["race"] = {"batches": len(flat), "went": len(went), "refused": len(refused), "codes": sorted({str(c) for _, s, c, _ in flat if s != 200}),
                            "rows": len(present), "counts": counts}
            checks["three nodes appending at once, 200 batches each, a third of the ids shared: every id in the table once, every refused batch 23505 and out whole, every batch that went in all there"] = \
                all(s in (200, 409) for _, s, _, _ in flat) and all(c in (None, "23505") for _, _, c, _ in flat) and len(refused) > 0 and \
                not any(v > 1 for v in Counter(present).values()) and set(present) == ok_ids and len(present) == 10 * len(went) and not own_refused & set(present) and \
                all(n == len(present) for n in info["race"]["counts"])
            # a retry through another node is a duplicate (the same producer and seq, sent to a follower)
            went_in = next((x for x in reversed(results[1]) if x[1] == 200), None)  # (none on a build that refuses the table)
            if went_in:
                b, _, _, s = went_in
                again = post(ports[2], f"/append/u3?producer=n1&seq={s}", ndjson([{"id": i, "name": "n1"} for i in b]))
            checks["a retry of a batch that went in, sent to another node, is a duplicate, not 23505"] = bool(went_in) and \
                again["status"] == 200 and again["ack"]["duplicate"] is True
            # invariant 29 on a follower: its Flight stream goes to the leader in order, through a refusal
            fl2 = fl.FlightClient(f"grpc://127.0.0.1:{fport + 3}")
            taken = present[0] if present else -1  # (a build that refuses the table has none: the refusal is then a miss)
            f_err_acks, f_err = fput(fl2, ["u3", "fpipe", "1"], [[(900, "x")], [(taken, "x")], [(902, "x")]])
            f_again_acks, f_again = fput(fl2, ["u3", "fpipe", "2"], [[(903, "x")], [(902, "x")]])
            order = settle(lambda: [r["id"] for r in sql(ports[1], "SELECT id FROM u3 WHERE id IN (900, 901, 902, 903) ORDER BY _row_id")], [900, 903, 902])
            info["follower_pipe"] = [len(f_err_acks), f_err, len(f_again_acks), f_again, order]
            checks["a pipelined Flight stream to a follower reaches the leader in order: through a refusal, the batches after it sent again, committed in the order cut"] = \
                f_err is not None and "duplicate key" in f_err and len(f_err_acks) == 1 and f_again is None and len(f_again_acks) == 2 and \
                not any(a.get("duplicate") for a in f_again_acks) and order == [900, 903, 902]
        finally:
            for n in nodes:
                n.kill()

    for part in (one_node, three_nodes):
        try:
            part()
        except Exception as e:  # (a section on a binary without the check records it, and goes on)
            info.setdefault("errors", []).append(f"{part.__name__}: {e!r}"[:600])
    ok = bool(checks) and all(checks.values()) and not info.get("errors")  # (a section that raised fails the run)
    print(json.dumps({"unique_doors": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"{sum(checks.values())} of {len(checks)} unique checks"


def raw_sql(port, q, fmt=None, timeout=900):
    """POST /sql as the wire has it: (status, content type, SQLSTATE header, body bytes)."""
    c = http_client.HTTPConnection("127.0.0.1", port, timeout=timeout)
    c.request("POST", "/sql" + (f"?format={fmt}" if fmt else ""), q.encode())
    r = c.getresponse()
    body = r.read()
    c.close()
    return r.status, r.getheader("content-type"), r.getheader("x-pondra-sqlstate"), body


def vm_hwm(pid):
    """The node's peak resident memory, in bytes (/proc/<pid>/status VmHWM)."""
    for line in open(f"/proc/{pid}/status"):
        if line.startswith("VmHWM:"):
            return int(line.split()[1]) << 10
    return 0


def answers_big():
    """An answer too big to hold as one body is sent in pieces (`server::stream`), and its bytes are
    the whole answer's: a node with PONDRA_STREAM_MB=0 (every answer in pieces) answers what the
    default node does, in JSON, CSV, TSV, NDJSON and Arrow (Arrow as tables). An answer counts in
    the node's query memory (`query::collect`): 3M rows of json over a 0.25 GB node come back whole,
    at a peak at least half their JSON under the same answer's rendered whole (442 MB against 715
    when written); an answer bigger than that memory is refused
    with 53200 and the node answers after. Queries take one of PONDRA_QUERIES' turns: with two turns
    and a second's queue, four slow queries at once answer two at once and refuse the rest with
    53300 (or answer after), and a query run inside a query (PIVOT asks the data) takes no turn of its
    own, so one turn does for it."""
    import pyarrow.compute as pc, pyarrow.csv as pacsv, pyarrow.ipc as paipc
    checks = {}
    # 1. The bytes of a streamed answer are the whole answer's.
    lake = new_lake()
    default = Node(lake, A.port).start()
    streamed = Node(lake, A.port + 1, env={"PONDRA_STREAM_MB": "0"}).start()
    try:
        q = lambda s: sql(A.port, s)
        q("CREATE TABLE t (id BIGINT, s VARCHAR, d DECIMAL(12,2), dt DATE, ts TIMESTAMP, l BIGINT[], f DOUBLE, b BOOLEAN)")
        q("INSERT INTO t SELECT value, CASE WHEN value % 7 = 0 THEN NULL WHEN value % 3 = 0 THEN 'say \"hi\", ' || chr(10) || 'ok' ELSE 'plain ' || value END, "
          "CASE WHEN value % 11 = 0 THEN NULL ELSE CAST(value AS DECIMAL(12,2)) / 7 END, DATE '2020-01-01' + CAST(value % 500 AS INTEGER), "
          "TIMESTAMP '2020-01-01 00:00:00' + value * INTERVAL '1 second', CASE WHEN value % 13 = 0 THEN NULL ELSE make_array(value, value + 1) END, "
          "value / 3.0, value % 2 = 0 FROM generate_series(1, 60000) AS g(value)")
        until(lambda: sql(A.port + 1, "SELECT count(*) AS n FROM t")[0]["n"], 60000)  # (the second node sees every row)
        # (CSV and TSV have no writer for a list column: only the query that reads `l` is refused there)
        queries = {
            "every column but the list": "SELECT id, s, d, dt, ts, f, b FROM t ORDER BY id",
            "nulls and quotes": "SELECT id, s, d, dt FROM t WHERE s IS NULL OR s LIKE '%\"%' OR d IS NULL ORDER BY id",
            "a join's repeated names": "SELECT t.id, t.s, t.d, u.id, u.s, u.ts FROM t JOIN t AS u ON t.id = u.id + 1 WHERE t.id < 20000 ORDER BY t.id",
            "lists, times and bools": "SELECT id, l, f, b, ts FROM t ORDER BY id LIMIT 30000",
            "no rows": "SELECT id, s, d, dt, ts, f, b FROM t WHERE id < 0",
            "one value": "SELECT 1 AS one",
        }
        same, differ, arrow_same, answered = [], [], [], []
        for name, query in queries.items():
            for fmt in (None, "csv", "tsv", "ndjson", "arrow"):
                a, b = raw_sql(A.port, query, fmt), raw_sql(A.port + 1, query, fmt)
                tag = f"{name} as {fmt or 'json'}"
                answered.append((tag, a[0]))
                if fmt == "arrow" and a[0] == 200 and b[0] == 200:
                    ta, tb = paipc.open_stream(a[3]).read_all(), paipc.open_stream(b[3]).read_all()
                    (arrow_same if ta.equals(tb) else differ).append(tag)
                    continue
                (same if (a[0], a[1], a[2], a[3]) == (b[0], b[1], b[2], b[3]) else differ).append(tag)
        checks[f"streamed answers are the whole answers' bytes: {len(same)} of {len(same) + len(differ)} (Arrow as tables: {len(arrow_same)} equal)"] = not differ
        checks[f"…and the answers are there: {sum(1 for _, s in answered if s == 200)} of {len(answered)} with 200"] = all(s == 200 for t, s in answered if not ("lists" in t and ("csv" in t or "tsv" in t)))
        checks["…a streamed answer carries the content type its format has"] = raw_sql(A.port + 1, queries["every column but the list"], "csv")[1].startswith("text/csv") and raw_sql(A.port + 1, queries["every column but the list"], "arrow")[1] == "application/vnd.apache.arrow.stream"
    finally:
        streamed.kill()
        default.kill()

    # 2. A big answer counts in the query memory, and is sent in pieces at a bounded peak.
    lake = new_lake()
    node = Node(lake, A.port + 2).start()
    rows = 3_000_000
    try:
        sql(A.port + 2, "CREATE TABLE big (a BIGINT, b BIGINT, c DOUBLE, s VARCHAR)")
        sql(A.port + 2, f"INSERT INTO big SELECT value, value * 2, value / 4.0, 'row ' || value FROM generate_series(1, {rows}) AS g(value)")
    finally:
        node.kill()
    node = Node(lake, A.port + 2, memory_gb=0.25).start()
    try:
        status, ctype, _, body = raw_sql(A.port + 2, "SELECT * FROM big")
        peak_json, json_size = vm_hwm(node.p.pid), len(body)
        sums = [int(m.group(1)) for m in re.finditer(rb'"a":(\d+)', body)]
        checks[f"a {rows:,}-row answer in json over 0.25 GB: 200, every row ({len(sums):,}, sum of a right: {sum(sums) == rows * (rows + 1) // 2})"] = status == 200 and len(sums) == rows and sum(sums) == rows * (rows + 1) // 2
        arrow_status, _, _, arrow = raw_sql(A.port + 2, "SELECT * FROM big", "arrow")
        del body, sums
        csv_status, _, _, csv_body = raw_sql(A.port + 2, "SELECT * FROM big", "csv")
        read = csv_status == 200 and arrow_status == 200
        t = pacsv.read_csv(io.BytesIO(csv_body)) if read else None
        back = paipc.open_stream(arrow).read_all() if read else None  # (no ORDER BY: rows come in any order, so sums)
        checks[f"…?format=csv ({csv_status}) and arrow ({arrow_status}) read back equal (rows and sums)"] = read and (
            t.num_rows == rows and pc.sum(t.column("a")).as_py() == rows * (rows + 1) // 2 and pc.sum(t.column("b")).as_py() == rows * (rows + 1)
            and back.num_rows == rows and pc.sum(back.column("a")).as_py() == rows * (rows + 1) // 2 and pc.sum(back.column("b")).as_py() == rows * (rows + 1))
        del csv_body, t, arrow
        status, _, code, text = raw_sql(A.port + 2, "SELECT b1.a, b2.a FROM big b1 CROSS JOIN (SELECT a FROM big LIMIT 20) b2")
        checks[f"a 60M-row answer over 0.25 GB: refused with 53200 ({code}) by name: {'the answer is bigger than this node' in text.decode(errors='replace')}"] = status != 200 and code == "53200"
        checks["…and the node answers after: SELECT 1 is 1"] = json.loads(raw_sql(A.port + 2, "SELECT 1 AS one")[3]) == [{"one": 1}]
    finally:
        node.kill()
    # (the same answer rendered whole, as before pieces: its JSON held in memory at once)
    node = Node(lake, A.port + 2, memory_gb=0.25, env={"PONDRA_STREAM_MB": "100000"}).start()
    try:
        status, _, _, body = raw_sql(A.port + 2, "SELECT * FROM big")
        peak_whole = vm_hwm(node.p.pid)
        del body
        checks[f"…in pieces its peak ({peak_json >> 20} MB) is at least half its JSON ({json_size >> 20} MB) under the same answer's rendered whole ({peak_whole >> 20} MB)"] = status == 200 and peak_json + json_size // 2 < peak_whole
    finally:
        node.kill()

    # 3. Turns: PONDRA_QUERIES at once, the rest wait PONDRA_QUEUE_SECS and are refused (53300).
    lake = new_lake()
    node = Node(lake, A.port + 3, env={"PONDRA_QUERIES": "2", "PONDRA_QUEUE_SECS": "0.5"}).start()
    # (seconds each, far past the half second the others wait; each its own text: identical queries
    # share one computation, so one turn)
    slow = "SELECT count(*) AS n FROM generate_series(1, 1000000000) AS g(v) WHERE v % 7 = {}"
    try:
        out, seen = [], []
        def ask(k):
            out.append(raw_sql(A.port + 3, slow.format(k))[::2])  # (status, SQLSTATE)
        threads = [threading.Thread(target=ask, args=(k,)) for k in range(4)]
        [t.start() for t in threads]
        for _ in range(40):
            m = call(A.port + 3, "GET", "/metrics").decode()
            seen.append((int(re.search(r"\npondra_queries_running (\d+)", m).group(1)), int(re.search(r"\npondra_queries_waiting (\d+)", m).group(1))))
            time.sleep(0.025)
        [t.join(300) for t in threads]
        refused = [s for s, c in out if c == "53300"]
        answered = [s for s, c in out if s == 200]
        checks[f"four slow queries at once on two turns: {len(answered)} answered, {len(refused)} refused with 53300 after waiting half a second"] = len(answered) == 2 and len(refused) == 2
        checks["…the running and waiting gauges show two running and some waiting"] = max(r for r, _ in seen) == 2 and max(w for _, w in seen) >= 1
        checks["…and a fifth, simple query after they end answers"] = json.loads(raw_sql(A.port + 3, "SELECT 1 AS one")[3]) == [{"one": 1}]
    finally:
        node.kill()
    lake = new_lake()
    node = Node(lake, A.port + 4, env={"PONDRA_QUERIES": "1", "PONDRA_QUEUE_SECS": "5"}).start()
    try:
        sql(A.port + 4, "CREATE TABLE ev (g VARCHAR, v BIGINT)")
        sql(A.port + 4, "INSERT INTO ev VALUES ('a', 1), ('b', 2), ('a', 3)")
        pivoted = raw_sql(A.port + 4, "PIVOT ev ON g USING sum(v)")
        checks["with one turn, a PIVOT (which asks the data before it runs) answers"] = pivoted[0] == 200 and json.loads(pivoted[3]) == [{"a": 4, "b": 2}]
    finally:
        node.kill()
    for name, good in checks.items():
        print(f"answers_big: {name}: {'OK' if good else 'FAIL'}")
    if not all(checks.values()):
        sys.exit(1)
    return "big answers go in pieces that are the whole's bytes, count in the query memory, and take turns"


def pkey():
    """A table's PRIMARY KEY (`constraints.rs`, `change.rs`): a plain SQL INSERT of a key the table holds
    is refused (23505, Postgres's words) at every SQL door, on one node and on three: HTTP (a follower
    too), the Postgres port, Flight SQL, MCP, `pondra sql` (also with no leader), a procedure and a task.
    Two rows of one key in one INSERT (VALUES and SELECT) are refused whole, and CREATE TABLE … AS SELECT
    with two rows of one key leaves no table. A deleted key is free again (before and after tiering), a
    transaction's COMMIT refuses a key it holds, and an order_by table is keyed too. The upserts keep
    upserting: ON CONFLICT, INSERT OR REPLACE and OR IGNORE, a MERGE's matched rows, /append, COPY FROM
    STDIN and a Kafka produce. A plain INSERT takes its keys' row locks on the leader (`txn::autocommit_as`): two nodes
    inserting the same new key at once, the second waits for the first and is refused (at its INSERT, as
    Postgres does). A transaction's plain INSERT is refused at its statement when the key is held as the
    transaction sees it (its own kept writes count; a SAVEPOINT can roll the refusal back), and COMMIT checks
    again: a change moving a key onto a held one is refused, and a DELETE and an INSERT of one key in one
    transaction keep the new row. An UPDATE of a key column is refused by name (0A000), so a key moves by a
    DELETE and an INSERT. A CREATE TABLE … AS SELECT refused by its key is purged, not kept for UNDROP.
    A MERGE's inserted keys must be new as a plain INSERT's are (23505, on a follower too, and in a
    transaction at COMMIT), though a MERGE matched on the key still updates and inserts; a MERGE that SETs
    a key column is refused by name (0A000)."""
    import psycopg, concurrent.futures as cf, urllib.request
    import adbc_driver_flightsql.dbapi as adbc
    import confluent_kafka as ck
    lake = new_lake()
    P, pg, kport, fport = A.port, A.port + 10, A.port + 20, A.port + 30
    nodes = [Node(lake, P, flight=f"127.0.0.1:{fport}", pg=f"127.0.0.1:{pg}", kafka=f"127.0.0.1:{kport}").start()]
    nodes += [Node(lake, P + i).start() for i in (1, 2)]
    while len(call(P, "GET", "/stats")["nodes"]) < 3:
        time.sleep(0.1)
    q = lambda s, port=P: call(port, "POST", "/sql", s.encode(), timeout=120)
    names = lambda port=P: {r["id"]: r["name"] for r in q("SELECT id, name FROM people", port)}

    def err(s, port=P, path="/sql"):
        """(status, x-pondra-sqlstate, the body's start) of a statement; (200, None, '') when it went in."""
        c = http.client.HTTPConnection("127.0.0.1", port, timeout=120)
        c.request("POST", path, s.encode(), {})
        r = c.getresponse()
        data = r.read().decode()
        c.close()
        return (r.status, r.getheader("x-pondra-sqlstate"), data[:500]) if r.status != 200 else (200, None, "")

    def mcp_write(sql):
        body = json.dumps({"jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {"name": "write", "arguments": {"sql": sql}}}).encode()
        req = urllib.request.Request(f"http://127.0.0.1:{P}/mcp", data=body, headers={"content-type": "application/json"})
        res = json.loads(urllib.request.urlopen(req).read())["result"]
        return res["isError"], res["content"][0]["text"]

    refused = lambda e: e[0] == 409 and e[1] == "23505"  # (409: a duplicate, by its SQLSTATE's class in `codes.rs`)
    dup_words = lambda text: "duplicate key value violates unique constraint" in text
    checks, info = {}, {}

    q("CREATE TABLE people (id BIGINT PRIMARY KEY, name VARCHAR)")
    q("INSERT INTO people VALUES (1, 'ann'), (2, 'bob')")
    # The plain refusal at each door
    http_one = err("INSERT INTO people VALUES (1, 'again')")
    for _ in range(100):  # (the follower checks the keys it has: the commit that made key 2 must have reached it)
        if 2 in names(P + 1):
            break
        time.sleep(0.1)
    http_follower = err("INSERT INTO people VALUES (2, 'again')", P + 1)
    info["http"] = [http_one, http_follower]
    checks["HTTP: a plain INSERT of a key the table holds is refused (23505, people_pkey, Key (id)=(1) already exists), from a follower too"] = \
        refused(http_one) and refused(http_follower) and "people_pkey" in http_one[2] and "Key (id)=(1) already exists" in http_one[2] and names() == {1: "ann", 2: "bob"}
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=u dbname=lake", autocommit=True) as conn:
        try:
            conn.execute("INSERT INTO people VALUES (1, 'pg')")
            pg_err = None
        except psycopg.Error as e:
            pg_err = (e.sqlstate, str(e))
    info["postgres"] = pg_err
    checks["the Postgres port: the same refusal, SQLSTATE 23505 and the same words"] = bool(pg_err) and pg_err[0] == "23505" and "people_pkey" in pg_err[1]
    conn = adbc.connect(f"grpc://127.0.0.1:{fport}", autocommit=True)
    cur = conn.cursor()
    try:
        cur.execute("INSERT INTO people VALUES (1, 'flight')")
        fl_err = None
    except Exception as e:
        fl_err = str(e)
    info["flight_sql"] = fl_err
    checks["Flight SQL (ADBC): the same refusal, with the same words"] = bool(fl_err) and dup_words(fl_err)
    mcp_err, mcp_text = mcp_write("INSERT INTO people VALUES (1, 'mcp')")
    info["mcp"] = [mcp_err, mcp_text[:200]]
    checks["MCP's write tool: the same refusal, with the same words"] = mcp_err and dup_words(mcp_text)
    cli_dup = subprocess.run([BIN, "sql", "--dir", lake, "INSERT INTO people VALUES (1, 'cli')"], capture_output=True, text=True, timeout=120)
    cli_new = subprocess.run([BIN, "sql", "--dir", lake, "INSERT INTO people VALUES (3, 'cli')"], capture_output=True, text=True, timeout=120)
    info["cli"] = [cli_dup.returncode, cli_dup.stderr[-200:], cli_new.returncode]
    checks["pondra sql: refused by the same words (exit 1); a new key goes in"] = cli_dup.returncode != 0 and dup_words(cli_dup.stderr) and cli_new.returncode == 0 and names()[3] == "cli"
    q("CREATE PROCEDURE add_person(i BIGINT, n VARCHAR) LANGUAGE sql AS $$ INSERT INTO people VALUES ($i, $n) $$")
    proc_dup = err("CALL add_person(1, 'proc')")
    q("CALL add_person(4, 'proc')")
    info["procedure"] = proc_dup
    checks["inside a procedure: the same refusal (23505); the procedure's new key goes in"] = refused(proc_dup) and dup_words(proc_dup[2]) and names()[4] == "proc"
    q("CREATE TASK pk_tick SCHEDULE '1 second' AS INSERT INTO people VALUES (1, 'task')")
    failed = []
    for _ in range(100):  # (a tick a second: its failed run within 30 s)
        failed = q("SELECT status, error FROM pondra.runs WHERE routine = 'pk_tick' AND status = 'failed' LIMIT 1")
        if failed:
            break
        time.sleep(0.3)
    q("DROP TASK pk_tick")
    info["task"] = failed
    checks["inside a task: each tick is refused the same way (its run is failed, with the words); the row stays as it was"] = \
        bool(failed) and dup_words(failed[0]["error"]) and names()[1] == "ann"

    # Two rows of one key in one INSERT: refused whole
    two_values = err("INSERT INTO people VALUES (5, 'x'), (5, 'y')")
    q("CREATE TABLE src_dup (k BIGINT, n VARCHAR)")
    q("INSERT INTO src_dup VALUES (7, 'a'), (7, 'b'), (8, 'c')")
    two_select = err("INSERT INTO people SELECT k, n FROM src_dup")
    info["two_in_one"] = [two_values, two_select]
    checks["two rows of one key in one INSERT (VALUES, or SELECT): 23505, and nothing of the statement lands"] = \
        refused(two_values) and refused(two_select) and not {5, 7, 8} & set(names())

    # The upserts keep upserting
    q("INSERT INTO people VALUES (1, 'ann pro') ON CONFLICT (id) DO UPDATE SET name = excluded.name")
    q("INSERT INTO people VALUES (2, 'lost') ON CONFLICT (id) DO NOTHING")
    q("INSERT OR REPLACE INTO people VALUES (2, 'bob v2')")
    q("INSERT OR IGNORE INTO people VALUES (1, 'ignored')")
    q("MERGE INTO people t USING (SELECT 1 AS id, 'merged' AS name) s ON t.id = s.id WHEN MATCHED THEN UPDATE SET name = s.name")
    got = names()
    info["upserts"] = got
    checks["ON CONFLICT DO UPDATE and DO NOTHING, INSERT OR REPLACE and OR IGNORE, MERGE still upsert"] = got[1] == "merged" and got[2] == "bob v2"

    # A MERGE's inserted keys must be new, as a plain INSERT's are (`change::run`): one that matches on another column looks
    # each inserted key up, one that matches on the key alone, in the key's own type, checks its own new rows. A MERGE
    # matched on the key still updates and inserts (dbt's shape), and a SET of a key column is refused by name (0A000).
    q("CREATE TABLE mrg (id BIGINT PRIMARY KEY, v VARCHAR)")
    q("INSERT INTO mrg VALUES (7001, 'a'), (7002, 'b'), (7003, 'c')")
    mrg_rows = lambda port=P: {r["id"]: r["v"] for r in q("SELECT id, v FROM mrg", port)}
    for _ in range(100):  # (the follower sees the table and its rows once the commit reaches it)
        if set(mrg_rows(P + 1)) == {7001, 7002, 7003}:
            break
        time.sleep(0.1)
    mrg_before = mrg_rows()
    mrg_v = err("MERGE INTO mrg t USING (SELECT 7002 AS id, 'zz' AS v) s ON t.v = s.v WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.v)")
    mrg_follower = err("MERGE INTO mrg t USING (SELECT 7003 AS id, 'mm' AS v) s ON t.v = s.v WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.v)", P + 1)
    mrg_two = err("MERGE INTO mrg t USING (SELECT 7004 AS id, 'p' AS v UNION ALL SELECT 7004, 'q') s ON t.id = s.id WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.v)")
    mrg_conflict = err("INSERT INTO mrg VALUES (7003, 'yy') ON CONFLICT (v) DO NOTHING")
    mrg_after_refusals = mrg_rows()
    info["merge_inserts"] = [mrg_v, mrg_follower, mrg_two, mrg_conflict, mrg_after_refusals]
    checks["a MERGE that inserts a key the table holds is refused (23505) and changes no row: matched on another column (on a follower too), two source rows of one new key, ON CONFLICT on another column"] = \
        refused(mrg_v) and refused(mrg_follower) and refused(mrg_two) and refused(mrg_conflict) and mrg_after_refusals == mrg_before == {7001: "a", 7002: "b", 7003: "c"}

    # In a transaction the MERGE's insert is refused at COMMIT (its statement can't see the key it writes): the row stays
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=u dbname=lake", autocommit=True) as conn:
        cur = conn.cursor()
        cur.execute("BEGIN")
        try:
            cur.execute("MERGE INTO mrg t USING (SELECT 7002 AS id, 'tt' AS v) s ON t.v = s.v WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.v)")
            cur.execute("COMMIT")
            mrg_txn = None
        except psycopg.Error as e:
            mrg_txn = e.sqlstate  # (the transaction is over: nothing to roll back)
    info["merge_txn"] = [mrg_txn, mrg_rows().get(7002)]
    checks["a MERGE in a transaction that inserts a key the table holds: refused (23505), and the row is as it was"] = mrg_txn == "23505" and mrg_rows()[7002] == "b"

    # A key the ON compares in another type: 7002.5 against BIGINT's keys compares as decimals and matches no row, yet the
    # inserted value is cast to the key's type (7003, rounded as Postgres casts it), a row that's there. Such a MERGE is
    # checked by lookups.
    mrg_dec = err("MERGE INTO mrg t USING (SELECT 7002.5 AS id, 'y' AS v) s ON t.id = s.id WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.v)")
    info["merge_decimal"] = [mrg_dec, mrg_rows()]
    # An INSERT's value is cast to the key's type before its conflict is checked (as Postgres does): 7002.5 is the key 7003,
    # which is held, so DO NOTHING keeps its row.
    ins_nothing = err("INSERT INTO mrg SELECT 7002.5 AS id, 'y' AS v ON CONFLICT (id) DO NOTHING")
    info["merge_decimal_nothing"] = [ins_nothing, mrg_rows()]
    checks["a MERGE that compares a key in another type (7002.5 against BIGINT) and inserts it: refused (23505), the table as it was; an INSERT of 7002.5 ON CONFLICT DO NOTHING keeps 7003"] = \
        refused(mrg_dec) and "(id)=(7003)" in str(mrg_dec) and mrg_rows() == {7001: "a", 7002: "b", 7003: "c"} and ins_nothing[0] == 200

    mrg_dbt = q("MERGE INTO mrg t USING (SELECT 7001 AS id, 'a2' AS v UNION ALL SELECT 7005, 'e') s ON t.id = s.id WHEN MATCHED THEN UPDATE SET v = s.v WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.v)")
    mrg_key_set = err("MERGE INTO mrg t USING (SELECT 7001 AS id) s ON t.id = s.id WHEN MATCHED THEN UPDATE SET id = 7009")
    info["merge_dbt"] = [mrg_dbt, mrg_key_set, mrg_rows()]
    checks["a MERGE matched on the key updates and inserts (dbt's shape); a SET of the key is refused by name (0A000), the table unchanged"] = \
        mrg_rows() == {7001: "a2", 7002: "b", 7003: "c", 7005: "e"} and mrg_key_set[1] == "0A000" and mrg_rows()[7001] == "a2"

    # An INSERT of 7002.5 with ON CONFLICT DO UPDATE takes the cast key too: it updates 7003 (counted as updated), no row is inserted
    ins_update = q("INSERT INTO mrg VALUES (7002.5, 'u') ON CONFLICT (id) DO UPDATE SET v = excluded.v")
    info["merge_decimal_update"] = [ins_update, mrg_rows()]
    checks["an INSERT of 7002.5 with ON CONFLICT DO UPDATE updates 7003 (counted as updated, none inserted), the other rows as they were"] = \
        ins_update.get("updated") == 1 and ins_update.get("inserted") == 0 and mrg_rows() == {7001: "a2", 7002: "b", 7003: "u", 7005: "e"}

    # Loading doors: still upserts
    post = err('{"id": 1, "name": "append"}\n', P, "/append/people")
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=u dbname=lake", autocommit=True) as conn:
        with conn.cursor().copy("COPY people FROM STDIN") as cp:
            cp.write("1\tcopy\n")
    kp = ck.Producer({"bootstrap.servers": f"127.0.0.1:{kport}", "enable.idempotence": True, "linger.ms": 50, "message.timeout.ms": 20000})
    kafka_errs = []
    kp.produce("people", value=json.dumps({"id": 1, "name": "kafka"}), on_delivery=lambda e, m: kafka_errs.append(e and e.name()))
    kp.flush(30)
    info["loaders"] = [post, kafka_errs]
    checks["/append, COPY FROM STDIN and a Kafka produce still upsert a key the table holds (each goes in)"] = \
        post[0] == 200 and kafka_errs == [None] and names()[1] == "kafka"

    # A deleted key is free again, before and after tiering
    q("DELETE FROM people WHERE id = 2")
    gone = names()
    q("INSERT INTO people VALUES (2, 'back')")
    q("DELETE FROM people WHERE id = 1")
    call(P, "POST", "/tier", timeout=600)
    q("INSERT INTO people VALUES (1, 'after tiering')")
    info["deleted"] = [gone, names()]
    checks["a deleted key can be inserted again, its delete marker in the log or tiered into files"] = 2 not in gone and names()[2] == "back" and names()[1] == "after tiering"

    # A retried job (the same job id, after a lost answer): its plain INSERT is a duplicate, not a refusal
    def mcp_job(sql, job):
        body = json.dumps({"jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {"name": "write", "arguments": {"sql": sql, "job": job}}}).encode()
        req = urllib.request.Request(f"http://127.0.0.1:{P}/mcp", data=body, headers={"content-type": "application/json"})
        res = json.loads(urllib.request.urlopen(req).read())["result"]
        return res["isError"], res["content"][0]["text"]
    job_first = mcp_job("INSERT INTO people VALUES (400, 'job')", "pk-job-400")
    job_again = mcp_job("INSERT INTO people VALUES (400, 'job')", "pk-job-400")
    info["retried_job"] = [job_first, job_again]
    checks["a retried job's plain INSERT answers duplicate, not 23505 (its own row holds the key); its row goes in once"] = \
        job_first[0] is False and job_again[0] is False and "duplicate" in job_again[1] and names().get(400) == "job"

    # Two nodes, the leader (P, started first) and a follower (P + 1), insert the same 50 new keys at once: one INSERT per key per
    # node, both statements started together. A plain INSERT takes its keys' row locks on the leader, so the second waits for the
    # first to commit and is then refused (23505): exactly one of each pair goes in, each key holds one row, and its value is its
    # winner's.
    roles = (call(P, "GET", "/stats")["role"], call(P + 1, "GET", "/stats")["role"])
    def race(k):
        start = threading.Barrier(2)
        def go(port):
            start.wait()
            return err(f"INSERT INTO people VALUES ({k}, 'race{port}')", port)
        with cf.ThreadPoolExecutor(2) as ex:
            return dict(zip((P, P + 1), ex.map(go, (P, P + 1))))
    races = {k: race(k) for k in range(1000, 1050)}
    winners = {k: [port for port, r in outcome.items() if r[0] == 200] for k, outcome in races.items()}
    refusals = [r for outcome in races.values() for r in outcome.values() if r[0] != 200]
    counted = q("SELECT count(*) AS n, count(DISTINCT id) AS d FROM people WHERE id BETWEEN 1000 AND 1049")[0]
    got = names()
    info["race"] = [roles, sum(len(w) for w in winners.values()), len(refusals), sorted({r[1] for r in refusals}), counted]
    checks["two nodes (the leader and a follower) inserting the same 50 new keys at once: exactly 50 go in and 50 are refused (23505); each key holds one row, and its value is its winner's"] = \
        roles == ("leader", "follower") and all(len(w) == 1 for w in winners.values()) and len(refusals) == 50 and all(refused(r) for r in refusals) \
        and counted == {"n": 50, "d": 50} and all(got[k] == f"race{winners[k][0]}" for k in races)

    # A change's keys at COMMIT (`constraints::key_check`, with the change's old rows): a change moving a
    # key onto one the table holds is refused; a swap of two keys, a key the transaction deleted or
    # replaced, an upsert of a held key and a key a change moves away all commit; a plain INSERT of a
    # key the transaction inserted earlier, or one the table holds, is refused at its statement (23505)
    q("CREATE TABLE moves (id BIGINT PRIMARY KEY, n VARCHAR)")
    q("INSERT INTO moves VALUES (1, 'a'), (2, 'b'), (3, 'c'), (5, 'e')")

    def txn(*stmts):
        """The statements in one transaction over the Postgres port: None, or (SQLSTATE, where it failed)."""
        with psycopg.connect(f"host=127.0.0.1 port={pg} user=u dbname=lake", autocommit=True) as conn:
            cur = conn.cursor()
            cur.execute("BEGIN")
            try:
                for s in stmts:
                    cur.execute(s)
            except psycopg.Error as e:
                return (e.sqlstate, "statement")
            try:
                cur.execute("COMMIT")
            except psycopg.Error as e:
                return (e.sqlstate, "commit")
            return None

    mv = lambda: {r["id"]: r["n"] for r in q("SELECT id, n FROM moves")}
    moved_onto = txn("UPDATE moves SET id = 2 WHERE id = 1")  # (an UPDATE of a key column: refused by name, 0A000)
    swap = txn("UPDATE moves SET id = 3 - id WHERE id IN (1, 2)")
    swapped = mv()
    deleted_then_inserted = txn("DELETE FROM moves WHERE id = 3", "INSERT INTO moves VALUES (3, 'again')")
    twice_in_txn = txn("INSERT INTO moves VALUES (7, 'x')", "INSERT INTO moves VALUES (7, 'y')")
    replaced = txn("INSERT OR REPLACE INTO moves VALUES (5, 'replaced')")
    conflicted = txn("INSERT INTO moves VALUES (5, 'conflict') ON CONFLICT (id) DO UPDATE SET n = excluded.n")
    held_plain = txn("INSERT INTO moves VALUES (5, 'held')")
    freed = txn("UPDATE moves SET id = 10 WHERE id = 5")
    final = mv()
    info["moves"] = [moved_onto, swap, swapped, deleted_then_inserted, twice_in_txn, replaced, conflicted, held_plain, freed, final]
    checks["an UPDATE of a key column (a move, a swap) is refused by name (0A000); a key the transaction deleted and inserted again, an upsert of a held key commit; a plain INSERT of a held key, or of a key the transaction inserted earlier, is refused at its statement (23505)"] = \
        moved_onto == ("0A000", "statement") and swap == ("0A000", "statement") and deleted_then_inserted is None and twice_in_txn == ("23505", "statement") \
        and replaced is None and conflicted is None and held_plain == ("23505", "statement") and freed == ("0A000", "statement") \
        and final == {1: "a", 2: "b", 3: "again", 5: "conflict"}

    # Two transactions inserting the same new key: the second's INSERT waits for the first to commit (its row lock), and its
    # COMMIT is refused (23505) at the check; one row stays, the first's
    first, second = psycopg.connect(f"host=127.0.0.1 port={pg} user=u dbname=lake", autocommit=True), psycopg.connect(f"host=127.0.0.1 port={pg} user=u dbname=lake", autocommit=True)
    c1, c2 = first.cursor(), second.cursor()
    c1.execute("BEGIN")
    c1.execute("INSERT INTO people VALUES (1500, 'first')")
    c2.execute("BEGIN")
    waited = {}
    def second_insert():
        try:
            c2.execute("INSERT INTO people VALUES (1500, 'second')")
            waited["ok"] = True
        except psycopg.Error as e:
            waited["err"] = e.sqlstate
    t = threading.Thread(target=second_insert)
    t.start()
    t.join(1.5)
    blocked = t.is_alive()  # (still waiting on the first transaction's lock)
    c1.execute("COMMIT")
    t.join(60)
    waited_err = waited.get("err")  # (the second INSERT was refused at its statement: the key the first committed is held)
    try:
        c2.execute("SELECT 1")  # (the refused INSERT failed the second transaction: its next statement is refused too)
        after_refusal = None
    except psycopg.Error as e:
        after_refusal = e.sqlstate
    try:
        c2.execute("COMMIT")  # (a failed transaction's COMMIT is its ROLLBACK, which is no error)
        second_commit = None
    except psycopg.Error as e:
        second_commit = e.sqlstate
    first.close()
    second.close()
    info["two_txns"] = [blocked, waited, after_refusal, second_commit, names().get(1500)]
    checks["two transactions inserting one new key: the second's INSERT waits for the first to commit, and is refused at that INSERT (23505); its next statement is 25P02; the first's row stays"] = \
        blocked and waited_err == "23505" and after_refusal == "25P02" and second_commit is None and names().get(1500) == "first"

    # A DELETE and an INSERT of one key in one transaction: the key has the new row (its delete marker doesn't shadow it)
    q("INSERT INTO people VALUES (1600, 'old')")
    delete_insert = txn("DELETE FROM people WHERE id = 1600", "INSERT INTO people VALUES (1600, 'new')")
    info["delete_insert"] = [delete_insert, names().get(1600)]
    checks["DELETE then INSERT of one key in one transaction, COMMIT: the key has the new row"] = delete_insert is None and names().get(1600) == "new"

    # A SAVEPOINT rolls back a refused INSERT, as the programs that retry an insert on a key need (Django's get_or_create):
    # the INSERT of a held key is refused at its statement, ROLLBACK TO SAVEPOINT clears the failure, and the next INSERT
    # goes in. Only the new key's row lands.
    before_sp = names().get(1)
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=u dbname=lake", autocommit=True) as conn:
        cur = conn.cursor()
        cur.execute("BEGIN")
        cur.execute("SAVEPOINT s")
        try:
            cur.execute("INSERT INTO people VALUES (1, 'savepoint')")  # (key 1 is held)
            sp_refused = None
        except psycopg.Error as e:
            sp_refused = e.sqlstate
        cur.execute("ROLLBACK TO SAVEPOINT s")
        cur.execute("INSERT INTO people VALUES (1700, 'after savepoint')")
        cur.execute("COMMIT")
    info["savepoint"] = [sp_refused, before_sp, names().get(1), names().get(1700)]
    checks["BEGIN, SAVEPOINT, a plain INSERT of a held key refused at the INSERT (23505), ROLLBACK TO SAVEPOINT, a new key's INSERT, COMMIT: only the new key's row lands"] = \
        sp_refused == "23505" and names().get(1) == before_sp and names().get(1700) == "after savepoint"

    # A bulk INSERT … SELECT of new keys (past 1,000 keys: one query over the table, not a lookup each)
    # and a VALUES with several keys: a held key among them refuses the whole statement
    q("CREATE TABLE bulk (id BIGINT PRIMARY KEY, n VARCHAR)")
    q("INSERT INTO bulk SELECT x AS id, 'a' AS n FROM generate_series(1, 5000) t(x)")
    bulk_held = err("INSERT INTO bulk SELECT x AS id, 'b' AS n FROM generate_series(4990, 6000) t(x)")
    bulk_values = err("INSERT INTO bulk VALUES (6001, 'x'), (1, 'x'), (9999, 'x')")
    bulk_free = err("INSERT INTO bulk SELECT x AS id, 'c' AS n FROM generate_series(5001, 6000) t(x)")
    bulk_rows = q("SELECT count(*) AS n FROM bulk")
    info["bulk"] = [bulk_held, bulk_values, bulk_free, bulk_rows]
    checks["a bulk INSERT … SELECT with a held key among 1,010 keys, and a VALUES with one among three: each refused whole (23505); 1,000 new keys go in"] = \
        refused(bulk_held) and refused(bulk_values) and bulk_free[0] == 200 and bulk_rows == [{"n": 6000}]

    # An attached lake's keyed table: its plain INSERT is checked here, where its rows are, then its leader records them
    shop = new_lake()
    nodes.append(Node(shop, P + 6).start())
    q("CREATE TABLE stock (id BIGINT PRIMARY KEY, qty BIGINT)", P + 6)
    q("INSERT INTO stock VALUES (1, 100)", P + 6)
    q(f"ATTACH '{shop}' AS shop")
    attached_held = err("INSERT INTO shop.stock VALUES (1, 5)")
    attached_new = err("INSERT INTO shop.stock VALUES (2, 5)")
    info["attached"] = [attached_held, attached_new]
    checks["an attached lake's keyed table: a plain INSERT of a key it holds is refused (23505); a new key goes in and reads back"] = \
        refused(attached_held) and attached_new[0] == 200 and q("SELECT qty FROM shop.stock WHERE id = 2") == [{"qty": 5}]

    # A transaction: its INSERT of a key the table holds is refused at the statement (23505), and the transaction keeps nothing of it
    with psycopg.connect(f"host=127.0.0.1 port={pg} user=u dbname=lake", autocommit=True) as conn:
        cur = conn.cursor()
        cur.execute("BEGIN")
        cur.execute("INSERT INTO people VALUES (300, 'txn')")
        try:
            cur.execute("INSERT INTO people VALUES (1, 'txn dup')")
            txn = None
        except psycopg.Error as e:
            txn = e.sqlstate
        cur.execute("ROLLBACK")  # (the refused statement failed the transaction: it ends here)
        cur.execute("BEGIN")
        cur.execute("INSERT INTO people VALUES (302, 'txn ok')")
        cur.execute("COMMIT")
    info["txn"] = txn
    checks["a transaction whose INSERT takes a key the table holds: the INSERT is refused at its statement (23505), the transaction keeps nothing of it, and a clean one commits"] = \
        txn == "23505" and 300 not in names() and names().get(302) == "txn ok"

    # order_by: a keyed table, its plain INSERT refused whatever the event time
    q("CREATE TABLE events (id BIGINT PRIMARY KEY, ts BIGINT, v VARCHAR) WITH (order_by = 'ts')")
    q("INSERT INTO events VALUES (1, 10, 'a')")
    ev_plain = err("INSERT INTO events VALUES (1, 5, 'older')")
    q("INSERT OR REPLACE INTO events VALUES (1, 5, 'older upsert')")
    ev_after_older = q("SELECT v FROM events WHERE id = 1")
    q("INSERT OR REPLACE INTO events VALUES (1, 20, 'newer')")
    info["order_by"] = [ev_plain, ev_after_older]
    checks["an order_by table is keyed too: a plain INSERT of a key it holds is refused whatever its time; an upsert keeps the latest time"] = \
        refused(ev_plain) and ev_after_older == [{"v": "a"}] and q("SELECT v FROM events WHERE id = 1") == [{"v": "newer"}]

    # CREATE TABLE … AS SELECT with a key: two rows of one key leave no table
    ctas = q("CREATE TABLE people_copy (id BIGINT PRIMARY KEY, n VARCHAR) AS SELECT id, name AS n FROM people")
    ctas_dup = err("CREATE TABLE dup_copy (id BIGINT PRIMARY KEY, n VARCHAR) AS SELECT k, n FROM src_dup")
    no_table = err("SELECT count(*) AS n FROM dup_copy")
    # The table it refused never held a row, so it is purged: not kept for UNDROP. An ordinary DROP is kept (the control).
    q("CREATE TABLE kept_control (id BIGINT)")
    q("DROP TABLE kept_control")
    undrop_control = err("UNDROP TABLE kept_control")
    undrop_dup = err("UNDROP TABLE dup_copy")
    info["ctas"] = [ctas, ctas_dup, no_table, undrop_control[0], undrop_dup]
    checks["CREATE TABLE … PRIMARY KEY AS SELECT: a key's rows once go in; two rows of one key are refused (23505) and the table isn't left behind, nor kept for UNDROP (an ordinary DROP is: the control)"] = \
        q("SELECT count(*) AS n FROM people_copy") == q("SELECT count(*) AS n FROM people") and refused(ctas_dup) and no_table[0] == 404 \
        and undrop_control[0] == 200 and undrop_dup[0] != 200

    # pondra sql with no leader: it leads for a moment, and refuses the same way
    for n in nodes:
        n.kill()
    led_dup = subprocess.run([BIN, "sql", "--dir", lake, "INSERT INTO people VALUES (1, 'nobody leads')"], capture_output=True, text=True, timeout=120)
    led_new = subprocess.run([BIN, "sql", "--dir", lake, "INSERT INTO people VALUES (900, 'nobody leads')"], capture_output=True, text=True, timeout=120)
    read = subprocess.run([BIN, "sql", "--dir", lake, "SELECT name FROM people WHERE id = 900"], capture_output=True, text=True, timeout=120)
    info["no_leader"] = [led_dup.returncode, led_dup.stderr[-200:], led_new.returncode, read.stdout[-200:]]
    checks["pondra sql with no leader running: refused by the same words; a new key goes in and reads back"] = \
        led_dup.returncode != 0 and dup_words(led_dup.stderr) and led_new.returncode == 0 and "nobody leads" in read.stdout

    ok = all(checks.values())
    print(json.dumps({"pkey": checks, "ok": ok, "info": info}, indent=1, default=str))
    if not ok:
        sys.exit(1)
    return f"{sum(checks.values())} of {len(checks)} PRIMARY KEY checks"


# About how long each section of `all` takes, in seconds, on a machine like CI's runners (`all`
# prints each one's time as it goes): `--shard K/N` deals the sections out by it, so CI runs the
# suite in parts side by side that end together. A section not listed counts as 5 s.
SECS = {"memory": 255, "cursors": 15, "prepared": 15, "owned": 20, "signed": 20, "sso": 83, "sso_flow": 15, "guesses": 30, "stopped": 78, "clouds": 66, "functions": 50, "server": 43, "crash": 36, "across": 33, "serverless": 32, "kafkas": 29, "finals": 29,
        "found": 26, "alter": 24, "outside": 20, "load": 20, "loads": 30, "kafka": 19, "live": 19, "clusters": 17, "scale": 16, "guard": 15, "workspace": 15,
        "users": 15, "find": 15, "measures": 120, "facts": 90, "sealed": 60, "procedures": 14, "reader": 14, "schemas": 13, "followers": 13, "clients": 12, "files": 12, "ids": 12, "history": 12,
        "learn": 12, "upsert": 11, "sessions": 11, "objects": 11, "columns": 10, "catalogs": 12, "attached": 10, "use_path": 40, "first": 30, "answers_big": 15, "dialects": 20, "ddlgaps": 40, "sqla": 30, "unique_doors": 60, "pkey": 60}


def all_tests():
    A.runs, A.batches = min(A.runs, 5), min(A.batches, 30)
    sections = (upsert, deal, outside, catalogs, clouds, kafkas, tiering, tails, pace, memory, fence, insert, serverless, clients, kafka, alter, windows, sessions, finals, finishes, bykey, refreshed, asof, sums, schemas, changes, guard, files, layouts, clusters, copies, streams, columns, fills, dedup, procedures, functions, external, names, answers, answers_big, writes, adopted, ids, rewrites, followers, transactions, upserts, live, temps, across, attached, found, renames, workspace, server, scale, flight, first, users, secrets, sealed, safety, guarded, reached, owned, signed, guesses, sso, sso_flow, versions, stopped, flows, begin, doors, cursors, prepared, returning, objects, registry, find, measures, facts, sequences, constraints, ddlgaps, sqla, enums, uuids, colnames, bi, remembered, sparksql, variables, use_path, scripts, hot, minmax, history, plans, learn, friendly, dialects, publishing, backpressure, loads, reader, crash, load, unique_doors, waits, pkey)
    k, n = (int(x) for x in A.shard.split("/"))
    if not 1 <= k <= n:
        sys.exit(f"--shard {A.shard}: K/N, with K from 1 to N")
    out = {}
    for t in shard(sections, k, n):
        if t is load:
            A.secs = min(A.secs, 20)
        t0 = time.time()
        out[t.__name__] = t()
        print(f"harness all: {t.__name__} took {time.time() - t0:.0f} s", file=sys.stderr, flush=True)
    print(json.dumps(out, indent=1))
    # (a section that answers False failed: it printed its checks and went on, so the rest still run)
    failed = [name for name, r in out.items() if r is False]
    if failed:
        sys.exit(f"harness all: failed: {', '.join(failed)}")


def shard(sections, k, n):
    """The k-th of n shares of `sections`, in their own order: each section, longest first, goes to
    the share with the least time so far (SECS), so the shares take about as long."""
    sums, mine = [0] * n, set()
    for t in sorted(sections, key=lambda t: -SECS.get(t.__name__, 5)):
        i = sums.index(min(sums))
        sums[i] += SECS.get(t.__name__, 5)
        if i == k - 1:
            mine.add(t)
    return [t for t in sections if t in mine]


